a_os/windows/api/安全加载dll.content:
概述：如何安全加载dll文件，防止 dll 替换


C++cpp__inline HMODULE WINAPI LoadLibraryEx_api(LPCTSTR lpFileName, HANDLE hFile, DWORD dwFlags)
{
	return ::LoadLibraryEx(lpFileName, hFile, dwFlags);
}
//安全版LoadLibrary_api，可以降低dll劫持的可能性
HMODULE WINAPI LoadLibrary_api_s(LPCTSTR lpFileName)
{
#ifdef __360PubDLLSafeInitHelper
	/*
	当使用 S360时，我们优先使用 S360 提供是 DLL 安全加载。
	这是因为 S360 提供的LoadLibraryFormSystem32能为Windows XP以及其他所有没有安装 KB2533623 的系统提供 LOAD_LIBRARY_SEARCH_SYSTEM32 特性。
	提升不支持 LOAD_LIBRARY_SEARCH_SYSTEM32 特性系统中的安全性。
	*/
	return S360::Helper::LoadLibraryFormSystem32(lpFileName);
#elif defined _M_IX86 || defined _M_AMD64 || defined _M_IA64
	/*
	docs.microsoft.com/zh-cn/windows/desktop/api/libloaderapi/nf-libloaderapi-loadlibraryexa
	Windows 7, Windows Server 2008 R2, Windows Vista and Windows Server 2008:
	The LOAD_LIBRARY_SEARCH_ flags are available on systems that have KB2533623 installed.
	To determine whether the flags are available, use GetProcAddress to get the address of
	the AddDllDirectory, RemoveDllDirectory, or SetDefaultDllDirectories function.
	If GetProcAddress succeeds, the LOAD_LIBRARY_SEARCH_ flags can be used with LoadLibraryEx.
	*/
	//不再使用ERROR_INVALID_PARAMETER判断，规避联想一键影音导致的Hook Bug。
	static int bSafeLoadAvailable = 0;

	if (bSafeLoadAvailable == 0)
	{
		//此处不考虑线程安全，因为多执行一次 GetProcAddress 操作没什么大不了的。
		bSafeLoadAvailable = GetProcAddress(GetModuleHandleW(L&quot;Kernel32.dll&quot;), &quot;AddDllDirectory&quot;) != NULL ? 1 : -1;
	}

	//尝试使用DLL安全初始化
	return LoadLibraryEx_api(lpFileName, NULL, bSafeLoadAvailable == 1 ? /*LOAD_LIBRARY_SEARCH_SYSTEM32*/0x00000800 : 0);
#else // ARM || ARM64
	//始终使用DLL安全初始化
	return LoadLibraryEx_api(lpFileName, NULL, /*LOAD_LIBRARY_SEARCH_SYSTEM32*/0x00000800);
#endif
}

a_os/windows/api/弹出u盘.content:
概述：Win7 弹出U盘的方式汇总


参考文章：

How to Prepare a USB Drive for Safe Removal - CodeProject
参考代码：
balena-io-modules/mountutils: Cross platform mount related utilities
imdisk/cli/imdisk.c at 3f4672f83f02d18230bc1d47eb4617d106cc922c · dindinw/imdisk

问题描述

用户环境：Windows 7 x64 旗舰版

客户反馈使用 [U盘小助手] 弹出U盘时报错。弹出失败，每次都需要强制弹出才能弹出U盘，且强制弹出后 [Explorer] 界面仍会显示 U盘 对应的磁盘（没有容量）。但是使用系统的弹出是可以弹出的，且U盘图标弹出逻辑也正常。


异常情况就是上述两者发生：

排查思路
句柄未关闭
排查是否有未关闭的句柄导致弹出失败。具体就是使用 [Process Explorer] 查找 [U盘] 句柄。
被拦截

查看系统日志
查看 API 调用

查看代码
如果以上均排查不出来问题，那就只能看是不是代码写的有问题了。
以上只是常见的排查思路，具体问题具体分析。
弹出调用失败
代码中调用弹出的接口是 CM_Request_Device_Eject_Ex
问题原因
驱动问题，调用 CM_Request_Device_Eject_Ex 弹出时 pVetoType 返回 PNP_VetoIllegalDeviceRequest，表示当前设备不支持。这个在别的机器上是无法复现，截止目前我也不知道这个问题的根源是什么。只能通过别的方式弹出。
目前看只有 CM_Request_Device_Eject_Ex 才能从设备管理器界面弹出U盘。
C++cppCMAPI
CONFIGRET
WINAPI
CM_Request_Device_Eject_ExW(
    _In_  DEVINST       dnDevInst,
    _Out_opt_ PPNP_VETO_TYPE pVetoType,
    _Out_writes_opt_(ulNameLength) LPWSTR pszVetoName,
    _In_  ULONG         ulNameLength,
    _In_  ULONG         ulFlags,
    _In_opt_ HMACHINE   hMachine
    );
当 CM_Request_Device_Eject_Ex 接口不支持调用时，常见的方式就是调用 DeviceIOControl 来强制弹出U盘。示例代码如下所示：
C++cppSTDAPI_(BOOL) EjectVolumeForce(DWORD dwVolLetter)
{
	MYTRACE(L&quot;Enter EjectVolumeForce&quot;);

	WCHAR wszVolume[20] = {};
	WCHAR  wszVolShort[20] = {};
	DWORD dwReturn = 0;
	HANDLE hVolume = INVALID_HANDLE_VALUE;
	BOOL bRet = FALSE;

	StringCchPrintf(wszVolShort, ARRAYSIZE(wszVolShort), L&quot;%c:\\&quot;, dwVolLetter);
	StringCchPrintf(wszVolume, ARRAYSIZE(wszVolume), L&quot;\\\\.\\%c:&quot;, dwVolLetter);

	hVolume = CreateFile(wszVolume, GENERIC_READ, FILE_SHARE_WRITE | FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL);
	if (hVolume == INVALID_HANDLE_VALUE)
	{
		MYTRACE(L&quot;ERROR! Can not open volume!\n&quot;);
		return FALSE;
	}
	do
	{
		// 硬盘强制弹出失败率大
		if (DRIVE_FIXED == GetDriveType(wszVolShort))
		{
			MYTRACE(L&quot;DRIVE_FIXED == GetDriveType(wszVolShort)&quot;);
			bRet = FALSE;
			break;
		}
		MYTRACE(L&quot;GetDriveType(wszVolShort) == %d&quot;, GetDriveType(wszVolShort));

		// 开始暴力弹出
		if (DeviceIoControl(hVolume, FSCTL_DISMOUNT_VOLUME, NULL, 0, NULL, 0, &amp;dwReturn, NULL))
		{
			DWORD dwTmp = 0;
			MYTRACE(L&quot;IOCTL_STORAGE_MEDIA_REMOVAL&quot;);
			bRet = DeviceIoControl(hVolume, IOCTL_STORAGE_MEDIA_REMOVAL, &amp;dwTmp, sizeof(dwTmp), NULL, 0, &amp;dwReturn, NULL);
			MYTRACE(L&quot;IOCTL_STORAGE_MEDIA_REMOVAL, bRet==%d&quot;, bRet);
			bRet = DeviceIoControl(hVolume, IOCTL_DISK_EJECT_MEDIA, NULL, 0, NULL, 0, &amp;dwReturn, NULL);
			MYTRACE(L&quot;IOCTL_DISK_EJECT_MEDIA bRet==%d&quot;, bRet);
			bRet = DeviceIoControl(hVolume, IOCTL_STORAGE_EJECT_MEDIA, NULL, 0, NULL, 0, &amp;dwReturn, NULL);
			MYTRACE(L&quot;IOCTL_STORAGE_EJECT_MEDIA bRet==%d&quot;, bRet);

		}
		// 弹出是否成功
		if (!PathFileExists(wszVolShort))
		{
			DeleteJunctionPoint(dwVolLetter);
			bRet = TRUE;
			break;
		}
		else
		{
			bRet = FALSE;
			break;
		}
	} while (0);

	if (INVALID_HANDLE_VALUE != hVolume)
	{
		CloseHandle(hVolume);
		hVolume = INVALID_HANDLE_VALUE;
	}

	return bRet;
}
在大多是机器都是正常的，但是在该客户的机器，调用上述代码后，虽然U盘设备已经移除，但是explorer 仍会有U盘图标显示。对此，我的解决方案就是刷新一下 explorer 界面，让已弹出的U盘不显示。
解决思路
总共试了以下多个 API 尝试通知到 explorer。
API 1 DeleteVolumeMountPointW (不要用)
由于尝试了多个 API 无果后，就尝试了调用了 以下接口，导致了后续一系列问题，在此避坑，建议了解当前函数的使用场景后再决定是否调用。
C++cppDeleteVolumeMountPointW
API 2 DefineDosDevice
DefineDosDeviceA 函数 (winbase.h) - Win32 apps | Microsoft Learn
DefineDosDevice 会删除驱动器号。但是在。
C++cppvoid RemoveDrive(char driveLetter) 
{
	MYTRACE(L&quot;RemoveDrive&quot;);

	wchar_t deviceName[] = L&quot;\\??\\X:&quot;;
	deviceName[4] = driveLetter;

	// 移除设备挂载点
	DefineDosDevice(DDD_REMOVE_DEFINITION, deviceName, NULL);
}
API 3 SendMessage
通过 SendMessage 发送 WM_DEVICECHANGE 消息给所有窗口。
C++cppvoid NotifyDeviceRemoval(DWORD dwVolLetter) 
{
	MYTRACE(L&quot;NotifyDeviceRemoval&quot;);
	DEV_BROADCAST_VOLUME dbv = { 0 };
	dbv.dbcv_size = sizeof(DEV_BROADCAST_VOLUME);
	dbv.dbcv_devicetype = DBT_DEVTYP_VOLUME;
	dbv.dbcv_unitmask = 1 &lt;&lt; (dwVolLetter - L&#039;A&#039;);

	SendMessage(HWND_BROADCAST, WM_DEVICECHANGE, DBT_DEVICEREMOVECOMPLETE, (LPARAM)&amp;dbv); // 这一步其实已经是可以了，但是这个客户机器还是不行，调用后设备管理器界面会有延迟，但是 explorer 界面会立即刷新。
	SendMessage(HWND_BROADCAST, WM_DEVICECHANGE, DBT_DEVICEREMOVECOMPLETE, 0);
}
API 4 RunDLL32.EXE
调用 RunDLL32.EXE 来实现弹出。以下两种方法均不可行，有需求可以深入研究下。
C++cppvoid EjectDriveWithShell(char driveLetter) 
{
	MYTRACE(L&quot;EjectDriveWithShell&quot;);
	wchar_t command[] = L&quot;RunDLL32.EXE shell32.dll,Control_RunDLL hotplug.dll&quot;;
	ShellExecute(NULL, L&quot;open&quot;, command, NULL, NULL, SW_SHOWNORMAL);
}

// RunDLL32.EXE shell32.dll,SHInvokeCommand 0 &quot;EjectPC&quot; &quot;%c:\\&quot;
void EjectDriveWithShell(char driveLetter) 
{
	MYTRACE(L&quot;EjectDriveWithShell&quot;);
	wchar_t command[MAX_PATH] = {0};
	wsprintf(command, L&quot;RunDLL32.EXE shell32.dll,SHInvokeCommand 0 \&quot;EjectPC\&quot; \&quot;%c:\\\\\&quot;&quot;, driveLetter);
	ShellExecute(NULL, L&quot;open&quot;, command, NULL, NULL, SW_SHOWNORMAL);
}
API 5 重新挂载达到刷新目的
结果：同样不生效，U盘设备移除，但是 Expolorer 图标仍在。
C++cppvoid RemountDrive(char driveLetter) 
{
	MYTRACE(L&quot;RemountDrive&quot;);
	wchar_t deviceName[] = L&quot;\\\\.\\X:&quot;;
	deviceName[4] = driveLetter;

	HANDLE hDevice = CreateFile(deviceName, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, 0, NULL);
	if (hDevice != INVALID_HANDLE_VALUE) {
		DWORD bytesReturned;
		DeviceIoControl(hDevice, FSCTL_DISMOUNT_VOLUME, NULL, 0, NULL, 0, &amp;bytesReturned, NULL);
		DeviceIoControl(hDevice, IOCTL_STORAGE_EJECT_MEDIA, NULL, 0, NULL, 0, &amp;bytesReturned, NULL);
		CloseHandle(hDevice);
	}

	// 重新挂载驱动器
	hDevice = CreateFile(deviceName, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, 0, NULL);
	if (hDevice != INVALID_HANDLE_VALUE) {
		CloseHandle(hDevice);
	}
}
API 5 BroadcastSystemMessage
调用 BroadcastSystemMessage 广播通知设备改动
结果：不生效，图标在、设备也在
C++cppvoid BroadcastDeviceChange(DWORD dwVolLetter) 
{
	// 模拟设备移除消息
	DEV_BROADCAST_VOLUME dbv;
	dbv.dbcv_size = sizeof(DEV_BROADCAST_VOLUME);
	dbv.dbcv_devicetype = DBT_DEVTYP_VOLUME;
	dbv.dbcv_reserved = 0;
	dbv.dbcv_unitmask = 1 &lt;&lt; (dwVolLetter - L&#039;A&#039;); // 假设 E: 是 U 盘的盘符
	dbv.dbcv_flags = DBTF_MEDIA;

	// 向系统广播设备变更消息
	BroadcastSystemMessage(BSF_IGNORECURRENTTASK | BSF_POSTMESSAGE, BSM_ALLCOMPONENTS, WM_DEVICECHANGE, DBT_DEVICEREMOVECOMPLETE, (LPARAM)&amp;dbv);

}
API 6 刷新设备列表
调用 SetupDI* 接口刷新设备列表。
结果：无效。因为设备并没有实际弹出，所有刷新后设备列表还是会有便携设备存在。
C++cppvoid RefreshDevice(LPCWSTR deviceInstanceId)
{
	MYTRACE(L&quot;RefreshDevice&quot;);
	HDEVINFO deviceInfoSet = SetupDiGetClassDevs(NULL, deviceInstanceId, NULL, DIGCF_ALLCLASSES | DIGCF_PRESENT);
	if (deviceInfoSet == INVALID_HANDLE_VALUE) 
	{
		return;
	}

	SP_DEVINFO_DATA deviceInfoData;
	deviceInfoData.cbSize = sizeof(SP_DEVINFO_DATA);

	if (SetupDiEnumDeviceInfo(deviceInfoSet, 0, &amp;deviceInfoData)) 
	{
		SetupDiCallClassInstaller(DIF_PROPERTYCHANGE, deviceInfoSet, &amp;deviceInfoData);
	}

	SetupDiDestroyDeviceInfoList(deviceInfoSet);
}
API 7 刷新 Explorer 界面
C++cppVOID RefreshFolderViews(UINT csidl, LONG wEventId)
{
    LPITEMIDLIST pidl;
    if (SUCCEEDED(SHGetSpecialFolderLocation(NULL, csidl, &amp;pidl)))
    {
    //    SHChangeNotify(SHCNE_UPDATEDIR, SHCNF_IDLIST, pidl, 0);
		SHChangeNotify(wEventId, SHCNF_IDLIST|SHCNF_FLUSH, pidl, 0);
        CoTaskMemFree(pidl);
    }
}
最终解决方案
调用 DeivceIOControl 强制弹出，然后通知界面刷新。
界面刷新调用了 SendMessage 和 SHChangeNotify，代码如下所示：
C++cpp	NotifyDeviceRemoval(dwVolLetter);
	SHChangeNotify(SHCNE_DRIVEREMOVED, SHCNF_PATH, wszVolShort, NULL);
	SHChangeNotify(SHCNE_DRIVEADD, SHCNF_PATH, wszVolShort, NULL);
事实上，只要 CM_Request_Device_Eject_Ex 调用成功，那图标缓存和设备列表都会更新，但是调用失败的时候就比较复杂，尤其是返回 PNP_VetoIllegalDeviceRequest 时，没有合适的方法能从设备列表移除设备。
备忘
C++cppWCHAR wszDrivePoint[3] = L&quot; :&quot;;
wszDrivePoint[0] = dwVolLetter;

if (!DefineDosDevice(DDD_REMOVE_DEFINITION | DDD_EXACT_MATCH_ON_REMOVE, wszDrivePoint, NULL))
	MYTRACE(L&quot;DDD_REMOVE_DEFINITION bRet==%d&quot;, GetLastError());

a_os/windows/api/监控网卡事件.content:

                  概述 



Windows 网卡事件监控技术，包括网络状态变化检测、连接事件通知等。




  本文部分内容由 AI 生成，经人工修订。

0x01、网络监控概述
Windows 提供了多种监控网络状态变化的 API，主要包括：



































API说明需要权限NLA（Network Location Awareness）网络位置感知，监控网络连接变化无NotifyAddrChange监控 IP 地址变化无WMIWindows 管理规范，全面监控无IP Helper API网络相关 API无注册表通知监控注册表网络项变化无
0x02、NLA Network List Manager
Network List Manager API 是监控网络状态变化的标准方式。
核心接口

























接口说明INetworkListManager网络列表管理器主接口INetworkListManagerEvents网络列表事件接口INetworkEvents网络事件接口IConnectionPointContainer连接点容器
基本使用流程

CoCreateInstance 创建 NetworkListManager
QueryInterface 获取 INetworkListManager
提供事件监听接口（COM 回调）
注册事件通知
处理网络变化事件
注销通知

0x03、完整代码实现
头文件部分
C++cpp#pragma once

#include &lt;netlistmgr.h&gt;
#include &lt;atomic&gt;
#include &lt;functional&gt;

// 全局网络状态标志
std::atomic_bool g_bNetworkOnline(true);

// 网络列表管理器事件类
class CNetworkListManagerEvent : public INetworkListManagerEvents
{
public:
    CNetworkListManagerEvent(std::function&lt;void(bool)&gt; handler)
        : m_ref(1)
        , changeHandler_(handler)
    {
    }

    ~CNetworkListManagerEvent() {}

    // IUnknown 接口实现
    HRESULT STDMETHODCALLTYPE QueryInterface(REFIID riid, void** ppvObject)
    {
        if (IsEqualIID(riid, IID_IUnknown) || 
            IsEqualIID(riid, IID_INetworkListManagerEvents)) {
            *ppvObject = static_cast&lt;INetworkListManagerEvents*&gt;(this);
            AddRef();
            return S_OK;
        }
        *ppvObject = nullptr;
        return E_NOINTERFACE;
    }

    ULONG STDMETHODCALLTYPE AddRef()
    {
        return (ULONG)InterlockedIncrement(&amp;m_ref);
    }

    ULONG STDMETHODCALLTYPE Release()
    {
        LONG ref = InterlockedDecrement(&amp;m_ref);
        if (ref == 0) delete this;
        return (ULONG)ref;
    }

    // INetworkListManagerEvents 接口实现
    HRESULT STDMETHODCALLTYPE ConnectivityChanged(NLM_CONNECTIVITY newConnectivity)
    {
        if (newConnectivity == NLM_CONNECTIVITY_DISCONNECTED)
        {
            // 网络断开
            if (changeHandler_) changeHandler_(false);
        }
        else if ((newConnectivity &amp; NLM_CONNECTIVITY_IPV4_INTERNET) || 
                 (newConnectivity &amp; NLM_CONNECTIVITY_IPV6_INTERNET))
        {
            // 网络连接到互联网
            if (changeHandler_) changeHandler_(true);
        }
        return S_OK;
    }

private:
    LONG m_ref;
    std::function&lt;void(bool)&gt; changeHandler_;
};
网络监控器类
C++cpp#include &lt;windows.h&gt;
#include &lt;netlistmgr.h&gt;
#include &lt;thread&gt;
#include &lt;functional&gt;
#include &lt;iostream&gt;

class CNetworkMonitor
{
public:
    CNetworkMonitor() = default;
    ~CNetworkMonitor() = default;

    // 启动监控线程
    void StartMonitor()
    {
        std::thread monitorThread(&amp;CNetworkMonitor::InitNetworkMonitor, this);
        monitorThread.detach();
    }

    // 停止监控
    void StopMonitor()
    {
        // 实际实现需要设置退出标志并通知消息循环
    }

private:
    // 网络状态变化回调
    void NetworkStatusChangedCallback(bool online)
    {
        g_bNetworkOnline = online;

        if (online) {
            std::cout &lt;&lt; &quot;Network connected&quot; &lt;&lt; std::endl;
            OnNetworkConnected();
        } else {
            std::cout &lt;&lt; &quot;Network disconnected&quot; &lt;&lt; std::endl;
            OnNetworkDisconnected();
        }
    }

    // 网络连接处理
    void OnNetworkConnected()
    {
        // 实现网络连接后的业务逻辑
        // 如：重连服务器、发送心跳等
    }

    // 网络断开处理
    void OnNetworkDisconnected()
    {
        // 实现网络断开后的业务逻辑
        // 如：清理连接、等待重连等
    }

    // 初始化网络监控
    void InitNetworkMonitor()
    {
        CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

        IUnknown* pUnknown = nullptr;
        HRESULT hr = CoCreateInstance(CLSID_NetworkListManager, nullptr, 
                                      CLSCTX_ALL, IID_IUnknown, 
                                      reinterpret_cast&lt;void**&gt;(&amp;pUnknown));

        if (SUCCEEDED(hr))
        {
            INetworkListManager* pNLM = nullptr;
            hr = pUnknown-&gt;QueryInterface(IID_INetworkListManager, 
                                           reinterpret_cast&lt;void**&gt;(&amp;pNLM));

            if (SUCCEEDED(hr))
            {
                // 检查当前网络连接状态
                VARIANT_BOOL isConnected = VARIANT_FALSE;
                hr = pNLM-&gt;get_IsConnectedToInternet(&amp;isConnected);
                if (SUCCEEDED(hr))
                {
                    std::cout &lt;&lt; &quot;Current internet status: &quot; 
                              &lt;&lt; (isConnected ? &quot;Connected&quot; : &quot;Disconnected&quot;) 
                              &lt;&lt; std::endl;
                }

                // 注册网络变化事件
                IConnectionPointContainer* pCPC = nullptr;
                hr = pNLM-&gt;QueryInterface(IID_IConnectionPointContainer, 
                                         reinterpret_cast&lt;void**&gt;(&amp;pCPC));

                if (SUCCEEDED(hr))
                {
                    IConnectionPoint* pCP = nullptr;
                    hr = pCPC-&gt;FindConnectionPoint(IID_INetworkListManagerEvents, &amp;pCP);

                    if (SUCCEEDED(hr))
                    {
                        DWORD cookie = 0;

                        // 创建事件处理对象
                        auto callback = std::bind(&amp;CNetworkMonitor::NetworkStatusChangedCallback, 
                                                 this, std::placeholders::_1);
                        CNetworkListManagerEvent* pEvent = new CNetworkListManagerEvent(callback);

                        if (pEvent)
                        {
                            hr = pCP-&gt;Advise(static_cast&lt;IUnknown*&gt;(pEvent), &amp;cookie);
                            if (SUCCEEDED(hr))
                            {
                                std::cout &lt;&lt; &quot;Network monitor started successfully&quot; &lt;&lt; std::endl;

                                // 消息循环处理事件
                                MSG msg;
                                while (GetMessage(&amp;msg, nullptr, 0, 0))
                                {
                                    TranslateMessage(&amp;msg);
                                    DispatchMessage(&amp;msg);
                                }

                                // 注销事件
                                pCP-&gt;Unadvise(cookie);
                            } else {
                                std::cerr &lt;&lt; &quot;Failed to advise event: 0x&quot; &lt;&lt; std::hex &lt;&lt; hr &lt;&lt; std::endl;
                            }

                            pEvent-&gt;Release();
                        }
                        pCP-&gt;Release();
                    } else {
                        std::cerr &lt;&lt; &quot;Failed to find connection point: 0x&quot; &lt;&lt; std::hex &lt;&lt; hr &lt;&lt; std::endl;
                    }
                    pCPC-&gt;Release();
                } else {
                    std::cerr &lt;&lt; &quot;Failed to query connection point container: 0x&quot; &lt;&lt; std::hex &lt;&lt; hr &lt;&lt; std::endl;
                }
                pNLM-&gt;Release();
            } else {
                std::cerr &lt;&lt; &quot;Failed to query NetworkListManager: 0x&quot; &lt;&lt; std::hex &lt;&lt; hr &lt;&lt; std::endl;
            }
            pUnknown-&gt;Release();
        } else {
            std::cerr &lt;&lt; &quot;Failed to create NetworkListManager: 0x&quot; &lt;&lt; std::hex &lt;&lt; hr &lt;&lt; std::endl;
        }

        CoUninitialize();
    }
};
