		{
			status = TRUE;
			RtlCopyMemory(*fullDCName, cInfo-&gt;DomainControllerName + 2, size);
		}
		NetApiBufferFree(cInfo);
	}
	else PRINT_ERROR(L&quot;DsGetDcName: %u\n&quot;, ret);
	return status;
}

