    ppszDisplayName = ppszDisplayName.Replace(&quot;objref:&quot;, &quot;&quot;).Replace(&quot;:&quot;, &quot;&quot;);
    byte[] objrefBytes = Convert.FromBase64String(ppszDisplayName);

    ObjRef tmpObjRef = new ObjRef(objrefBytes);

