    godPotatoContext.ConsoleWriter.WriteLine($&quot;[*] DCOM obj IPID: {tmpObjRef.StandardObjRef.IPID}&quot;);
    godPotatoContext.ConsoleWriter.WriteLine(&quot;[*] DCOM obj OXID: 0x{0:x}&quot;, tmpObjRef.StandardObjRef.OXID);
