    godPotatoContext.ConsoleWriter.WriteLine(&quot;[*] DCOM obj Flags: 0x{0:x}&quot;, tmpObjRef.StandardObjRef.Flags);
    godPotatoContext.ConsoleWriter.WriteLine(&quot;[*] DCOM obj PublicRefs: 0x{0:x}&quot;, tmpObjRef.StandardObjRef.PublicRefs);

