void FindAllDlls(const WCHAR* Path, int iDeep)
{
	if (iDeep &gt; 6)
	{
		return;
	}

	WCHAR TargetPath[MAX_PATH] = {};
	WCHAR szTempPath[MAX_PATH] = { 0 };
	LPCWSTR lpszFilePath = TEST_PATH;
