概述双机调试快速设置脚本


双机调试脚本
cmd@echo off
setlocal enabledelayedexpansion

echo 开始工作，当前目录为: %cd%

REM 创建一个临时文件夹，用于测试权限
set &quot;testFolder=C:\Windows\System32\AdminTest1&quot;

REM 尝试创建一个文件夹
mkdir &quot;%testFolder%&quot; 2&gt;nul

REM 检查是否成功创建
if exist &quot;%testFolder%&quot; (
    rmdir &quot;%testFolder%&quot;
) else (
    echo 当前进程没有管理员权限,结束运行
	pause
	goto:eof
)

for /F &quot;tokens=1,2 delims=#&quot; %%a in (&#039;&quot;prompt #$H#$E# &amp; echo on &amp; for %%b in (1) do rem&quot;&#039;) do (
  set &quot;DEL=%%a&quot;
)

:start

:: 提示用户选择
call :ColorText 02 &quot;请选择一个选项：&quot;
echo.
echo 1: 网络调试
echo 2: 串口调试
echo 3: 退出

:: 使用 choice 命令获取用户输入
choice /C 123 /M &quot;请输入你的选择:&quot;

set USER_CHOICE=%ERRORLEVEL%

:: 根据用户选择执行不同的处理逻辑
if &quot;%USER_CHOICE%&quot;==&quot;1&quot; (
    echo 你选择了选项1
    rem 在这里添加选项1的处理逻辑
	bcdedit.exe -set TESTSIGNING ON
	bcdedit.exe -set loadoptions DDISABLE_INTEGRITY_CHECKS
	bcdedit /set nointegritychecks on
	bcdedit /debug on
	bcdedit /bootdebug on
	rem 输入ip
	set /p InputIp=&quot;请输入调试主机IP地址:&quot;
	echo 输入IP为:!InputIp!
	rem 输入调试端口
	set /P InputPort=&quot;请输入调式端口地址:&quot;
	echo 输入端口为:!InputPort!
	@echo on
	bcdedit /dbgsettings net hostip:!InputIp! port:!InputPort!
	@echo off
	echo 请手动配置总线编号、设备编号和功能编号
	bcdedit /set {dbgsettings}  busparams  b.d.f
	pause
	goto:eof
)

if &quot;%USER_CHOICE%&quot;==&quot;2&quot; (
	echo test1
    call :ColorText 0b &quot;开始配置串口调试：&quot;
    bcdedit /dbgsettings SERIAL DEBUGPORT:1 BAUDRATE:115200
	bcdedit /set testsigning on
	rem 启动
	bcdedit /debug on
	rem 永久禁用数字签名
	bcdedit.exe /set nointegritychecks on
)

if &quot;%USER_CHOICE%&quot;==&quot;3&quot; (
    echo 你选择了退出
    exit
)

:: 参数1为空情况下打印提示
if &quot;%~1&quot;==&quot;&quot; (
	call :ColorText 0C &quot;[Error]没有提供参数1&quot;
	echo.

	call :UsagePrint
	echo.

	goto:eof
)

goto:eof

:UsagePrint
	call :ColorText 02 &quot;[Usage]:&quot;
	echo.

	call :ColorText 02 &quot;    %~nx0 [OutputDir] [ui version]&quot;
	echo.
goto:eof

:: call :ColorText 0C &quot;red&quot;
:: call :ColorText 0b &quot;blue&quot;
:: call :ColorText 02 &quot;green&quot;
:: call :ColorText 19 &quot;yellow&quot;
:: call :ColorText 2F &quot;black&quot;
:: call :ColorText 4e &quot;white&quot;
:ColorText
@echo off
:: 移除冒号
set &quot;input=%~2&quot;
set &quot;input=!input::=：!&quot;
&lt;nul set /p &quot;.=%DEL%&quot; &gt; &quot;!input!&quot;
findstr /v /a:%1 /R &quot;^$&quot; &quot;!input!&quot; nul
del &quot;!input!&quot; &gt; nul 2&gt;&amp;1
goto :eof

pause

