a_os/windows/安全/沙箱技术/windows-沙箱-demo---j.content:
前言
本文是 Windows 沙箱技术全景 的编程实战篇。使用 Job Object 对进程施加资源限制和 UI 限制，配合受限令牌构建一个轻量级的进程管控沙箱。
Job Object 本身不做文件/网络隔离，但它是自定义沙箱方案中不可或缺的组件——限制资源 + 管理进程树 + UI 限制。
环境准备

























项目要求操作系统Windows 10 / 11IDEVisual Studio 2022SDKWindows SDK 10.0.26100+语言C++

核心概念
┌──────────────── Job Object ────────────────┐
│                                            │
│   ┌─────────────┐    ┌─────────────┐       │
│   │  父进程      │───→│  子进程 A    │       │
│   │ (自动加入)   │    │ (自动加入)   │       │
│   └─────────────┘    └─────────────┘       │
│                            │                │
│                            ↓                │
│                      ┌─────────────┐       │
│                      │  子进程 B    │       │
│                      │ (自动加入)   │       │
│                      └─────────────┘       │
│                                            │
│   限制：                                    │
│   • CPU 速率 ≤ 20%                         │
│   • 内存 ≤ 256MB                           │
│   • 不能读剪贴板                            │
│   • 不能退出 Windows                        │
│   • Job 关闭 → 全部终止                     │
└────────────────────────────────────────────┘

关键特性：

进程一旦加入 Job，不可脱离（AssignProcessToJobObject）
子进程自动加入父进程的 Job（默认行为）
JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE：Job 句柄关闭时杀灭所有进程
Win8+ 支持嵌套 Job，可以有多层限制


完整代码
1. 创建 Job Object 并设置限制
C++cpp// sandbox_jobobject.cpp
// Job Object + 受限令牌 沙箱 Demo

#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;
#include &lt;tlhelp32.h&gt;

// 创建配置好的 Job Object
HANDLE CreateSandboxJob()
{
    // ---- Step 1: 创建 Job Object ----
    HANDLE hJob = ::CreateJobObjectW(nullptr, L&quot;SandboxJob_Demo&quot;);
    if (!hJob) {
        wprintf(L&quot;[-] CreateJobObject failed: %lu\n&quot;, GetLastError());
        return nullptr;
    }
    wprintf(L&quot;[+] Job Object created\n&quot;);

    // ---- Step 2: 设置基本限制 ----
    JOBOBJECT_BASIC_LIMIT_INFORMATION basicLimit = {};
    basicLimit.LimitFlags =
        JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE |    // Job 关闭时杀全部进程
        JOB_OBJECT_LIMIT_DIE_ON_UNHANDLED_EXCEPTION | // 未处理异常 → 终止整个 Job
        JOB_OBJECT_LIMIT_BREAKAWAY_OK;           // 允许子进程脱离（调试用）

    // 进程数限制
    basicLimit.LimitFlags |= JOB_OBJECT_LIMIT_ACTIVE_PROCESS;
    basicLimit.ActiveProcessLimit = 10;

    if (!::SetInformationJobObject(hJob, JobObjectBasicLimitInformation,
        &amp;basicLimit, sizeof(basicLimit))) {
        wprintf(L&quot;[-] SetInformationJobObject (basic) failed: %lu\n&quot;, GetLastError());
        ::CloseHandle(hJob);
        return nullptr;
    }
    wprintf(L&quot;[+] Basic limits set (max 10 processes, kill-on-close)\n&quot;);

    // ---- Step 3: 设置扩展限制（内存 + CPU） ----
    JOBOBJECT_EXTENDED_LIMIT_INFORMATION extLimit = {};
    extLimit.BasicLimitInformation.LimitFlags =
        JOB_OBJECT_LIMIT_PROCESS_MEMORY |        // 进程内存上限
        JOB_OBJECT_LIMIT_JOB_MEMORY |            // 整个 Job 内存上限
        JOB_OBJECT_LIMIT_CPU_RATE_CONTROL;       // CPU 速率控制

    // 内存限制：单个进程 256MB，整个 Job 512MB
    extLimit.ProcessMemoryLimit = 256 * 1024 * 1024;   // 256 MB
    extLimit.JobMemoryLimit = 512 * 1024 * 1024;        // 512 MB

    if (!::SetInformationJobObject(hJob, JobObjectExtendedLimitInformation,
        &amp;extLimit, sizeof(extLimit))) {
        wprintf(L&quot;[-] SetInformationJobObject (extended) failed: %lu\n&quot;, GetLastError());
        // 非致命，继续
    } else {
        wprintf(L&quot;[+] Extended limits set (process: 256MB, job: 512MB)\n&quot;);
    }

    // ---- Step 4: CPU 速率限制 ----
    JOBOBJECT_CPU_RATE_CONTROL_INFORMATION cpuRate = {};
    cpuRate.ControlFlags =
        JOB_OBJECT_CPU_RATE_CONTROL_ENABLE |
        JOB_OBJECT_CPU_RATE_CONTROL_HARD_CAP;   // 硬限制，不可超出
    cpuRate.CpuRate = 2000;  // 单位：百分比 × 100，即 20%（2000 = 20%）

    if (!::SetInformationJobObject(hJob, JobObjectCpuRateControlInformation,
        &amp;cpuRate, sizeof(cpuRate))) {
        wprintf(L&quot;[-] SetInformationJobObject (CPU rate) failed: %lu\n&quot;, GetLastError());
    } else {
        wprintf(L&quot;[+] CPU rate limit set to 20%%\n&quot;);
    }

    // ---- Step 5: UI 限制 ----
    JOBOBJECT_BASIC_UI_RESTRICTIONS uiRestrictions = {};
    uiRestrictions.UIRestrictionsClass =
        JOB_OBJECT_UILIMIT_EXIT_WINDOWS |        // 不能关机/重启
        JOB_OBJECT_UILIMIT_READCLIPBOARD |       // 不能读剪贴板
        JOB_OBJECT_UILIMIT_WRITECLIPBOARD |      // 不能写剪贴板
        JOB_OBJECT_UILIMIT_SYSTEMPARAMETERS |    // 不能改系统参数
        JOB_OBJECT_UILIMIT_DISPLAYSETTINGS |     // 不能改显示设置
        JOB_OBJECT_UILIMIT_GLOBALATOMS;          // 隔离全局原子表

    if (!::SetInformationJobObject(hJob, JobObjectBasicUIRestrictions,
        &amp;uiRestrictions, sizeof(uiRestrictions))) {
        wprintf(L&quot;[-] SetInformationJobObject (UI) failed: %lu\n&quot;, GetLastError());
    } else {
        wprintf(L&quot;[+] UI restrictions set (no clipboard, no system params)\n&quot;);
    }

    return hJob;
}

// 创建受限令牌（去掉高危权限）
HANDLE CreateRestrictedTokenForSandbox()
{
    HANDLE hCurrentToken = nullptr;
    if (!::OpenProcessToken(::GetCurrentProcess(), TOKEN_DUPLICATE | TOKEN_QUERY, &amp;hCurrentToken)) {
        wprintf(L&quot;[-] OpenProcessToken failed: %lu\n&quot;, GetLastError());
        return nullptr;
    }

    HANDLE hRestrictedToken = nullptr;
    // 创建受限令牌：移除所有权限，仅保留基本权限
    if (!::CreateRestrictedToken(
        hCurrentToken,
        DISABLE_MAX_PRIVILEGE,     // 禁用所有权限
        0, nullptr,                 // 不删除特定 SID
        0, nullptr,                 // 不设置 Deny-Only SID
        0, nullptr,                 // 不限制 SID
        &amp;hRestrictedToken))
    {
        wprintf(L&quot;[-] CreateRestrictedToken failed: %lu\n&quot;, GetLastError());
        ::CloseHandle(hCurrentToken);
        return nullptr;
    }

    ::CloseHandle(hCurrentToken);
    wprintf(L&quot;[+] Restricted token created (all privileges disabled)\n&quot;);
    return hRestrictedToken;
}

// 在沙箱中启动进程
BOOL LaunchInSandbox(HANDLE hJob, HANDLE hRestrictedToken, const wchar_t* commandLine)
{
    STARTUPINFOW si = {};
    si.cb = sizeof(si);
    PROCESS_INFORMATION pi = {};

    // 使用受限令牌创建进程
    BOOL success = ::CreateProcessAsUserW(
        hRestrictedToken,
        nullptr,
        const_cast&lt;LPWSTR&gt;(commandLine),
        nullptr, nullptr,
        FALSE,
        CREATE_SUSPENDED | CREATE_NEW_CONSOLE,  // 挂起启动，先加入 Job
        nullptr, nullptr,
        &amp;si, &amp;pi);

    if (!success) {
        wprintf(L&quot;[-] CreateProcessAsUserW failed: %lu\n&quot;, GetLastError());
        return FALSE;
    }

    // 将进程加入 Job Object（在进程恢复执行前）
    if (!::AssignProcessToJobObject(hJob, pi.hProcess)) {
        wprintf(L&quot;[-] AssignProcessToJobObject failed: %lu\n&quot;, GetLastError());
        // Win8 之前的版本如果进程已加入其他 Job 会失败
        ::TerminateProcess(pi.hProcess, 1);
        ::CloseHandle(pi.hProcess);
        ::CloseHandle(pi.hThread);
        return FALSE;
    }

    // 恢复进程执行
    ::ResumeThread(pi.hThread);

    wprintf(L&quot;[+] Process launched in sandbox: PID=%lu\n&quot;, pi.dwProcessId);

    ::CloseHandle(pi.hThread);
    // 保留 pi.hProcess 供等待使用
    // 调用方负责关闭

    // 将进程句柄存入全局或返回
    // 这里简化：直接等待
    wprintf(L&quot;\n[&gt;] 进程在沙箱中运行中...\n&quot;);
    wprintf(L&quot;[&gt;] 限制：CPU 20%% / 内存 256MB / 无剪贴板 / 无关机\n&quot;);
    wprintf(L&quot;[&gt;] 等待进程退出...\n\n&quot;);

    ::WaitForSingleObject(pi.hProcess, INFINITE);

    DWORD exitCode = 0;
    ::GetExitCodeProcess(pi.hProcess, &amp;exitCode);
    wprintf(L&quot;[+] Process exited with code: %lu\n&quot;, exitCode);

    ::CloseHandle(pi.hProcess);
    return TRUE;
}

int wmain(int argc, wchar_t* argv[])
{
    wprintf(L&quot;====================================\n&quot;);
    wprintf(L&quot;  Job Object 沙箱 Demo\n&quot;);
    wprintf(L&quot;====================================\n\n&quot;);

    // 默认启动 cmd.exe，也可通过命令行参数指定
    std::wstring cmdLine = (argc &gt; 1) ? argv[1] : L&quot;cmd.exe /k echo Job Object Sandbox Ready&quot;;

    // Step 1: 创建 Job Object
    HANDLE hJob = CreateSandboxJob();
    if (!hJob) return 1;

    // Step 2: 创建受限令牌
    HANDLE hRestrictedToken = CreateRestrictedTokenForSandbox();
    if (!hRestrictedToken) {
        ::CloseHandle(hJob);
        return 1;
    }

    // Step 3: 在沙箱中启动进程
    wprintf(L&quot;\n[+] Launching: %s\n\n&quot;, cmdLine.c_str());
    LaunchInSandbox(hJob, hRestrictedToken, cmdLine.c_str());

    // 清理
    ::CloseHandle(hRestrictedToken);
    ::CloseHandle(hJob);  // 关闭 Job 句柄 → 如果有残留进程会被杀灭

    wprintf(L&quot;\n[+] Sandbox closed. All processes terminated.\n&quot;);
    return 0;
}
2. 测试脚本
编译后运行，会启动一个受限的 cmd.exe。在其中测试以下操作：
batch:: 在沙箱 cmd.exe 中执行以下测试：

:: 测试 1: 检查权限
whoami /priv
:: 预期：权限列表为空或极少

:: 测试 2: 尝试读取剪贴板
powershell -command &quot;Get-Clipboard&quot;
:: 预期：被拒绝（UI 限制）

:: 测试 3: 尝试关机
shutdown /s /t 0
:: 预期：被拒绝（UI 限制）

:: 测试 4: 消耗大量内存（测试内存限制）
:: 预期：进程因内存超限被终止
powershell -command &quot;$a = New-Object byte[] 300MB&quot;

:: 测试 5: 占用 CPU（测试 CPU 限制）
:: 预期：CPU 使用率被限制在 20%
powershell -command &quot;while($true) { $x = 1+1 }&quot;
3. 进程树监控（可选扩展）
C++cpp// 枚举 Job 中所有进程
void EnumerateJobProcesses(HANDLE hJob)
{
    JOBOBJECT_BASIC_PROCESS_ID_LIST pidList = {};
    DWORD cb = sizeof(JOBOBJECT_BASIC_PROCESS_ID_LIST) + sizeof(DWORD) * 100;
    auto buffer = std::vector&lt;BYTE&gt;(cb);

    auto pPidList = reinterpret_cast&lt;JOBOBJECT_BASIC_PROCESS_ID_LIST*&gt;(buffer.data());
    pPidList-&gt;NumberOfProcessIdsInList = 100;

    if (::QueryInformationJobObject(hJob, JobObjectBasicProcessIdList,
        pPidList, cb, nullptr))
    {
        wprintf(L&quot;[+] Job contains %lu processes:\n&quot;,
            pPidList-&gt;NumberOfProcessIdsInList);
        for (DWORD i = 0; i &lt; pPidList-&gt;NumberOfProcessIdsInList; i++) {
            wprintf(L&quot;    PID: %lu\n&quot;, pPidList-&gt;ProcessIdList[i]);
        }
    }
}

// 查询 Job 资源使用统计
void QueryJobStats(HANDLE hJob)
{
    JOBOBJECT_BASIC_AND_IO_ACCOUNTING_INFORMATION info = {};
    if (::QueryInformationJobObject(hJob,
        JobObjectBasicAndIoAccountingInformation,
        &amp;info, sizeof(info), nullptr))
    {
        wprintf(L&quot;\n--- Job Statistics ---\n&quot;);
        wprintf(L&quot;  Total processes:     %lu\n&quot;, info.BasicInfo.TotalProcesses);
        wprintf(L&quot;  Active processes:    %lu\n&quot;, info.BasicInfo.ActiveProcesses);
        wprintf(L&quot;  Terminated processes:%lu\n&quot;, info.BasicInfo.TotalTerminatedProcesses);
        wprintf(L&quot;  Peak process memory: %llu MB\n&quot;,
            info.BasicInfo.PeakProcessMemoryUsed / (1024 * 1024));
        wprintf(L&quot;  Peak job memory:     %llu MB\n&quot;,
            info.BasicInfo.PeakJobMemoryUsed / (1024 * 1024));
        wprintf(L&quot;  I/O Read bytes:      %llu\n&quot;, info.IoInfo.ReadOperationCount);
        wprintf(L&quot;  I/O Write bytes:     %llu\n&quot;, info.IoInfo.WriteOperationCount);
    }
}

限制项详解
基本限制 (JOBOBJECT_BASIC_LIMIT_INFORMATION)





































Flag说明JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSEJob 句柄关闭 → 杀灭所有进程JOB_OBJECT_LIMIT_DIE_ON_UNHANDLED_EXCEPTION未处理异常 → 终止整个 JobJOB_OBJECT_LIMIT_ACTIVE_PROCESS限制最大进程数JOB_OBJECT_LIMIT_PROCESS_TIME单进程 CPU 时间上限JOB_OBJECT_LIMIT_JOB_TIME整个 Job CPU 时间上限JOB_OBJECT_LIMIT_BREAKAWAY_OK允许子进程脱离 JobJOB_OBJECT_LIMIT_SILENT_BREAKAWAY_OK子进程自动脱离
扩展限制 (JOBOBJECT_EXTENDED_LIMIT_INFORMATION)





















Flag说明JOB_OBJECT_LIMIT_PROCESS_MEMORY单进程内存上限JOB_OBJECT_LIMIT_JOB_MEMORY整个 Job 内存上限JOB_OBJECT_LIMIT_CPU_RATE_CONTROL启用 CPU 速率控制
CPU 速率控制





















模式说明JOB_OBJECT_CPU_RATE_CONTROL_HARD_CAP硬限制，绝对不超JOB_OBJECT_CPU_RATE_CONTROL_SOFT_CAP软限制，系统空闲时可超出CpuRate百分比 × 100（如 2000 = 20%）
UI 限制 (JOBOBJECT_BASIC_UI_RESTRICTIONS)









































Flag说明JOB_OBJECT_UILIMIT_EXIT_WINDOWS不能关机/重启JOB_OBJECT_UILIMIT_READCLIPBOARD不能读剪贴板JOB_OBJECT_UILIMIT_WRITECLIPBOARD不能写剪贴板JOB_OBJECT_UILIMIT_SYSTEMPARAMETERS不能改系统参数JOB_OBJECT_UILIMIT_DISPLAYSETTINGS不能改显示设置JOB_OBJECT_UILIMIT_GLOBALATOMS隔离全局原子表JOB_OBJECT_UILIMIT_DESKTOP隔离桌面JOB_OBJECT_UILIMIT_HANDLES隔离句柄

组合方案：完整轻量级沙箱
