概述: 组策略-密码策略说明


0x01 密码策略如下图所示：

0x02 详细说明
1 放宽最小密码长度限制
2 密码必须符合复杂性要求
3 密码长度最小值
4 密码最短使用期限
5 密码最长使用期限
注册表：
6 强制密码历史
7 用户可还原的加密来存储密码
8 最小密码长度审核
相关API
用NetUser函数修改密码策略
可以使用 NetUserModalsGet 来查询密码策略，最后需要使用 NetApiBufferFree 来释放
查询到的数据空间。还可以使用 NetUserModalsSet 可以对密码策略进行设定。
C++cppNET_API_STATUS NetUserModalsGet(
  _In_opt_ LPCWSTR servername,
  _In_     DWORD   level,
  _Out_    LPBYTE  *bufptr
); // 查询密码策略
C++cppNET_API_STATUS NetApiBufferFree(
  _In_ LPVOID Buffer
); // 释放查询的数据空间
C++cppNET_API_STATUS NetUserModalsSet(
  _In_  LPCWSTR servername,
  _In_  DWORD   level,
  _In_  LPBYTE  buf,
  _Out_ LPDWORD parm_err
); // 设定密码策略
这两个函数中 level 参数决定了要处理数据的类型，可以取值的内容为

































































ValueMeaningStructure0Specifies global password parameters.USER_MODALS_INFO_01Specifies logon server and domain controller information.USER_MODALS_INFO_12Specifies the domain name and identifier.USER_MODALS_INFO_23Specifies lockout information.USER_MODALS_INFO_31001Specifies the minimum allowable password length.USER_MODALS_INFO_10011002Specifies the maximum allowable password age.USER_MODALS_INFO_10021003Specifies the minimum allowable password age.USER_MODALS_INFO_10031004Specifies forced logoff information.USER_MODALS_INFO_10041005Specifies the length of the password history.USER_MODALS_INFO_10051006Specifies the role of the logon server.USER_MODALS_INFO_10061007Specifies domain controller information.USER_MODALS_INFO_1007
如下是使用 NetUserModalsGet 查询时，我们关注的结构体信息
C++cpptypedef struct _USER_MODALS_INFO_0 {
  DWORD usrmod0_min_passwd_len; // 密码长度最小值
  DWORD usrmod0_max_passwd_age; // 密码最长使用期限(秒)
  DWORD usrmod0_min_passwd_age; // 密码最短使用期限(秒)
  DWORD usrmod0_force_logoff; // 过期后强制注销的期限(秒)
  DWORD usrmod0_password_hist_len; // 强制密码历史个数
} USER_MODALS_INFO_0, *PUSER_MODALS_INFO_0, *LPUSER_MODALS_INFO_0;
typedef struct _USER_MODALS_INFO_3 {
  DWORD usrmod3_lockout_duration; // 账户锁定时间(秒)
  DWORD usrmod3_lockout_observation_window; // 重置账户锁定计数器(秒)
  DWORD usrmod3_lockout_threshold; // 账户锁定阈值
} USER_MODALS_INFO_3, *PUSER_MODALS_INFO_3, *LPUSER_MODALS_INFO_3;
使用 NetUserModalsSet 除了以上结构体进行整体设置外，还可以对部分参数进行单独设置
C++cpptypedef struct _USER_MODALS_INFO_1001 {
  DWORD usrmod1001_min_passwd_len; // 密码长度最小值
} USER_MODALS_INFO_1001, *PUSER_MODALS_INFO_1001, *LPUSER_MODALS_INFO_1001;
typedef struct _USER_MODALS_INFO_1002 {
  DWORD usrmod1002_max_passwd_age; // 密码最长使用期限(秒)
} USER_MODALS_INFO_1002, *PUSER_MODALS_INFO_1002, *LPUSER_MODALS_INFO_1002;
typedef struct _USER_MODALS_INFO_1003 {
  DWORD usrmod1003_min_passwd_age; // 密码最短使用期限(秒)
} USER_MODALS_INFO_1003, *PUSER_MODALS_INFO_1003, *LPUSER_MODALS_INFO_1003;
typedef struct _USER_MODALS_INFO_1004 {
  DWORD usrmod1004_force_logoff; // 过期后强制注销的期限(秒)
} USER_MODALS_INFO_1004, *PUSER_MODALS_INFO_1004, *LPUSER_MODALS_INFO_1004;
typedef struct _USER_MODALS_INFO_1005 {
  DWORD usrmod1005_password_hist_len; // 强制密码历史个数
} USER_MODALS_INFO_1005, *PUSER_MODALS_INFO_1005, *LPUSER_MODALS_INFO_1005;
密码复杂度的处理
看到这里是不是发现一个问题，那就是 密码必须符合复杂性要求 这项配置，查询不到。
我们可以通过直接读取 SAM 注册表的信息，来判断密码复杂度是否启用
C++cppBOOL CheckPwdComplexPolicy()
{
    HKEY hKey = NULL;
    // 打开密码策略注册表
    LONG lResult = RegOpenKeyEx(HKEY_LOCAL_MACHINE,
        &quot;SAM\\SAM\\Domains\\Account&quot;, 0, KEY_ALL_ACCESS, &amp;hKey);
    if (lResult != ERROR_SUCCESS) return FALSE;
    // 读取密码策略注册表信息
    DWORD dwLen = 1024;
    BYTE pBuf[1024] = { 0 };
    lResult = RegQueryValueEx(hKey, &quot;F&quot;, NULL, NULL, pBuf, &amp;dwLen);
    RegCloseKey(hKey);
    if (lResult != ERROR_SUCCESS) return FALSE;
    // 检查密码复杂度是否启用
    if (pBuf[76] != 1) return FALSE; // 复杂度(0未启用)(1已启用)
    // if (pBuf[80] &lt; 8) return FALSE; // 最小长度
    return TRUE;
}
普通情况下 SAM 注册表是不允许访问的，就需要我们首先修改一下访问 SAM 的权限
C++cppBOOL ModifySamRegPrivilege()
{
    PACL pOldDacl = NULL;
    PSECURITY_DESCRIPTOR pSID = NULL;
    // 获取SAM主键的DACL
    DWORD dRet = GetNamedSecurityInfo(&quot;MACHINE\\SAM\\SAM&quot;,
        SE_REGISTRY_KEY, DACL_SECURITY_INFORMATION, NULL, NULL, &amp;pOldDacl, NULL, &amp;pSID);
    if (dRet != ERROR_SUCCESS)
    {
        LocalFree(pSID);
        return FALSE;
    }
    // 创建一个ACE,允许Administrators组成员完全控制对象,并允许子对象继承此权限
    EXPLICIT_ACCESS_A eia = { 0 };
    BuildExplicitAccessWithName(&amp;eia, &quot;Administrators&quot;,
        KEY_ALL_ACCESS, SET_ACCESS, SUB_CONTAINERS_AND_OBJECTS_INHERIT);
    // 将新的ACE加入DACL
    PACL pNewDacl = NULL;
    dRet = SetEntriesInAcl(1, &amp;eia, pOldDacl, &amp;pNewDacl);
    if (dRet != ERROR_SUCCESS)
    {
        LocalFree(pSID);
        return FALSE;
    }
    // 更新SAM主键的DACL   
    dRet = SetNamedSecurityInfo(&quot;MACHINE\\SAM\\SAM&quot;,
        SE_REGISTRY_KEY, DACL_SECURITY_INFORMATION, NULL, NULL, pNewDacl, NULL);
    if (dRet != ERROR_SUCCESS)
    {
        LocalFree(pNewDacl);
        LocalFree(pSID);
        return FALSE;
    }
    return TRUE;
}

a_os/windows/安全/组策略/账户锁定策略.content:
概述：Windows 安全设置下账户锁定策略相关内容


账户锁定策略条目
打开方式：Win+R -&gt; gpedit.msc（域控本地管理员无法修改）。如果是在域控服务器上，则需要输入 rsop.msc 来查看，如果修改请查看下一小节。

账户锁定时间

帐户锁定时间
此安全设置确定锁定帐户在自动解锁之前保持锁定的分钟数。可用范围从 0 到 99,999 分钟。如果将帐户锁定时间设置为 0，帐户将一直被锁定直到管理员明确解除对它的锁定。
如果定义了帐户锁定阈值，则帐户锁定时间必须大于或等于重置时间。
默认值: 无，因为只有在指定了帐户锁定阈值时，此策略设置才有意义。

即账户被锁定后开始，过了多长时间才能解锁
账户锁定阈值

帐户锁定阈值
此安全设置确定导致用户帐户被锁定的登录尝试失败的次数。在管理员重置锁定帐户或帐户锁定时间期满之前，无法使用该锁定帐户。可以将登录尝试失败次数设置为介于 0 和 999 之间的值。如果将值设置为 0，则永远不会锁定帐户。
在使用 Ctrl+Alt+Del 或密码保护的屏幕保护程序锁定的工作站或成员服务器上的密码尝试失败将计作登录尝试失败。
默认值: 0。

即账户在尝试登录时，失败几次后会锁定账户。
重置账户锁定计数器

在此后复位帐户锁定计数器
此安全设置确定在某次登录尝试失败之后将登录尝试失败计数器重置为 0 次错误登录尝试之前需要的时间。可用范围是 1 到 99,999 分钟。
如果定义了帐户锁定阈值，此重置时间必须小于或等于帐户锁定时间。
默认值: 无，因为只有在指定了帐户锁定阈值时，此策略设置才有意义。

即账户锁定阈值在锁定之后经过多久使账户锁定阈值清 0。
相关问题
域控服务器的策略如何设置
域策略 安全策略 组策略
在域控服务器上，修改登录策略。

工具 -&gt; 组策略管理

编辑默认域控

组策略管理编辑器


C++ 获取锁定策略
C++cppBOOL IsAccountLockoutPolicyOpen(LPCWSTR ServerName, BOOL&amp; bOpen)
{
	MYTRACE(L&quot;确认账户锁定策略是否开启&quot;);
	BOOL bSuc = FALSE;
	DWORD dwLevel = 3;
	USER_MODALS_INFO_3 *pBuf = NULL;
	NET_API_STATUS nStatus = NetUserModalsGet(ServerName,
		dwLevel,
		(LPBYTE *)&amp;pBuf);

	if (nStatus == NERR_Success)
	{
		if (pBuf != NULL)
		{
			bSuc = TRUE;
			if(pBuf-&gt;usrmod3_lockout_threshold == 0)
			{
				bOpen = FALSE;
			}
			else
			{
				bOpen = TRUE;
			}
		}
	}

	if (pBuf != NULL)
		NetApiBufferFree(pBuf);

	return bSuc;
}

