a_os/windows/服务/windows服务进程.content:

                  概述 



windows操作系统创建服务实例



说明
调用的相关系统API：

CreateService
StartServiceCtrlDispatcher
RegisterServiceCtrlHandlerEx

代码
使用时进需要修改 MyServiceName 即可。
C++cpp#include &lt;windows.h&gt;
#include &lt;tchar.h&gt;
#include &lt;strsafe.h&gt;

#define MyServiceName TEXT(&quot;MyService&quot;)

bool                    g_bPausedFlag = false;
HANDLE                  g_hSvcStopEvent = NULL;
SERVICE_STATUS          g_MyServiceStatus;
SERVICE_STATUS_HANDLE   g_hMyServiceStatusHandle;

void __stdcall MyServiceMain(DWORD  dwArgc, LPTSTR *lpszArgv);
DWORD __stdcall MyServiceHandlerEx(DWORD  dwControl, DWORD  dwEventType, LPVOID lpEventData, LPVOID lpContext);
void ReportServiceStatus(DWORD dwCurrentState, DWORD dwWin32ExitCode, DWORD dwWaitHint);
DWORD MyServiceInitialization(DWORD  dwArgc, LPTSTR *lpszArgv);
DWORD MyServiceWorker(DWORD dwArgc, LPTSTR *lpszArgv);

int _tmain(int argc, TCHAR* argv[])
{
    SERVICE_TABLE_ENTRY dispatchTable[] = { 
        {MyServiceName, (LPSERVICE_MAIN_FUNCTION)MyServiceMain},
        {NULL, NULL} };

    if (!StartServiceCtrlDispatcher(dispatchTable))
    {
        // cleaning worker
    }

    return 0;
}

void __stdcall MyServiceMain(DWORD  dwArgc, LPTSTR *lpszArgv)
{
    g_hSvcStopEvent = CreateEvent(NULL, TRUE, FALSE, NULL);
    g_hMyServiceStatusHandle = RegisterServiceCtrlHandlerEx(MyServiceName, (LPHANDLER_FUNCTION_EX)MyServiceHandlerEx, NULL);
    if (g_hMyServiceStatusHandle == NULL)
        return;

    g_MyServiceStatus.dwServiceType = SERVICE_WIN32_OWN_PROCESS;
    g_MyServiceStatus.dwServiceSpecificExitCode = 0;
    ReportServiceStatus(SERVICE_START_PENDING, 0, 0);

    DWORD dwRet = MyServiceInitialization(dwArgc, lpszArgv);
    if (dwRet != NO_ERROR)
        ReportServiceStatus(SERVICE_STOPPED, dwRet, 0);
    ReportServiceStatus(SERVICE_RUNNING, 0, 0);

    MyServiceWorker(dwArgc, lpszArgv);

    while (true)
    {
        WaitForSingleObject(g_hSvcStopEvent, INFINITE);
        ReportServiceStatus(SERVICE_STOPPED, 0, 0);
        return;
    }
}

DWORD __stdcall MyServiceHandlerEx(DWORD  dwControl, DWORD  dwEventType, LPVOID lpEventData, LPVOID lpContext)
{
    switch (dwControl)
    {
    case SERVICE_CONTROL_SHUTDOWN:
    case SERVICE_CONTROL_STOP:
        ReportServiceStatus(SERVICE_STOP_PENDING, 0, 0);
        SetEvent(g_hSvcStopEvent);
        break;
    case SERVICE_CONTROL_PAUSE:
        ReportServiceStatus(SERVICE_PAUSE_PENDING, 0, 0);
        g_bPausedFlag = true;
        break;
    case SERVICE_CONTROL_CONTINUE:
        ReportServiceStatus(SERVICE_CONTINUE_PENDING, 0, 0);
        g_bPausedFlag = false;
        break;
    case SERVICE_CONTROL_INTERROGATE:
        break;
    default:
        break;
    }
    return 0;
}

// 执行一些初始化过程
DWORD MyServiceInitialization(DWORD  dwArgc, LPTSTR *lpszArgv)
{
    return NO_ERROR;
}

// 服务工作执行函数
DWORD MyServiceWorker(DWORD dwArgc, LPTSTR *lpszArgv)
{
    return 0;
}

// 向服务控制管理器报告状态信息
void ReportServiceStatus(DWORD dwCurrentState, DWORD dwWin32ExitCode, DWORD dwWaitHint)
{
    static DWORD dwCheckPoint = 1;

    g_MyServiceStatus.dwCurrentState = dwCurrentState;
    g_MyServiceStatus.dwWin32ExitCode = dwWin32ExitCode;
    g_MyServiceStatus.dwWaitHint = dwWaitHint;

    if (dwCurrentState == SERVICE_START_PENDING)
        g_MyServiceStatus.dwControlsAccepted = 0;
    else 
        g_MyServiceStatus.dwControlsAccepted = SERVICE_ACCEPT_STOP | SERVICE_ACCEPT_PAUSE_CONTINUE;

    if ((dwCurrentState == SERVICE_RUNNING) ||
        (dwCurrentState == SERVICE_STOPPED))
        g_MyServiceStatus.dwCheckPoint = 0;
    else 
        g_MyServiceStatus.dwCheckPoint = dwCheckPoint++;

    SetServiceStatus(g_hMyServiceStatusHandle, &amp;g_MyServiceStatus);
}

补充 1：创建服务（CreateService 完整示例）



                  来源 



Windows-API-Usage/WinAPI/CreateService/CreateService.cpp





                  理解本文的前提 



上方的模板是服务内部（StartServiceCtrlDispatcher 分发入口）的写法；而创建/注册一个服务，需要在外部用 CreateService 完成。二者是服务生命周期的两个阶段。

























阶段API执行者作用安装/注册OpenSCManager + CreateService外部程序（安装器/管理员）在 SCM 中登记服务运行StartServiceCtrlDispatcher + RegisterServiceCtrlHandlerEx服务本体连接 SCM，响应控制
关键流程
C++cpp// 1. 打开服务控制管理器（SCM）
SC_HANDLE hSCM = ::OpenSCManager(NULL, NULL,
    SC_MANAGER_CONNECT | SC_MANAGER_CREATE_SERVICE);

// 2. 创建服务
SC_HANDLE hService = ::CreateService(
    hSCM,
    lpszServiceName,      // 服务名（注册表 Services 键名）
    lpszDisplayName,      // 显示名
    SERVICE_ALL_ACCESS,   // 权限
    SERVICE_WIN32_OWN_PROCESS, // 服务类型：独立进程
    SERVICE_AUTO_START,   // 启动类型：自动
    SERVICE_ERROR_NORMAL, // 错误处理
    szFilePath,           // 可执行文件路径
    _T(&quot;FSFilter Activity Monitor&quot;), // 服务组（LoadOrderGroup）
    &amp;dwOrder,             // 组内加载顺序标签
    _T(&quot;FltMgr&quot;),         // 依赖（Dependencies）
    NULL,                 // ServiceStartName（账户）
    NULL                  // 密码
);
失败处理：服务已存在



                  别把&quot;已存在&quot;当错误 



CreateService 失败时，若 GetLastError() == ERROR_SERVICE_EXISTS，说明服务之前已被创建过（如上次安装未卸载）。此时不应报错，而应视为”已存在”，走更新或直接返回成功的逻辑。


注意点



                  minifilter 驱动服务 



若服务类型为 SERVICE_FILE_SYSTEM_DRIVER / minifilter，还需要在注册表 Services\&lt;name&gt;\Instances 下写入 DefaultInstance、Altitude、Flags 等键，才会被过滤器管理器加载。





                   ChangeServiceConfig 的坑



在 CreateService 成功之后再调用 ChangeServiceConfig 是冗余操作；且若把依赖（FltMgr）误传成空字符串，会覆盖掉 minifilter 的依赖、破坏加载顺序——这正是 CreateService.cpp 中把这段调用注释掉的原因。
要动态修改配置，应在 ERROR_SERVICE_EXISTS 分支里调用 ChangeServiceConfig 才合理。


卸载服务（DeleteService）
C++cpp// 打开 SCM → 打开服务 → 若在运行则先 STOP → DeleteService
SC_HANDLE hSCManager = OpenSCManager(NULL, NULL, SC_MANAGER_ALL_ACCESS);
SC_HANDLE hSCService = OpenService(hSCManager, lpszServiceName, SERVICE_ALL_ACCESS);
QueryServiceStatus(hSCService, &amp;curStatus);
if (curStatus.dwCurrentState != SERVICE_STOPPED)
    ControlService(hSCService, SERVICE_CONTROL_STOP, &amp;ctrlstatus); // 先停止
DeleteService(hSCService); // 再删除

补充 2：服务主进程完整逻辑（SimpleService.cpp）



                  来源 



Windows-API-Usage/WinAPI/ServiceCallDll/SimpleService.cpp





                  与开头模板的关系 



开头那篇是精简骨架，本补充是同一个服务的完整实现（SimpleService.cpp）。核心框架一致，但多了：① 日志封装（define.h 的 Debug_Run/Debug_Error）；② 在 MyServiceWorker 里挂接实际业务（DLL 注入测试）。


服务主进程的生命周期
服务主进程就是 _tmain 里那一套：分发 → 主入口 → 注册控制处理 → 上报状态 → 初始化 → 干活 → 等停止。
_tmain
 └─ StartServiceCtrlDispatcher(dispatchTable)   ← 连接 SCM，进入服务分发
     └─ MyServiceMain(被 SCM 调用)
         ├─ CreateEvent(停止事件)
         ├─ RegisterServiceCtrlHandlerEx        ← 注册控制回调
         ├─ ReportServiceStatus(SERVICE_START_PENDING)  ← 启动中
         ├─ MyServiceInitialization             ← 初始化
         ├─ ReportServiceStatus(SERVICE_RUNNING)         ← 运行中
         ├─ MyServiceWorker                     ← 真正干活（本Demo：注入测试）
         └─ while(true) WaitForSingleObject(停止事件)    ← 等待停止
             └─ ReportServiceStatus(SERVICE_STOPPED)     ← 停止

服务主进程活动图




                  控制回调并行触发 



上图中的停止/暂停等状态变化，实际由 MyServiceHandlerEx 控制回调并行触发：SCM 收到 SERVICE_CONTROL_STOP 时回调里 SetEvent(g_hSvcStopEvent)，主线程的 WaitForSingleObject 随即返回并上报 SERVICE_STOPPED。


各函数职责








































函数职责关键点_tmain程序入口，注册服务分发表SERVICE_TABLE_ENTRY 以 {NULL,NULL} 结尾MyServiceMain服务主入口（SCM 回调）注册控制处理器、上报状态、调初始化与 WorkerMyServiceHandlerEx处理控制命令SERVICE_CONTROL_STOP/PAUSE/CONTINUE/SHUTDOWNMyServiceInitialization初始化本 Demo 仅打日志，返回 NO_ERRORMyServiceWorker业务主循环本 Demo 在此做 DLL 注入测试ReportServiceStatus向 SCM 上报状态封装 SetServiceStatus
关键代码逐段解读
1) 服务分发（_tmain）
C++cppSERVICE_TABLE_ENTRY dispatchTable[] = {
    {(LPWSTR)MyServiceName, (LPSERVICE_MAIN_FUNCTION)MyServiceMain},
    {NULL, NULL} };                       // 必须以 NULL 结尾

if (!StartServiceCtrlDispatcher(dispatchTable))
{
    // 失败说明不是被 SCM 启动（如直接在命令行运行），可在此提示
}



                  StartServiceCtrlDispatcher 的返回值 



只有被 SCM 启动时才会正确分发。若直接双击运行该 exe，StartServiceCtrlDispatcher 会立即失败（返回 FALSE）——因为本进程并非由 SCM 拉起的服务。这也是常见的调试困惑点。


2) 服务主入口（MyServiceMain）
C++cppvoid __stdcall MyServiceMain(DWORD dwArgc, LPTSTR* lpszArgv)
{
    g_hSvcStopEvent = CreateEvent(NULL, TRUE, FALSE, NULL);   // 停止事件
    // 注册控制回调（注意是 HandlerEx 版本，带事件参数）
    g_hMyServiceStatusHandle = RegisterServiceCtrlHandlerEx(MyServiceName,
        (LPHANDLER_FUNCTION_EX)MyServiceHandlerEx, NULL);
    if (g_hMyServiceStatusHandle == NULL)
        return;                                              // 注册失败直接退出

    g_MyServiceStatus.dwServiceType = SERVICE_WIN32_OWN_PROCESS;
    ReportServiceStatus(SERVICE_START_PENDING, 0, 0);        // 上报&quot;启动中&quot;

    DWORD dwRet = MyServiceInitialization(dwArgc, lpszArgv); // 初始化
    if (dwRet != NO_ERROR)
        ReportServiceStatus(SERVICE_STOPPED, dwRet, 0);      // 初始化失败 → 停止
    ReportServiceStatus(SERVICE_RUNNING, 0, 0);              // 上报&quot;运行中&quot;

    MyServiceWorker(dwArgc, lpszArgv);                       // 干活

    while (true)                                             // 等待停止
    {
        WaitForSingleObject(g_hSvcStopEvent, INFINITE);
        ReportServiceStatus(SERVICE_STOPPED, 0, 0);
        return;
    }
}



                  服务的&quot;主线程&quot;不能返回 



服务主线程进入 WaitForSingleObject(停止事件, INFINITE) 后就不能返回，否则 SCM 认为服务已退出。停止由控制回调通过 SetEvent(g_hSvcStopEvent) 触发。


3) 控制回调（MyServiceHandlerEx）
C++cppDWORD __stdcall MyServiceHandlerEx(DWORD dwControl, ...)
{
    switch (dwControl)
    {
    case SERVICE_CONTROL_SHUTDOWN:   // 系统关机
    case SERVICE_CONTROL_STOP:       // 停止服务
        ReportServiceStatus(SERVICE_STOP_PENDING, 0, 0);
        SetEvent(g_hSvcStopEvent);   // 触发主线程停止
        break;
    case SERVICE_CONTROL_PAUSE:      // 暂停
        ReportServiceStatus(SERVICE_PAUSE_PENDING, 0, 0);
        g_bPausedFlag = true;
        break;
    case SERVICE_CONTROL_CONTINUE:   // 继续
        ReportServiceStatus(SERVICE_CONTINUE_PENDING, 0, 0);
        g_bPausedFlag = false;
        break;
    case SERVICE_CONTROL_INTERROGATE: // 查询状态，无需动作
        break;
    default:
        break;
    }
    return 0;
}
4) 上报状态（ReportServiceStatus）
C++cppvoid ReportServiceStatus(DWORD dwCurrentState, DWORD dwWin32ExitCode, DWORD dwWaitHint)
{
    static DWORD dwCheckPoint = 1;
    g_MyServiceStatus.dwCurrentState = dwCurrentState;
    g_MyServiceStatus.dwWin32ExitCode = dwWin32ExitCode;
    g_MyServiceStatus.dwWaitHint = dwWaitHint;

    // 启动中不允许接收控制命令；运行/停止后可接收 停止+暂停/继续
    if (dwCurrentState == SERVICE_START_PENDING)
        g_MyServiceStatus.dwControlsAccepted = 0;
    else
        g_MyServiceStatus.dwControlsAccepted = SERVICE_ACCEPT_STOP | SERVICE_ACCEPT_PAUSE_CONTINUE;

    // 运行/停止时 checkpoint 归零；中间态自增（供 SCM 判断是否卡死）
    if ((dwCurrentState == SERVICE_RUNNING) || (dwCurrentState == SERVICE_STOPPED))
        g_MyServiceStatus.dwCheckPoint = 0;
    else
        g_MyServiceStatus.dwCheckPoint = dwCheckPoint++;

    SetServiceStatus(g_hMyServiceStatusHandle, &amp;g_MyServiceStatus);
}



                  CheckPoint 的意义 



启动/停止等过渡态（*_PENDING）需要 dwCheckPoint 自增并配合 dwWaitHint 提示 SCM “我还要多久”。若长时间无进展，SCM 会判定服务卡死。运行/停止的稳态则归零。


附加功能：Worker 中的 DLL 注入测试
MyServiceWorker 里挂的是注入逻辑——这只是用来验证”服务启动后能做点实际业务”的附加测试，并非服务核心：
C++cppDWORD MyServiceWorker(DWORD dwArgc, LPTSTR* lpszArgv)
{
    Debug_Run(L&quot;[%s]-------Work&quot;, __FUNCTIONW__);

    // 附加测试：把 SimpleDll.dll 注入到 mysqld.exe (PID 5552)
    InjectDll idl(5552, &quot;C:\MYSQLPLUGIN64.dll&quot;);
    idl.SetCheckEnvValue(&quot;MYSQLD_WINDOWS_SERVICE&quot;);
    idl.Inject(InjectDll::INJECT_NT_CREATETH);   // 注入方式之一

    return 0;
}



                  注入逻辑只是附加功能 



本目录的 InjectDll / ProcessHelper / SimpleDll 均服务于这个测试性注入功能，用来证明”服务主进程在 MyServiceWorker 里能驱动真实业务”。
若只关注服务本身的框架，看本文 _tmain → MyServiceMain → HandlerEx → ReportServiceStatus 这条主线即可；注入相关的三种方式、DLL 内容等，属于测试业务的延伸。

a_os/windows/权限与会话/privilege's-constants.content:

                  概述 



阅读这篇文章你可以了解：

Constants 是什么
windows提权时常用的 Constants
微软官方文档：Privilege Constants (Winnt.h) - Win32 apps | Microsoft Learn




介绍
Constants
Constants 即常用权限对应字符串，微软通过宏定义的方式对 Constants 进行了罗列。如常见使用的 SeDebugPrivilege 对应的宏定义即为 SE_DEBUG_NAME，下表所示为常见的 Constant 对应的 value 和描述。

























































































































































Constant/valueDescriptionSE_ASSIGNPRIMARYTOKEN_NAMETEXT(“SeAssignPrimaryTokenPrivilege”)Required to assign the primary token of a process. User Right: Replace a process-level token.SE_AUDIT_NAMETEXT(“SeAuditPrivilege”)Required to generate audit-log entries. Give this privilege to secure servers. User Right: Generate security audits.SE_BACKUP_NAMETEXT(“SeBackupPrivilege”)Required to perform backup operations. This privilege causes the system to grant all read access control to any file, regardless of the access control list (ACL) specified for the file. Any access request other than read is still evaluated with the ACL. This privilege is required by the RegSaveKey and RegSaveKeyExfunctions. The following access rights are granted if this privilege is held: READ_CONTROLACCESS_SYSTEM_SECURITYFILE_GENERIC_READFILE_TRAVERSEUser Right: Back up files and directories. If the file is located on a removable drive and the “Audit Removable Storage” is enabled, the SE_SECURITY_NAME is required to have ACCESS_SYSTEM_SECURITY.SE_CHANGE_NOTIFY_NAMETEXT(“SeChangeNotifyPrivilege”)Required to receive notifications of changes to files or directories. This privilege also causes the system to skip all traversal access checks. It is enabled by default for all users. User Right: Bypass traverse checking.SE_CREATE_GLOBAL_NAMETEXT(“SeCreateGlobalPrivilege”)Required to create named file mapping objects in the global namespace during Terminal Services sessions. This privilege is enabled by default for administrators, services, and the local system account. User Right: Create global objects.SE_CREATE_PAGEFILE_NAMETEXT(“SeCreatePagefilePrivilege”)Required to create a paging file. User Right: Create a pagefile.SE_CREATE_PERMANENT_NAMETEXT(“SeCreatePermanentPrivilege”)Required to create a permanent object. User Right: Create permanent shared objects.SE_CREATE_SYMBOLIC_LINK_NAMETEXT(“SeCreateSymbolicLinkPrivilege”)Required to create a symbolic link. User Right: Create symbolic links.**SE_CREATE_TOKEN_NAME**TEXT(“SeCreateTokenPrivilege”)Required to create a primary token. User Right: Create a token object. You cannot add this privilege to a user account with the “Create a token object” policy. Additionally, you cannot add this privilege to an owned process using Windows APIs.Windows Server 2003 and Windows XP with SP1 and earlier: Windows APIs can add this privilege to an owned process.**SE_DEBUG_NAME**TEXT(“SeDebugPrivilege”)Required to debug and adjust the memory of a process owned by another account. User Right: Debug programs.**SE_DELEGATE_SESSION_USER_IMPERSONATE_NAME**TEXT(“SeDelegateSessionUserImpersonatePrivilege”)Required to obtain an impersonation token for another user in the same session. User Right: Impersonate other users.SE_ENABLE_DELEGATION_NAMETEXT(“SeEnableDelegationPrivilege”)Required to mark user and computer accounts as trusted for delegation. User Right: Enable computer and user accounts to be trusted for delegation.SE_IMPERSONATE_NAMETEXT(“SeImpersonatePrivilege”)Required to impersonate. User Right: Impersonate a client after authentication.SE_INC_BASE_PRIORITY_NAMETEXT(“SeIncreaseBasePriorityPrivilege”)Required to increase the base priority of a process. User Right: Increase scheduling priority.SE_INCREASE_QUOTA_NAMETEXT(“SeIncreaseQuotaPrivilege”)Required to increase the quota assigned to a process. User Right: Adjust memory quotas for a process.**SE_INC_WORKING_SET_NAME**TEXT(“SeIncreaseWorkingSetPrivilege”)Required to allocate more memory for applications that run in the context of users. User Right: Increase a process working set.**SE_LOAD_DRIVER_NAME**TEXT(“SeLoadDriverPrivilege”)Required to load or unload a device driver. User Right: Load and unload device drivers.**SE_LOCK_MEMORY_NAME**TEXT(“SeLockMemoryPrivilege”)Required to lock physical pages in memory. User Right: Lock pages in memory.**SE_MACHINE_ACCOUNT_NAME**TEXT(“SeMachineAccountPrivilege”)Required to create a computer account. User Right: Add workstations to domain.SE_MANAGE_VOLUME_NAMETEXT(“SeManageVolumePrivilege”)Required to enable volume management privileges. User Right: Manage the files on a volume.SE_PROF_SINGLE_PROCESS_NAMETEXT(“SeProfileSingleProcessPrivilege”)Required to gather profiling information for a single process. User Right: Profile single process.SE_RELABEL_NAMETEXT(“SeRelabelPrivilege”)Required to modify the mandatory integrity level of an object. User Right: Modify an object label.**SE_REMOTE_SHUTDOWN_NAME**TEXT(“SeRemoteShutdownPrivilege”)Required to shut down a system using a network request. User Right: Force shutdown from a remote system.SE_RESTORE_NAMETEXT(“SeRestorePrivilege”)Required to perform restore operations. This privilege causes the system to grant all write access control to any file, regardless of the ACL specified for the file. Any access request other than write is still evaluated with the ACL. Additionally, this privilege enables you to set any valid user or group SID as the owner of a file. This privilege is required by the RegLoadKey function. The following access rights are granted if this privilege is held: WRITE_DACWRITE_OWNERACCESS_SYSTEM_SECURITYFILE_GENERIC_WRITEFILE_ADD_FILEFILE_ADD_SUBDIRECTORYDELETEUser Right: Restore files and directories. If the file is located on a removable drive and the “Audit Removable Storage” is enabled, the SE_SECURITY_NAME is required to have ACCESS_SYSTEM_SECURITY.SE_SECURITY_NAMETEXT(“SeSecurityPrivilege”)Required to perform a number of security-related functions, such as controlling and viewing audit messages. This privilege identifies its holder as a security operator. User Right: Manage auditing and security log.SE_SHUTDOWN_NAMETEXT(“SeShutdownPrivilege”)Required to shut down a local system. User Right: Shut down the system.SE_SYNC_AGENT_NAMETEXT(“SeSyncAgentPrivilege”)Required for a domain controller to use the Lightweight Directory Access Protocol directory synchronization services. This privilege enables the holder to read all objects and properties in the directory, regardless of the protection on the objects and properties. By default, it is assigned to the Administrator and LocalSystem accounts on domain controllers. User Right: Synchronize directory service data.SE_SYSTEM_ENVIRONMENT_NAMETEXT(“SeSystemEnvironmentPrivilege”)Required to modify the nonvolatile RAM of systems that use this type of memory to store configuration information. User Right: Modify firmware environment values.SE_SYSTEM_PROFILE_NAMETEXT(“SeSystemProfilePrivilege”)Required to gather profiling information for the entire system. User Right: Profile system performance.SE_SYSTEMTIME_NAMETEXT(“SeSystemtimePrivilege”)Required to modify the system time. User Right: Change the system time.SE_TAKE_OWNERSHIP_NAMETEXT(“SeTakeOwnershipPrivilege”)Required to take ownership of an object without being granted discretionary access. This privilege allows the owner value to be set only to those values that the holder may legitimately assign as the owner of an object. User Right: Take ownership of files or other objects.**SE_TCB_NAME**TEXT(“SeTcbPrivilege”)This privilege identifies its holder as part of the trusted computer base. Some trusted protected subsystems are granted this privilege. User Right: Act as part of the operating system.**SE_TIME_ZONE_NAME**TEXT(“SeTimeZonePrivilege”)Required to adjust the time zone associated with the computer’s internal clock. User Right: Change the time zone.SE_TRUSTED_CREDMAN_ACCESS_NAMETEXT(“SeTrustedCredManAccessPrivilege”)Required to access Credential Manager as a trusted caller. User Right: Access Credential Manager as a trusted caller.SE_UNDOCK_NAMETEXT(“SeUndockPrivilege”)Required to undock a laptop. User Right: Remove computer from docking station.**SE_UNSOLICITED_INPUT_NAME**TEXT(“SeUnsolicitedInputPrivilege”)Required to read unsolicited input from a terminal device. User Right: Not applicable.
用法
value不同，对应的操作和权限也不同，本文列举了有关 Privilege Constants 的一些使用方式。
LookupPrivilegeValue 查找权限
查找权限
C++cppBOOL EnablePrivilege()
{
    LUID PrivilegeRequired ;
    BOOL bRes = FALSE;

    bRes = LookupPrivilegeValue(NULL, SE_DEBUG_NAME, &amp;PrivilegeRequired);

    // ...

    return bRes;
}
AdjustTokenPrivileges 修改权限
C++cppinline BOOL CToolhelp::EnablePrivilege(PCTSTR szPrivilege, BOOL fEnable) {

   // Enabling the debug privilege allows the application to see
   // information about service applications
   BOOL fOk = FALSE;    // Assume function fails
   HANDLE hToken;

   // Try to open this process&#039;s access token
   if (OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES, 
      &amp;hToken)) {

      // Attempt to modify the given privilege
      TOKEN_PRIVILEGES tp;
      tp.PrivilegeCount = 1;
      LookupPrivilegeValue(NULL, szPrivilege, &amp;tp.Privileges[0].Luid);
      tp.Privileges[0].Attributes = fEnable ? SE_PRIVILEGE_ENABLED : 0;
      AdjustTokenPrivileges(hToken, FALSE, &amp;tp, sizeof(tp), NULL, NULL);
      fOk = (GetLastError() == ERROR_SUCCESS);

      // Don&#039;t forget to close the token handle
      CloseHandle(hToken);
   }
   return(fOk);
}

