a_os/windows/权限与会话/service降权启动进程.content:

                  概述 



windows 服务中以管理员或普通权限启动进程



背景知识：UAC 与 Token 机制
在 Windows Vista 引入 UAC（User Account Control）之后，管理员账户登录时会得到两个令牌：

















令牌类型说明Filtered Token（过滤令牌）默认分配给 explorer.exe 等用户进程，权限被削减Linked Token（链接令牌）完整管理员权限令牌，仅在用户”以管理员身份运行”时激活
因此，从 explorer.exe 获取的令牌不一定是管理员令牌——UAC 开启时拿到的是 filtered token（普通用户权限）。
关键 API





















API作用GetTokenInformation(TokenElevation)检查令牌是否已提升（elevated）GetTokenInformation(TokenLinkedToken)获取与 filtered token 关联的 linked token（完整管理员令牌）DuplicateTokenEx复制令牌，生成可用于 CreateProcessAsUser 的主令牌
判断逻辑
graph TD
    A[&quot;explorer.exe 的令牌&quot;] --&gt; B{TokenElevation?}
    B -- &quot;== TRUE&lt;br/&gt;UAC 关闭或已提权&quot; --&gt; C[&quot;已是管理员令牌&quot;]
    C --&gt; D[&quot;直接使用&quot;]
    B -- &quot;== FALSE&lt;br/&gt;UAC 已降权 (filtered token)&quot; --&gt; E[&quot;取 TokenLinkedToken&quot;]
    E --&gt; F[&quot;获得完整管理员令牌&quot;]

管理员权限启动进程
C++cpp// 管理员权限启动进程
#ifdef UNICODE
MMSYSSHARED_EXPORT bool CreateProcessWithAdmin(const std::wstring&amp; exe, const std::wstring&amp; param, bool show)
#else
MMSYSSHARED_EXPORT bool CreateProcessWithAdmin(const std::string&amp; exe, const std::string&amp; param, bool show)
#endif // UNICODE
{
    HANDLE hToken{ NULL };
    HANDLE hTokenDup{ NULL };
    LPVOID pEnvironment{ NULL };
    bool res{ false };
#ifdef UNICODE
    wchar_t* cmd = (wchar_t*)param.c_str();
#else
    char* cmd = (wchar_t*)param.c_str();
#endif

    do
    {
        if (exe.empty())
        {
            LOG_ERROR(&quot;exe is null!&quot;);
            break;
        }

        if (!GetTokenWithProcessName(L&quot;explorer.exe&quot;, hToken))
        {
            LOG_ERROR(&quot;GetTokenWithProcessName Error: %u&quot;, GetLastError());
            break;
        }

        // ★ 检查令牌是否已提升（UAC 判断）
        // explorer.exe 在 UAC 开启时持有的是 filtered token（未提升）
        // 需要通过 TokenLinkedToken 获取完整管理员令牌
        TOKEN_ELEVATION elevation = { 0 };
        DWORD dwSize = 0;
        if (GetTokenInformation(hToken, TokenElevation, &amp;elevation, sizeof(elevation), &amp;dwSize))
        {
            if (!elevation.TokenIsElevated)
            {
                // 当前是 filtered token，获取 linked token（完整管理员令牌）
                TOKEN_LINKED_TOKEN linked = { 0 };
                DWORD dwLinkedSize = 0;
                if (GetTokenInformation(hToken, TokenLinkedToken, &amp;linked, sizeof(linked), &amp;dwLinkedSize))
                {
                    CloseHandle(hToken);
                    hToken = linked.LinkedToken;
                }
                else
                {
                    LOG_ERROR(&quot;GetTokenInformation(TokenLinkedToken) Error: %u&quot;, GetLastError());
                    // 无法获取 linked token，继续使用原令牌（降级为普通用户权限）
                }
            }
        }

        // 复制令牌,把调用方有效的所有访问权限给复制后的令牌.
        if (!DuplicateTokenEx(hToken, MAXIMUM_ALLOWED/*TOKEN_ALL_ACCESS*/, NULL/*&amp;sa*/, SecurityImpersonation, TokenPrimary, &amp;hTokenDup))
        {
            LOG_ERROR(&quot;DuplicateTokenEx Error: %u&quot;, GetLastError());
            break;
        }
        STARTUPINFO si;
        ZeroMemory(&amp;si, sizeof(STARTUPINFO));
        si.cb = sizeof(STARTUPINFO);
#ifdef UNICODE
        wchar_t desk[]{ TEXT(&quot;WinSta0\\Default&quot;) };
#else
        char desk[]{ TEXT(&quot;WinSta0\\Default&quot;) };
#endif
        si.lpDesktop = desk;
        if (show)
        {
            si.wShowWindow = SW_SHOW;
        }
        else
        {
            si.wShowWindow = SW_HIDE;
        }
        si.dwFlags = STARTF_USESHOWWINDOW;
        PROCESS_INFORMATION pi;
        // 检索指定用户的环境变量。然后，可以将此块传递给 CreateProcessAsUser 函数。
        if (!CreateEnvironmentBlock(&amp;pEnvironment, hTokenDup, FALSE))
        {
            LOG_ERROR(&quot;CreateEnvironmentBlock Error: %u&quot;, GetLastError());
            break;
        }
        // 缺少环境变量时某些依赖环境变量的程序打不开，或者运行不正常。
        if (!CreateProcessAsUser(hTokenDup, exe.c_str(), cmd, NULL, NULL, FALSE
            , NORMAL_PRIORITY_CLASS 
            /*| CREATE_NEW_CONSOLE  */ 
            | CREATE_UNICODE_ENVIRONMENT
            , pEnvironment, NULL, &amp;si, &amp;pi))
        {
            LOG_ERROR(&quot;CreateProcessAsUser Error: %u&quot;, GetLastError());
            break;
        }
        res = true;
    } while (0);
    // 清理
    if (cmd)
    {
        delete[]cmd;
    }
    if (pEnvironment)
    {
        DestroyEnvironmentBlock(pEnvironment);
    }
    if(hToken)
        CloseHandle(hToken);
    if (hTokenDup)
        CloseHandle(hTokenDup);
    return res;
}
普通用户权限启动进程
C++cpp// 普通用户权限启动进程
#ifdef UNICODE
bool CreateProcessWithUser(const std::wstring&amp; exePath, const std::wstring&amp; param, bool show)
#else
bool CreateProcessWithUser(const std::string&amp; exePath, const std::string&amp; param, bool show)
#endif // UNICODE
{
    HANDLE hToken = 0;
    HANDLE hNewToken = 0;
    LPVOID pEnvironment{ NULL };
    bool res{ false };
    int l = param.length();
#ifdef UNICODE
    wchar_t* cmd = new wchar_t[l + 1];
    memcpy(cmd, param.c_str(), l * sizeof(wchar_t));
    cmd[l] = 0;
#else
    char* cmd = new char[l + 1];
    memcpy(cmd, param.c_str(), l * sizeof(char));
    cmd[l] = 0;
#endif // UNICODE

    do 
    {
        if (!GetTokenWithProcessName(L&quot;explorer.exe&quot;, hToken))
        {
            LOG_ERROR(&quot;GetTokenWithProcessName Error: %u&quot;, GetLastError());
            break;
        }

        // ★ 确保使用的是 filtered token（普通用户权限）
        // 如果 explorer.exe 持有的恰好是提升后的令牌（UAC 关闭场景），
        // 则无需处理；UAC 开启时 explorer.exe 持有的就是 filtered token
        TOKEN_ELEVATION elevation = { 0 };
        DWORD dwSize = 0;
        if (GetTokenInformation(hToken, TokenElevation, &amp;elevation, sizeof(elevation), &amp;dwSize))
        {
            if (elevation.TokenIsElevated)
            {
                // UAC 关闭场景：explorer.exe 持有完整管理员令牌
                // 此处不做降权处理，因为无法从完整令牌&quot;降回&quot; filtered token
                // 如需严格降权，应使用 CreateRestrictedToken 或以其他方式获取低权限令牌
                LOG_ERROR(&quot;Warning: explorer.exe token is elevated, process will run with admin rights&quot;);
            }
        }

        if (!DuplicateTokenEx(hToken, TOKEN_ALL_ACCESS, NULL/*&amp;sa*/, SECURITY_MAX_IMPERSONATION_LEVEL, TokenPrimary, &amp;hNewToken))
        {
            LOG_ERROR(&quot;DuplicateTokenEx Error: %u&quot;, GetLastError());
            break;
        }
        DWORD dwCreationFlag = NORMAL_PRIORITY_CLASS /*| CREATE_NEW_CONSOLE*/ | CREATE_UNICODE_ENVIRONMENT;
        // 检索指定用户的环境变量。然后，可以将此块传递给 CreateProcessAsUser 函数。
        if (!CreateEnvironmentBlock(&amp;pEnvironment, hNewToken, FALSE))
        {
            LOG_ERROR(&quot;CreateEnvironmentBlock Error: %u&quot;, GetLastError());
            break;
        }
        STARTUPINFO si;
        PROCESS_INFORMATION pi;
        ZeroMemory(&amp;si, sizeof(STARTUPINFO));
        si.cb = sizeof(STARTUPINFO);
#ifdef UNICODE
        wchar_t desktop[] = L&quot;winsta0\\default&quot;;
#else
        char desktop[] = &quot;winsta0\\default&quot;;
#endif 
        si.lpDesktop = desktop;
        si.dwFlags = STARTF_USESHOWWINDOW;
        if (show)
        {
            si.wShowWindow = SW_SHOW;
        }
        else
        {
            si.wShowWindow = SW_HIDE;
        }
        if (!CreateProcessAsUser(hNewToken, exePath.c_str(), cmd, 0, 0, FALSE, dwCreationFlag, pEnvironment, 0, &amp;si, &amp;pi))
        {
#ifdef UNICODE
            std::string ansicmd = mm::Charset::UnicodeToANSI(cmd);
            std::string ansibat = mm::Charset::UnicodeToANSI(exePath.c_str());
            LOG_ERROR(&quot;CreateProcessAsUser error! LastError=%ld, %s, %s&quot;, GetLastError(), ansibat.c_str(), ansicmd.c_str());
#else
            LOG_ERROR(&quot;CreateProcessAsUser error! LastError=%ld, %s, %s&quot;, GetLastError(), exePath.c_str(), cmd.c_str());
#endif // UNICODE
            break;
        }
        res = true;
    } while (0);
    // 清理
    delete[] cmd;
    if (hToken)
    {
        CloseHandle(hToken);
    }
    if (hNewToken) 
    {
        CloseHandle(hNewToken);
    }
    if (pEnvironment)
    {
        DestroyEnvironmentBlock(pEnvironment);
    }
    return res;
}
