完整 Demo 源码



                  INFO



以下为自包含的控制台 Demo 源码，去除了 MMSYSSHARED_EXPORT、LOG_ERROR、mm::Charset 等项目依赖，可直接编译运行。
项目地址：Windows-API-Usage/WinAPI/ServiceCreateProcessDemo/


C++cpp// ServiceCreateProcessDemo.cpp
// 演示在 Windows 服务中以管理员/普通用户权限启动进程
//
// 关键知识点：
//   1. UAC 开启时 explorer.exe 持有 filtered token（普通用户权限）
//      需通过 TokenLinkedToken 获取完整管理员令牌
//   2. UAC 关闭时 explorer.exe 持有完整管理员令牌
//      无法降级为 filtered token，CreateProcessWithUser 会发出警告
//   3. 两个函数的核心差异不在 DuplicateTokenEx 参数，
//      而在于是否通过 GetTokenInformation 做权限提升/验证

#include &lt;windows.h&gt;
#include &lt;tlhelp32.h&gt;
#include &lt;userenv.h&gt;
#include &lt;stdio.h&gt;
#include &lt;tchar.h&gt;
#include &lt;string&gt;

#pragma comment(lib, &quot;userenv.lib&quot;)

using namespace std;

// ============================================================================
// 根据进程名获取进程令牌
// ============================================================================
bool GetTokenWithProcessName(const wchar_t* szName, HANDLE&amp; hToken)
{
    HANDLE hProcessSnap = NULL;
    PROCESSENTRY32W pe32 = { 0 };
    HANDLE hProcess = NULL;
    bool res = false;

    do
    {
        hProcessSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (hProcessSnap == INVALID_HANDLE_VALUE)
        {
            wprintf(L&quot;[-] CreateToolhelp32Snapshot failed: %lu\n&quot;, GetLastError());
            break;
        }

        pe32.dwSize = sizeof(PROCESSENTRY32W);
        if (!Process32FirstW(hProcessSnap, &amp;pe32))
        {
            wprintf(L&quot;[-] Process32FirstW failed: %lu\n&quot;, GetLastError());
            break;
        }

        do
        {
            if (_wcsicmp(pe32.szExeFile, szName) != 0)
                continue;

            hProcess = OpenProcess(PROCESS_QUERY_INFORMATION, FALSE, pe32.th32ProcessID);
            if (!hProcess)
            {
                wprintf(L&quot;[-] OpenProcess failed: %lu\n&quot;, GetLastError());
                break;
            }

            if (!OpenProcessToken(hProcess, TOKEN_ALL_ACCESS, &amp;hToken))
            {
                wprintf(L&quot;[-] OpenProcessToken failed: %lu\n&quot;, GetLastError());
                break;
            }

            res = true;
            break;
        } while (Process32NextW(hProcessSnap, &amp;pe32));
    } while (false);

    if (hProcessSnap)
        CloseHandle(hProcessSnap);
    if (hProcess)
        CloseHandle(hProcess);

    return res;
}

// ============================================================================
// 以管理员权限启动进程
// 从 explorer.exe 获取令牌后，检查 UAC 状态：
//   - TokenElevation == FALSE → filtered token，需获取 TokenLinkedToken（完整管理员令牌）
//   - TokenElevation == TRUE  → 已是管理员令牌，直接使用
// ============================================================================
bool CreateProcessWithAdmin(const std::wstring&amp; exe, const std::wstring&amp; param, bool show)
{
    HANDLE hToken = NULL;
    HANDLE hTokenDup = NULL;
    LPVOID pEnvironment = NULL;
    bool res = false;

    do
    {
        if (exe.empty())
        {
            wprintf(L&quot;[-] exe path is empty\n&quot;);
            break;
        }

        if (!GetTokenWithProcessName(L&quot;explorer.exe&quot;, hToken))
        {
            wprintf(L&quot;[-] GetTokenWithProcessName failed: %lu\n&quot;, GetLastError());
            break;
        }

        // ★ UAC 权限提升：检查 explorer.exe 令牌是否已提升
        TOKEN_ELEVATION elevation = { 0 };
        DWORD dwSize = 0;
        if (GetTokenInformation(hToken, TokenElevation, &amp;elevation, sizeof(elevation), &amp;dwSize))
        {
            if (!elevation.TokenIsElevated)
            {
                wprintf(L&quot;[*] Token is not elevated (UAC filtered), obtaining linked token...\n&quot;);
                // filtered token → 获取 linked token（完整管理员令牌）
                TOKEN_LINKED_TOKEN linked = { 0 };
                DWORD dwLinkedSize = 0;
                if (GetTokenInformation(hToken, TokenLinkedToken, &amp;linked, sizeof(linked), &amp;dwLinkedSize))
                {
                    CloseHandle(hToken);
                    hToken = linked.LinkedToken;
                    wprintf(L&quot;[+] Linked token obtained (full admin rights)\n&quot;);
                }
                else
                {
                    wprintf(L&quot;[-] GetTokenInformation(TokenLinkedToken) failed: %lu\n&quot;, GetLastError());
                    wprintf(L&quot;    Continuing with filtered token (non-elevated)\n&quot;);
                }
            }
            else
            {
                wprintf(L&quot;[*] Token is already elevated (UAC disabled or already admin)\n&quot;);
            }
        }

        if (!DuplicateTokenEx(hToken, MAXIMUM_ALLOWED, NULL, SecurityImpersonation, TokenPrimary, &amp;hTokenDup))
        {
            wprintf(L&quot;[-] DuplicateTokenEx failed: %lu\n&quot;, GetLastError());
            break;
        }

        STARTUPINFOW si = { 0 };
        si.cb = sizeof(STARTUPINFOW);
        si.lpDesktop = (LPWSTR)L&quot;WinSta0\\Default&quot;;
        si.wShowWindow = show ? SW_SHOW : SW_HIDE;
        si.dwFlags = STARTF_USESHOWWINDOW;

        PROCESS_INFORMATION pi = { 0 };

        if (!CreateEnvironmentBlock(&amp;pEnvironment, hTokenDup, FALSE))
        {
            wprintf(L&quot;[-] CreateEnvironmentBlock failed: %lu\n&quot;, GetLastError());
            break;
        }

        // 构建命令行（可变参数需要可写缓冲区）
        std::wstring cmdLine = param;

        if (!CreateProcessAsUserW(hTokenDup, exe.c_str(),
            cmdLine.empty() ? NULL : &amp;cmdLine[0],
            NULL, NULL, FALSE,
            NORMAL_PRIORITY_CLASS | CREATE_UNICODE_ENVIRONMENT,
            pEnvironment, NULL, &amp;si, &amp;pi))
        {
            wprintf(L&quot;[-] CreateProcessAsUserW failed: %lu\n&quot;, GetLastError());
            break;
        }

        wprintf(L&quot;[+] Process created successfully (PID: %lu)\n&quot;, pi.dwProcessId);

        CloseHandle(pi.hThread);
        CloseHandle(pi.hProcess);
        res = true;
    } while (false);

    if (pEnvironment)
        DestroyEnvironmentBlock(pEnvironment);
    if (hToken)
        CloseHandle(hToken);
    if (hTokenDup)
        CloseHandle(hTokenDup);

    return res;
}

// ============================================================================
// 以普通用户权限启动进程
// 从 explorer.exe 获取令牌后，检查 UAC 状态：
//   - TokenElevation == FALSE → filtered token，正是我们需要的（普通用户权限）
//   - TokenElevation == TRUE  → UAC 关闭，explorer.exe 持有完整管理员令牌
//     无法降级为 filtered token，发出警告（进程将以管理员权限运行）
// ============================================================================
bool CreateProcessWithUser(const std::wstring&amp; exePath, const std::wstring&amp; param, bool show)
{
    HANDLE hToken = NULL;
    HANDLE hNewToken = NULL;
    LPVOID pEnvironment = NULL;
    bool res = false;

    do
    {
        if (!GetTokenWithProcessName(L&quot;explorer.exe&quot;, hToken))
        {
            wprintf(L&quot;[-] GetTokenWithProcessName failed: %lu\n&quot;, GetLastError());
            break;
        }

        // ★ UAC 权限检查：确认使用的是 filtered token（普通用户权限）
        TOKEN_ELEVATION elevation = { 0 };
        DWORD dwSize = 0;
        if (GetTokenInformation(hToken, TokenElevation, &amp;elevation, sizeof(elevation), &amp;dwSize))
        {
            if (elevation.TokenIsElevated)
            {
                // UAC 关闭场景：explorer.exe 持有完整管理员令牌
                // 无法从完整令牌&quot;降回&quot; filtered token
                // 如需严格降权，应使用 CreateRestrictedToken 或以其他方式获取低权限令牌
                wprintf(L&quot;[!] Warning: token is elevated (UAC disabled), process will run with admin rights\n&quot;);
            }
            else
            {
                wprintf(L&quot;[*] Token is filtered (standard user rights)\n&quot;);
            }
        }

        if (!DuplicateTokenEx(hToken, TOKEN_ALL_ACCESS, NULL, SECURITY_MAX_IMPERSONATION_LEVEL, TokenPrimary, &amp;hNewToken))
        {
            wprintf(L&quot;[-] DuplicateTokenEx failed: %lu\n&quot;, GetLastError());
            break;
        }

        DWORD dwCreationFlag = NORMAL_PRIORITY_CLASS | CREATE_UNICODE_ENVIRONMENT;

        if (!CreateEnvironmentBlock(&amp;pEnvironment, hNewToken, FALSE))
        {
            wprintf(L&quot;[-] CreateEnvironmentBlock failed: %lu\n&quot;, GetLastError());
            break;
        }

        STARTUPINFOW si = { 0 };
        si.cb = sizeof(STARTUPINFOW);
        si.lpDesktop = (LPWSTR)L&quot;winsta0\\default&quot;;
        si.dwFlags = STARTF_USESHOWWINDOW;
        si.wShowWindow = show ? SW_SHOW : SW_HIDE;

        PROCESS_INFORMATION pi = { 0 };

        std::wstring cmdLine = param;

        if (!CreateProcessAsUserW(hNewToken, exePath.c_str(),
            cmdLine.empty() ? NULL : &amp;cmdLine[0],
            NULL, NULL, FALSE, dwCreationFlag,
            pEnvironment, NULL, &amp;si, &amp;pi))
        {
            wprintf(L&quot;[-] CreateProcessAsUserW failed: %lu\n&quot;, GetLastError());
            break;
        }

        wprintf(L&quot;[+] Process created successfully (PID: %lu)\n&quot;, pi.dwProcessId);

        CloseHandle(pi.hThread);
        CloseHandle(pi.hProcess);
        res = true;
    } while (false);

    if (pEnvironment)
        DestroyEnvironmentBlock(pEnvironment);
    if (hToken)
        CloseHandle(hToken);
    if (hNewToken)
        CloseHandle(hNewToken);

    return res;
}

// ============================================================================
// 主函数 - 用法演示
// ============================================================================
int wmain(int argc, wchar_t* argv[])
{
    wprintf(L&quot;=== Service Create Process Demo ===\n\n&quot;);

    if (argc &lt; 3)
    {
        wprintf(L&quot;Usage:\n&quot;);
        wprintf(L&quot;  %s --admin  &lt;exe_path&gt; [params]  - Launch with admin token (elevated via UAC linked token)\n&quot;, argv[0]);
        wprintf(L&quot;  %s --user   &lt;exe_path&gt; [params]  - Launch with user token (filtered, non-elevated)\n&quot;, argv[0]);
        wprintf(L&quot;\nExample:\n&quot;);
        wprintf(L&quot;  %s --admin  C:\\Windows\\System32\\notepad.exe\n&quot;, argv[0]);
        wprintf(L&quot;  %s --user   C:\\Windows\\System32\\notepad.exe\n&quot;, argv[0]);
        return 1;
    }

    // 校验 mode 是否合法，避免后续对未知模式无意义的处理
    std::wstring mode = argv[1];
    if (mode != L&quot;--admin&quot; &amp;&amp; mode != L&quot;--user&quot;)
    {
        wprintf(L&quot;[-] Unknown mode: %s\n&quot;, mode.c_str());
        wprintf(L&quot;    Use --admin or --user\n&quot;);
        return 1;
    }

    std::wstring exePath = argv[2];
    std::wstring params;
    if (argc &gt;= 4)
    {
        params = argv[3];
        for (int i = 4; i &lt; argc; i++)
        {
            params += L&quot; &quot;;
            params += argv[i];
        }
    }

    bool show = true;

    if (mode == L&quot;--admin&quot;)
    {
        wprintf(L&quot;[*] Creating process with admin token...\n&quot;);
        if (CreateProcessWithAdmin(exePath, params, show))
            wprintf(L&quot;[+] Success!\n&quot;);
        else
            wprintf(L&quot;[-] Failed!\n&quot;);
    }
    else if (mode == L&quot;--user&quot;)
    {
        wprintf(L&quot;[*] Creating process with user token...\n&quot;);
        if (CreateProcessWithUser(exePath, params, show))
            wprintf(L&quot;[+] Success!\n&quot;);
        else
            wprintf(L&quot;[-] Failed!\n&quot;);
    }
    else
    {
        wprintf(L&quot;[-] Unknown mode: %s\n&quot;, mode.c_str());
        wprintf(L&quot;    Use --admin or --user\n&quot;);
        return 1;
    }

    return 0;
}
