                        if (GetExitCodeThread(hThread, &amp;ec)) {
                            printf(&quot;  [ exit code was %lu (%08lX)&quot;, ec, ec);
                        }
                        CloseHandle(hThread);
                    }
                    else {
                        MessageBox(NULL, &quot;CreateRemoteThread&quot;, &quot;Notice&quot;, MB_ICONINFORMATION | MB_OK);
                    }
                }
                if (idx == 0) {
                    VirtualFreeEx(hProc, pCode, 0, MEM_RELEASE);
                    if (pData != NULL) {
                        VirtualFreeEx(hProc, pData, 0, MEM_RELEASE);
                    }
                }
            }
            else {
                MessageBox(NULL, &quot;VirtualFreeEx()&quot;, &quot;Notice&quot;, MB_ICONINFORMATION | MB_OK);
            }
            CloseHandle(hProc);
        }
        else {
            MessageBox(NULL, &quot;OpenProcess&quot;, &quot;Notice&quot;, MB_ICONINFORMATION | MB_OK);
        }
        if (CreateRemoteThread64 != NULL) free_func(CreateRemoteThread64);
        return bStatus;
    }
}

a_os/windows/注入与hook/detours的使用.content:
概述：Detours 的说明和简单使用

Detours
Detours 是微软提供的一套工具，主要用于win32 API的拦截
Github：microsoft/Detours: Detours is a software package for monitoring and instrumenting API calls on Windows. It is distributed in source code form.
仓库中有挺多示例程序可供参考。
使用 Detours 的大致流程：

在 Detours 的工作过程中，DetourTransactionBegin 函数首先用于启动一个截获（Hook）或解除截获（UnHook）的过程，这个过程中可能包含对多个函数的修改。然后，开发者可以使用 DetourAttach 或 DetourAttachEx 函数将 Detour 钩子附加到目标函数上，或使用 DetourDetach 函数将钩子从目标函数中分离出来。

相关函数说明
DetourAttach 函数说明
DetourAttach 是最常用的附加函数，将 Detour 钩子附加到目标函数上。
C++cppLONG DetourAttach(
    _Inout_ PVOID *ppPointer,   // 指向目标函数指针的指针（会被修改为指向 trampoline）
    _In_    PVOID  pDetour      // Detour 函数地址
);

ppPointer：传入时指向目标函数原地址，成功后会被修改为指向 trampoline（跳板代码），可在 Detour 函数中通过它调用原始函数
pDetour：你的 Hook 函数地址，签名必须与目标函数一致
返回值：NO_ERROR 表示成功


⚠️ DetourAttach 内部使用默认参数（5 字节跳转），对大多数 x86/x64 函数已足够。


DetourAttachEx 函数说明
DetourAttachEx 是 DetourAttach 的扩展版本，提供了对 Hook 过程更精细的控制，允许获取额外的诊断信息和控制桩（stub）的大小。
函数原型
C++cppLONG DetourAttachEx(
    _Inout_  PVOID   *ppPointer,    // 指向目标函数指针的指针
    _In_     PVOID    pDetour,      // Detour 函数地址
    _Out_    PDETOUR_TRAMPOLINE *ppRealTrampoline,  // 接收 trampoline 可执行代码的指针
    _Out_    PVOID   *ppRealTarget,  // 接收目标函数原始入口点
    _Out_    PVOID   *ppDetour       // 接收 detour 函数入口点
);
参数详解



































参数方向说明ppPointerIn/Out与 DetourAttach 相同。传入目标函数地址指针，成功后被修改为指向 trampoline（可用于调用原函数）pDetourIn你的 Hook 函数地址ppRealTrampolineOut接收 trampoline 可执行代码块的指针。trampoline 是 Detours 动态分配的一段可执行内存，包含被覆盖的原始指令 + 跳转回原函数剩余部分的代码。这个指针可以用于直接执行 trampoline 代码，而无需通过 ppPointer 间接调用ppRealTargetOut接收目标函数的 原始入口地址（即 Hook 前的函数起始地址）。这个值在 Hook 前后不变，始终指向原始函数的入口点ppDetourOut接收 Detour 函数的 入口地址。这个值在 Hook 前后不变，始终指向你的 Hook 函数入口
返回值

NO_ERROR（0）：成功
ERROR_INVALID_BLOCK：目标函数代码段过短，无法放置跳转指令
ERROR_INVALID_DATA：目标函数已有其他 Hook 或代码格式不支持
其他 Win32 错误码

与 DetourAttach 的区别



































特性DetourAttachDetourAttachEx基本附加功能✅✅获取 trampoline 代码指针❌✅ ppRealTrampoline获取原始入口地址❌✅ ppRealTarget获取 Detour 入口地址❌✅ ppDetour诊断/调试支持有限完整
使用场景

调试与诊断：获取 trampoline 和原始入口地址，用于验证 Hook 是否正确安装
多层 Hook 链：当你需要在多个 Hook 之间手动跳转时，ppRealTrampoline 提供了直接访问 trampoline 代码的能力
Hook 验证：对比 ppRealTarget 和 ppPointer 的值，确认 Hook 已正确生效
安全工具开发：在安全监控场景中，需要精确追踪每个 Hook 的安装状态和位置

使用示例
C++cpp#include &lt;iostream&gt;
#include &lt;Windows.h&gt;
#include &quot;detours.h&quot;
#pragma comment(lib, &quot;detours.lib&quot;)

using namespace std;

// 原函数指针
void (*OldGetLocalTime)(LPSYSTEMTIME) = GetLocalTime;

// Hook 函数
void NewGetLocalTime(LPSYSTEMTIME lpSystemTime) {
    OldGetLocalTime(lpSystemTime);
    lpSystemTime-&gt;wMinute = 52;
}

void StartHookEx() {
    DetourTransactionBegin();
    DetourUpdateThread(GetCurrentThread());

    // 扩展参数
    PDETOUR_TRAMPOLINE pRealTrampoline = nullptr;
    PVOID pRealTarget = nullptr;
    PVOID pDetourEntry = nullptr;

    LONG hr = DetourAttachEx(
        &amp;(PVOID&amp;)OldGetLocalTime,
        NewGetLocalTime,
        &amp;pRealTrampoline,
        &amp;pRealTarget,
        &amp;pDetourEntry
    );

    if (hr != NO_ERROR) {
        wprintf(L&quot;DetourAttachEx failed: %d\n&quot;, hr);
        DetourTransactionAbort();
        return;
    }

    LONG commitHR = DetourTransactionCommit();
    if (commitHR != NO_ERROR) {
        wprintf(L&quot;Transaction commit failed: %d\n&quot;, commitHR);
        return;
    }

    // 输出诊断信息
    wprintf(L&quot;[Hook 诊断信息]\n&quot;);
    wprintf(L&quot;  Trampoline 地址: %p\n&quot;, pRealTrampoline);
    wprintf(L&quot;  原始入口地址:    %p\n&quot;, pRealTarget);
    wprintf(L&quot;  Detour 入口地址: %p\n&quot;, pDetourEntry);
    wprintf(L&quot;  OldGetLocalTime:  %p (指向 trampoline)\n&quot;, OldGetLocalTime);
}

void EndHookEx() {
    DetourTransactionBegin();
    DetourUpdateThread(GetCurrentThread());
    DetourDetach(&amp;(PVOID&amp;)OldGetLocalTime, NewGetLocalTime);
    DetourTransactionCommit();
}

int main() {
    SYSTEMTIME time1, time2;
    GetLocalTime(&amp;time1);
    wprintf(L&quot;Hook 前: %02d:%02d\n&quot;, time1.wHour, time1.wMinute);

    StartHookEx();

    GetLocalTime(&amp;time2);
    wprintf(L&quot;Hook 后: %02d:%02d\n&quot;, time2.wHour, time2.wMinute);

    EndHookEx();
    return 0;
}
⚠️ 注意事项

ppRealTrampoline 指向可执行内存：该地址可以直接被调用（call），但不应被修改或释放——Detours 在 DetourDetach 时会自动处理
ppRealTarget 不等于 ppPointer 修改后的值：ppRealTarget 始终是原始函数入口地址，而 ppPointer 被修改后指向 trampoline 代码块。调用 trampoline（通过 ppPointer）等效于调用原始函数，但 trampoline 可能包含额外的指令修复
所有扩展参数都可以传 NULL：如果你不需要某个输出参数，传 NULL 即可，功能退化为 DetourAttach
线程安全：与 DetourAttach 一样，必须在事务内调用


DetourUpdateThread 函数说明
DetourUpdateThread 函数是 Detours 库中的一个重要函数，用于在 Detour 事务处理过程中将特定的线程列入更新范围。Detours 是一个用于在运行时修改二进制代码（如函数钩子）的库，它允许开发者在不修改原始代码的情况下，拦截和修改函数的执行流程。
DetourUpdateThread 函数的作用是在这个事务过程中，将一个或多个线程列入需要更新的范围。这是因为在多线程环境中，直接修改函数的代码可能会导致竞态条件，即一个线程正在执行原始代码时，另一个线程可能已经修改了该代码。通过 DetourUpdateThread 将线程列入更新范围，Detours 库可以确保在事务提交时，所有相关线程的代码都被正确地更新，从而避免竞态条件。
具体来说，DetourUpdateThread 函数的作用是：

将指定的线程加入到 Detour 事务的更新列表中。
在事务提交时，Detours 库会遍历这个更新列表，并对列表中的每个线程执行必要的代码更新操作。

需要注意的是，在调用 DetourTransactionCommit 或 DetourTransactionCommitEx 函数提交事务之前，所有的附加、分离和线程更新操作都不会生效。一旦事务被提交，所有的修改就会立即生效，所有相关线程的代码都会被更新以反映这些修改。
因此，DetourUpdateThread 函数是 Detours 库中用于确保多线程环境下代码修改一致性和安全性的重要工具之一。
可以看下 DetourUpdateThread 的源码，如下所示：
C++cppLONG WINAPI DetourUpdateThread(_In_ HANDLE hThread)
{
    LONG error;

    // If any of the pending operations failed, then we don&#039;t need to do this.
    if (s_nPendingError != NO_ERROR) {
        return s_nPendingError;
    }

    // Silently (and safely) drop any attempt to suspend our own thread.
    if (hThread == GetCurrentThread()) {
        return NO_ERROR;
    }

    DetourThread *t = new NOTHROW DetourThread;
    if (t == NULL) {
        error = ERROR_NOT_ENOUGH_MEMORY;
      fail:
        if (t != NULL) {
            delete t;
            t = NULL;
        }
        s_nPendingError = error;
        s_ppPendingError = NULL;
        DETOUR_BREAK();
        return error;
    }

    if (SuspendThread(hThread) == (DWORD)-1) {
        error = GetLastError();
        DETOUR_BREAK();
        goto fail;
    }

    t-&gt;hThread = hThread;
    t-&gt;pNext = s_pPendingThreads;
    s_pPendingThreads = t;

    return NO_ERROR;
}

hookDemo
修改 GetLocalTime ，使其返回的分钟数为 52
C++cpp#include &lt;iostream&gt;
#include &lt;Windows.h&gt;
//包含Detour的头文件和库文件
#include &quot;detours.h&quot;
#pragma comment (lib,&quot;detours.lib&quot;)
using namespace std;

//保存函数原型（用指针存储要拦截的API）
void (*OldGetLocalTime)(LPSYSTEMTIME) = GetLocalTime;

//拦截后要执行的操作（这里是将时间的分改为52）
void NewGetLocalTime(LPSYSTEMTIME lpSystemTime) {
	OldGetLocalTime(lpSystemTime);
	lpSystemTime-&gt;wMinute = 52;
}

//下钩子函数
void StartHook() {
	//开始事务
	DetourTransactionBegin();
	//更新线程信息
	DetourUpdateThread(GetCurrentThread());
	//将拦截的函数附加到原函数的地址上
	DetourAttach(&amp;(PVOID&amp;)OldGetLocalTime, NewGetLocalTime);
	//结束事务
	DetourTransactionCommit();
}

//撤钩子函数
void EndHook() {
	//开始detours事务
	DetourTransactionBegin();
	//更新线程信息 
	DetourUpdateThread(GetCurrentThread());
	//将拦截的函数从原函数的地址上解除
	DetourDetach(&amp;(PVOID&amp;)OldGetLocalTime, NewGetLocalTime);
	//结束detours事务
	DetourTransactionCommit();
}

int main()
{
	//获取本地时间
	SYSTEMTIME time, time2;
	GetLocalTime(&amp;time);
	cout &lt;&lt; time.wHour &lt;&lt; &quot;:&quot; &lt;&lt; time.wMinute &lt;&lt; endl;
	//下钩子
	StartHook();

	//下钩子后再次获取本地时间
	GetLocalTime(&amp;time2);
	cout &lt;&lt; time2.wHour &lt;&lt; &quot;:&quot; &lt;&lt; time2.wMinute &lt;&lt; endl;

	//撤钩子
	EndHook();
	return 0;
}

a_os/windows/注入与hook/hook模版.content:
概述Hook注入的模版函数，以Hook loadlibrary 为例

主要是创建了 __InlineHOOK_Base 用于实现函数的注入。
由于程序在创建和执行时会使用 LoadLibrary 函数。 因此需要在调用是时先 unhook 在
Hook模版
以下两宏定义即可完成函数的hook
C++cpp/*
    C/C++ HOOK API（原理深入剖析之-LoadLibraryA）_c++ loadlibrarya-CSDN博客: 
    blog.csdn.net/masefee/article/details/4566121
*/
#include &lt;iostream&gt;
#include &lt;Windows.h&gt;
using namespace std;

#pragma warning( disable: 4309 )
#pragma warning( disable: 4311 )

typedef HMODULE(WINAPI* HOOKAPI)(IN LPCSTR);
#define MYHOOKMETHOD(__fun) HMODULE WINAPI __fun
#define DECLARE_REGISTER( __0bj, __lawfunc, __newfunc ) Inline_Hook&lt; HOOKAPI, 1 &gt; __Obj( __lawfunc, __newfunc )

struct __InlineHOOK_Base
{
    DWORD _argsBytes;
    void* _lawFunc;
    void* _newFunc;
    char  _lawByteCode[16];
    char  _newByteCode[16];

    bool unhook(void)
    {
        // It&#039;s hooked.
        if (memcmp(_newByteCode, _lawFunc, 16) == 0)
        {
            DWORD dwOldFlag;
            VirtualProtect(_lawFunc, 8, PAGE_EXECUTE_READWRITE, &amp;dwOldFlag);
            memcpy(_lawFunc, _lawByteCode, 16);
            VirtualProtect(_lawFunc, 8, dwOldFlag, &amp;dwOldFlag);
            return true;
        }

        return false;
    }

    bool hook(void)
    {
        // It&#039;s saved.
        if (memcmp(_lawByteCode, _lawFunc, 16) == 0)
        {
            DWORD dwOldFlag;
            VirtualProtect(_lawFunc, 8, PAGE_EXECUTE_READWRITE, &amp;dwOldFlag);
            memcpy(_lawFunc, _newByteCode, 16);
            VirtualProtect(_lawFunc, 8, dwOldFlag, &amp;dwOldFlag);
            return true;
        }

        return false;
    }

    __InlineHOOK_Base(void* lawfun, void* newfun, DWORD args);
};


void __declspec(naked) __Inline_Hook_Func(void)
{
    __asm
    {
        push ebp  // save maybe usefull register.
        push ebx
        push esi
        push ecx
        call __InlineHOOK_Base::unhook  // first, remove the hook in order to call the normal function.
        test eax, eax   // check the remove was successful
        jz __return


    __getargnum :
        mov eax, dword ptr[esp] // esp just is ecx, also is __InlineHOOK_Base&#039;s this pointer.
        mov ecx, dword ptr[eax] // get first 4 bytes, that is params total size.
        shr ecx, 2  // get params num, equal with __InlineHOOK_Base::_argsBytes / sizeof( DWORD )
        test ecx, ecx   // check whether there are params.
        jz __callfunc   // no param


    __pushargs :
        mov edx, esp    // __InlineHOOK_Base&#039;s this pointer.
        add edx, 14h    // navigate to first call ret addr.
        add edx, dword ptr[eax]; // add params size.
        push dword ptr[edx];    // push the dll file name pointer.
        loop __pushargs


    __callfunc :
        call[eax + 8]   // call my function .
        mov ecx, dword ptr[esp]  // get __InlineHOOK_Base&#039;s this pointer.

        push edx        // save my function return value.
        push eax

        call __InlineHOOK_Base::hook   // rehook.

        pop eax                  // get saved return value, provided to my superiors to use
        pop edx


    __return :
        pop ecx
        pop esi
        pop ebx
        pop ebp
        ret
    }
}

__InlineHOOK_Base::__InlineHOOK_Base(void* lawfun, void* newfun, DWORD args)
    : _lawFunc(lawfun), _newFunc(newfun), _argsBytes(args * 4)
{
    _newByteCode[0] = 0xB9;     // mov ecx, ...
    (DWORD&amp;)_newByteCode[1] = (DWORD)this;
    _newByteCode[5] = 0xB8;     // mov eax, ...
    (DWORD&amp;)_newByteCode[6] = (DWORD)__Inline_Hook_Func;
    (WORD&amp;)_newByteCode[10] = 0xD0FF;       // call eax
    _newByteCode[12] = 0x000000C3;          // ret

    if (args &gt; 0)
    {
        _newByteCode[12] = 0xC2;        // ret ...
        (WORD&amp;)_newByteCode[13] = (WORD)_argsBytes;
        _newByteCode[15] = 0;
    }

    memcpy(_lawByteCode, _lawFunc, 16); // save
}


template&lt; typename _function, DWORD args &gt;
struct Inline_Hook : __InlineHOOK_Base
{
    Inline_Hook(_function lawfun, _function newfun)
        :__InlineHOOK_Base(lawfun, newfun, args) {
        hook();
    }
    ~Inline_Hook(void) { unhook(); }
};

MYHOOKMETHOD(myLoadLibrary)(LPCSTR lpcStrFileName)
{
    ::MessageBoxA(NULL, lpcStrFileName, &quot;LoadLibrary Name&quot;, MB_OK | MB_ICONINFORMATION);
    return LoadLibraryA(lpcStrFileName);
}


DECLARE_REGISTER(__inline_hook, LoadLibraryA, myLoadLibrary);


int main(void)
{
    HMODULE hIntstance = LoadLibraryA(&quot;d3d9.dll&quot;);
    return 0;
}
如何使用，使用宏进行注入，在程序执行前完成。
C++cppDECLARE_REGISTER(__inline_hook, LoadLibraryA, myLoadLibrary);

a_os/windows/注入与hook/dll注入.content:

                  概述：windows 操作系统下注入dll到进程中 



环境相关：win10操作系统注入本地编译的简单dll到notepad.exe
其他问题补充： CreateRemoteThread函数多参数传入使用方法_createremotethread 传递参数-CSDN博客
多参数问题：lem0nSec/CreateRemoteThreadPlus: CreateRemoteThread: how to pass multiple parameters to the remote thread function without shellcode.






                  相关文章推荐 




破碎注入-无痕注入不使用任何进程句柄的注入技术原理分析 | 杨CC 技术录




基本知识
注入dll的简单逻辑就是要在目标进程申请内存加载一个dll。分步骤来说就是：

打开进程
申请内存
写入内存
调用内存的函数

操作步骤
前提

进程间内存独立


运行在安全模式下的Windows，每个进程的内存空间都是独立的，互相不能访问彼此，所以代码注入才是一件比较麻烦的事情


所有进程中 kernel32.dll地址相同


每个进程都会加载kernel32.dll，并且在那些进程中，这个库的地址都是一样的

原理
DLL注入主要分为如下几个步骤
-提权：如果提权的话，进程列表中很多进程是打不开的，并且可能获取不到PROCESS_ALL_ACCESS权限

获取PID：这部分不是必须的，但是PID每次运行都不一样，所以最好能获取，这里通过CreateToolhelp32Snapshot()函数获取进程，遍历结果之后得到对应的PID
打开进程：通过OpenProcess()函数打开进程，同时指定权限是PROCESS_ALL_ACCESS权限，否则后面操作会失败，如果要获取这个权限就得先提权
通过VirtualAllocEx()函数在目标进程中申请内存，然后用WriteProcessMemory()函数将LoadLibraey()函数的参数准备好写入到内存中
通过LoadLibrary()函数加载kernel32.dll，实际上进程都会加载这个，第二次加载似乎直接获取模块句柄了。
通过GetProcAddress()函数获取到LoadLibraryW()函数的地址，因为kernel32.dll在所有进程中的地址都相同，所以，在本进程中获取的函数地址在目标进程中也是那个函数
通过CreateRemoteThread()函数在目标进程中创建一个线程，执行LoadLibraryW()函数载入自己的dll

代码
InjectDll.exe
InjectDll.exe 的代码如下所示：
完成了注入 simpledll.dll 到 notepad.exe 的功能
C++cpp#include &lt;windows.h&gt;
#include &lt;iostream&gt;
#include &lt;tlhelp32.h&gt;

using namespace std;

DWORD GetPidByName(LPCWSTR lpName)
{
	DWORD pid = 0;

	HANDLE hSnap = ::CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
	if (!hSnap)
	{
		cout &lt;&lt; &quot;Create Process Snap failed&quot; &lt;&lt; endl;
		return 0;
	}

	PROCESSENTRY32 pe;
	pe.dwSize = sizeof(PROCESSENTRY32);
	Process32First(hSnap, &amp;pe);

	do {
		if (!_wcsicmp(lpName, pe.szExeFile))
		{
			return pe.th32ProcessID;
		}
	} while (Process32Next(hSnap, &amp;pe));

	return pid;
}

bool EnableDebugPrivilege()
{
	bool bRet = false;

	HANDLE token;
	TOKEN_PRIVILEGES tp;
	// 打开进程令牌环
	if (!OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &amp;token))
	{
		cout &lt;&lt; &quot;Open Toekn Failed&quot; &lt;&lt; endl;
		return bRet;
	}

	// 获取进程uuid
	LUID luid;
	if (!LookupPrivilegeValue(NULL, SE_DEBUG_NAME, &amp;luid))
	{
		cout &lt;&lt; &quot;Get uid failed&quot; &lt;&lt; endl;
		return bRet;
	}

	tp.PrivilegeCount = 1;
	tp.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
	tp.Privileges[0].Luid = luid;

	// 调整进程权限
	if (!AdjustTokenPrivileges(token, 0, &amp;tp, sizeof(TOKEN_PRIVILEGES), NULL, NULL))
	{
		cout &lt;&lt; &quot;Adjust Privilege failed&quot; &lt;&lt; endl;
		return bRet;
	}

	bRet = true;

	return bRet;
}

int main(char* argc, const char* argv[])
{
	// 先提权
	if (!EnableDebugPrivilege())
	{
		cout &lt;&lt; &quot;提权失败&quot; &lt;&lt; endl;
		return 0;
	}

	DWORD dwTargetPid = GetPidByName(L&quot;notepad.exe&quot;);
	if (!dwTargetPid)
	{
		cout &lt;&lt; &quot;Get Target Process Id failed&quot; &lt;&lt; endl;
		return 0;
	}

	// 打开目标进程
	HANDLE hTarget = OpenProcess(PROCESS_ALL_ACCESS, false, dwTargetPid);
	if (!hTarget)
	{
		cout &lt;&lt; &quot;Open Target Process failed&quot; &lt;&lt; endl;
		return 0;
	}

	// 在目标进程申请内存
	void* pLoadLibFuncParam = nullptr;
	pLoadLibFuncParam = VirtualAllocEx(hTarget, 0, 4096, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
	if (pLoadLibFuncParam == nullptr)
	{
		cout &lt;&lt; &quot;alloc memery failed&quot; &lt;&lt; endl;
		CloseHandle(hTarget);
		return 0;
	}

	LPCTSTR lpParam = L&quot;C:\\6\\SimpleDll.dll&quot;;
	if (!WriteProcessMemory(hTarget, pLoadLibFuncParam, (LPCVOID)lpParam, (wcslen(lpParam) + 1) * sizeof(TCHAR), NULL))
	{
		cout &lt;&lt; &quot;写入内存失败&quot; &lt;&lt; endl;
		CloseHandle(hTarget);
		return 0;
	}
	HMODULE hNtdll = LoadLibrary(L&quot;kernel32.dll&quot;);
	if (!hNtdll)
	{
		cout &lt;&lt; &quot;加载模块错误&quot; &lt;&lt; GetLastError() &lt;&lt; endl;
		CloseHandle(hTarget);
		return 0;
	}
	cout &lt;&lt; &quot;模块句柄: &quot; &lt;&lt; hNtdll &lt;&lt; endl;
	void* pLoadLibrary = nullptr;
	pLoadLibrary = GetProcAddress(hNtdll, &quot;LoadLibraryW&quot;);
	if (pLoadLibrary == nullptr)
	{
		cout &lt;&lt; &quot;找不到函数&quot; &lt;&lt; endl;
		CloseHandle(hTarget);
		return 0;
	}
	cout &lt;&lt; &quot;函数地址: &quot; &lt;&lt; pLoadLibrary &lt;&lt; endl;
	DWORD dwThreadId = 0;
	HANDLE hRemoteThread = CreateRemoteThread(hTarget, NULL, 0, (LPTHREAD_START_ROUTINE)pLoadLibrary, (LPVOID)pLoadLibFuncParam, 0, &amp;dwThreadId);
	if (!hRemoteThread)
	{
		cout &lt;&lt; &quot;创建进程失败&quot; &lt;&lt; GetLastError() &lt;&lt; endl;
		CloseHandle(hTarget);
		return 0;
	}
	cout &lt;&lt; &quot;运行结束&quot; &lt;&lt; hRemoteThread &lt;&lt; endl;
	getchar();
	getchar();
	CloseHandle(hTarget);
	return 0;
}
