a_内功/设计模式/创建型模式.content:

                  创建型模式 



设计模式学习笔记——创建型模式篇。
📑 相关文章：结构型模式 · 行为型模式



[toc]

一、工厂模式

1.1 简单工厂模式

简单工厂模式由一个工厂类根据传入参数决定创建哪种产品实例，将对象的创建逻辑集中在一处。

类图

代码
C++cpp#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;

// 抽象水果类
class Fruit {
public:
    virtual void getName() = 0;
    virtual ~Fruit() {}
};

class Apple : public Fruit {
public:
    void getName() override {
        cout &lt;&lt; &quot;我是苹果&quot; &lt;&lt; endl;
    }
};

class Banana : public Fruit {
public:
    void getName() override {
        cout &lt;&lt; &quot;我是香蕉&quot; &lt;&lt; endl;
    }
};

// 简单工厂类
class FruitFactory {
public:
    Fruit* createFruit(const string&amp; type) {
        if (type == &quot;apple&quot;) return new Apple;
        if (type == &quot;banana&quot;) return new Banana;
        return nullptr;
    }
};

int main()
{
    FruitFactory* factory = new FruitFactory;

    Fruit* apple = factory-&gt;createFruit(&quot;apple&quot;);
    apple-&gt;getName();

    Fruit* banana = factory-&gt;createFruit(&quot;banana&quot;);
    banana-&gt;getName();

    delete apple;
    delete banana;
    delete factory;

    return 0;
}
优缺点
优点：

不需要记住具体类名，甚至连具体参数都不用记忆
实现了对象创建和使用的分离
系统可扩展性好，无需修改接口和原类

缺点：

增加系统中类的个数，复杂度和理解度增加
增加了系统的抽象性和理解难度
工厂类职责过重，新增产品需修改工厂代码（违反开闭原则）


1.2 工厂方法模式

工厂方法模式为每种产品提供对应的工厂子类，将简单工厂中的工厂类职责拆分，符合开闭原则。

类图

代码
C++cpp#include &lt;iostream&gt;
using namespace std;

// 抽象水果类
class Fruit {
public:
    virtual void getName() = 0;
    virtual ~Fruit() {}
};

class Apple : public Fruit {
public:
    void getName() override {
        cout &lt;&lt; &quot;我是苹果&quot; &lt;&lt; endl;
    }
};

class Banana : public Fruit {
public:
    void getName() override {
        cout &lt;&lt; &quot;我是香蕉&quot; &lt;&lt; endl;
    }
};

// 抽象工厂类
class AbstractFactory {
public:
    virtual Fruit* createFruit() = 0;
    virtual ~AbstractFactory() {}
};

// 苹果工厂：只生产苹果
class AppleFactory : public AbstractFactory {
public:
    Fruit* createFruit() override {
        return new Apple;
    }
};

// 香蕉工厂：只生产香蕉
class BananaFactory : public AbstractFactory {
public:
    Fruit* createFruit() override {
        return new Banana;
    }
};

int main()
{
    // 香蕉工厂 → 生产香蕉
    AbstractFactory* bananaFactory = new BananaFactory;
    Fruit* banana = bananaFactory-&gt;createFruit();
    banana-&gt;getName();

    delete bananaFactory;
    delete banana;

    // 苹果工厂 → 生产苹果
    AbstractFactory* appleFactory = new AppleFactory;
    Fruit* apple = appleFactory-&gt;createFruit();
    apple-&gt;getName();

    delete appleFactory;
    delete apple;

    return 0;
}

💡 简单工厂 → 工厂方法：将工厂类的 switch/if 判断拆分为多个工厂子类，每新增产品只需新增对应工厂类，无需修改已有代码。


二、抽象工厂模式

工厂方法模式通过引入工厂等级结构，解决了简单工厂模式中工厂类职责太重的问题。但 由于工厂方法模式中的每个工厂只生产一种产品，可能会导致系统中存在大量的工厂类，势必会增加系统的开销。此时，我们可以考虑将一些相关的产品组成一个”产品族”，由同一个工厂来统一生产，这就是抽象工厂模式的基本思想。

2.1 图例

2.2 代码
C++cpp#include &lt;iostream&gt;
using namespace std;

// ===== 抽象产品类 =====
class AbstractApple {
public:
    virtual void getName() = 0;
    virtual ~AbstractApple() {}
};
class AbstractBanana {
public:
    virtual void getName() = 0;
    virtual ~AbstractBanana() {}
};
class AbstractPear {
public:
    virtual void getName() = 0;
    virtual ~AbstractPear() {}
};

// ===== 具体产品：美国 =====
class USAApple : public AbstractApple {
public:
    void getName() override { cout &lt;&lt; &quot;美国苹果&quot; &lt;&lt; endl; }
};
class USABanana : public AbstractBanana {
public:
    void getName() override { cout &lt;&lt; &quot;美国香蕉&quot; &lt;&lt; endl; }
};
class USAPear : public AbstractPear {
public:
    void getName() override { cout &lt;&lt; &quot;美国鸭梨&quot; &lt;&lt; endl; }
};

// ===== 具体产品：中国 =====
class ChinaApple : public AbstractApple {
public:
    void getName() override { cout &lt;&lt; &quot;中国苹果&quot; &lt;&lt; endl; }
};
class ChinaBanana : public AbstractBanana {
public:
    void getName() override { cout &lt;&lt; &quot;中国香蕉&quot; &lt;&lt; endl; }
};
class ChinaPear : public AbstractPear {
public:
    void getName() override { cout &lt;&lt; &quot;中国鸭梨&quot; &lt;&lt; endl; }
};

// ===== 具体产品：日本 =====
class JapanApple : public AbstractApple {
public:
    void getName() override { cout &lt;&lt; &quot;日本苹果&quot; &lt;&lt; endl; }
};
class JapanBanana : public AbstractBanana {
public:
    void getName() override { cout &lt;&lt; &quot;日本香蕉&quot; &lt;&lt; endl; }
};
class JapanPear : public AbstractPear {
public:
    void getName() override { cout &lt;&lt; &quot;日本鸭梨&quot; &lt;&lt; endl; }
};

// ===== 抽象工厂类 =====
class AbstractFactory {
public:
    virtual AbstractApple* createApple() = 0;
    virtual AbstractBanana* createBanana() = 0;
    virtual AbstractPear* createPear() = 0;
    virtual ~AbstractFactory() {}
};

// ===== 具体工厂 =====
class USAFactory : public AbstractFactory {
public:
    AbstractApple* createApple() override { return new USAApple; }
    AbstractBanana* createBanana() override { return new USABanana; }
    AbstractPear* createPear() override { return new USAPear; }
};

class ChinaFactory : public AbstractFactory {
public:
    AbstractApple* createApple() override { return new ChinaApple; }
    AbstractBanana* createBanana() override { return new ChinaBanana; }
    AbstractPear* createPear() override { return new ChinaPear; }
};

class JapanFactory : public AbstractFactory {
public:
    AbstractApple* createApple() override { return new JapanApple; }
    AbstractBanana* createBanana() override { return new JapanBanana; }
    AbstractPear* createPear() override { return new JapanPear; }
};

int main()
{
    // 中国工厂 → 中国苹果、香蕉、鸭梨
    AbstractFactory* factory = new ChinaFactory;
    AbstractApple* AA = factory-&gt;createApple();
    AbstractBanana* AB = factory-&gt;createBanana();
    AbstractPear* AP = factory-&gt;createPear();

    AA-&gt;getName();
    AB-&gt;getName();
    AP-&gt;getName();

    delete AA;
    delete AB;
    delete AP;
    delete factory;

    return 0;
}

⚠️ 抽象工厂模式不符合”开闭原则”：新增产品等级结构需修改所有工厂类。

2.3 抽象工厂模式的优缺点
优点：

拥有工厂方法模式的优点
当一个产品族中的多个对象被设计成一起工作时，能够保证客户端始终只使用同一个产品族中的对象
增加新的产品族很方便，无需修改已有系统，符合”开闭原则”

缺点：

增加新的产品等级结构麻烦，需要对原有系统进行较大的修改，甚至需要修改抽象层代码，违背了”开闭原则”

2.4 三种工厂模式对比


简单工厂模式 + “开闭原则” = 工厂方法模式
工厂方法模式 + “产品族” = 抽象工厂模式

借鉴了《Easy搞定设计模式》

三、单例模式

保证一个类只有一个实例存在，同时提供能对该实例加以访问的全局访问方法。

3.1 三个要点

某个类只能有一个实例
它必须自行创建这个实例
它必须自行向整个系统提供这个实例

3.2 角色和职责
Singleton（单例）：在单例类的内部实现只生成一个实例，同时提供一个静态的 getInstance() 方法，让客户可以访问其唯一实例；为了防止在外部对其实例化，将其构造函数设计为私有；在单例类内部定义了一个 Singleton 类型的静态对象，作为外部共享的唯一实例。
3.3 单例模式的使用步骤

构造函数私有化 — 防止外部直接创建实例
提供全局静态方法 — 作为全局访问点获取单例对象
定义静态指针 — 指向本类的唯一实例

单例模式类图

3.4 饿汉模式

在程序启动时（类加载时）就创建实例，不管是否使用。

C++cpp#include &lt;iostream&gt;
using namespace std;

class Singleton {
public:
    static Singleton* getInstance() {
        return instance;
    }
private:
    Singleton() {}
    static Singleton* instance;
};

// 静态变量在类外初始化（程序启动即创建）
Singleton* Singleton::instance = new Singleton;

int main()
{
    Singleton* s1 = Singleton::getInstance();
    Singleton* s2 = Singleton::getInstance();

    if (s1 == s2)
        cout &lt;&lt; &quot;s1 == s2&quot; &lt;&lt; endl;
    else
        cout &lt;&lt; &quot;s1 != s2&quot; &lt;&lt; endl;

    return 0;
}

饿汉模式线程安全（初始化在 main 之前完成），但可能浪费资源（未使用也会创建）。

3.5 懒汉模式

在第一次使用时才创建实例，延迟加载。

C++cppclass Singleton1 {
public:
    static Singleton1* getInstance() {
        if (instance1 == nullptr) {
            instance1 = new Singleton1;
        }
        return instance1;
    }
private:
    Singleton1() {}
    static Singleton1* instance1;
};

// 懒汉式初始化：初始为空，首次调用时创建
Singleton1* Singleton1::instance1 = nullptr;

⚠️ 懒汉模式在多线程下需加锁保护，否则可能创建多个实例。

饿汉 vs 懒汉对比

3.6 单例模式的应用——打印机
用单例模式实现一个打印机程序，记录打印次数和内容。
C++cpp#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;

class Printer {
public:
    static Printer* getInstance() {
        return instance;
    }

    void print(const string&amp; text) {
        cout &lt;&lt; &quot;打印内容：&quot; &lt;&lt; text &lt;&lt; endl;
        sequence++;
        cout &lt;&lt; &quot;打印机今天使用了 &quot; &lt;&lt; sequence &lt;&lt; &quot; 次&quot; &lt;&lt; endl;
    }

private:
    // 嵌套 Garbo 类，用于程序结束时自动释放单例
    class Garbo {
    public:
        ~Garbo() {
            if (instance != nullptr) {
                delete instance;
                instance = nullptr;
            }
        }
    };

    Printer() {}
    static Printer* instance;
    static int sequence;
    static Garbo garbo;
};

int Printer::sequence = 0;
Printer* Printer::instance = new Printer;
Printer::Garbo Printer::garbo;

int main()
{
    Printer* p1 = Printer::getInstance();
    p1-&gt;print(&quot;一封简历&quot;);

    Printer* p2 = Printer::getInstance();
    p2-&gt;print(&quot;一份工作汇报&quot;);

    Printer* p3 = Printer::getInstance();
    p3-&gt;print(&quot;离职申请&quot;);

    // p1 == p2 == p3，始终是同一个实例
    return 0;
}
打印机类图


四、总结

以上就是几种常见的创建型设计模式。

a_内功/设计模式/结构型模式.content:
结构型模式

学习笔记C++设计模式——创建型模式
📑 创建型模式 |  📑 行为型模式

Proxy模式又叫做代理模式，是构造型的设计模式之一， 它可以为其他对象提供-种代理( Proxy )以控制对这个对象的访问。所谓代理，是指具有与代理元(被代理的对象)具有相同的接口的类，客户端必须通过代理与被代理的目标类交互，而代理一-般在交互的过程中 (交互前后) , 进行某些特别的处理。
代理模式

通俗理解就和海外代购类似，由一个海外代购专门负责所有需要从其他国家购买的这个行为。
以下为代理模式案例及其代码：
C++cpp// 代理模式.cpp : 定义控制台应用程序的入口点。
//
#include &quot;stdafx.h&quot;
#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;
class Item
{
public:
	Item(string kind, bool fact) 
	{
		this-&gt;kind = kind;
		this-&gt;fact = fact;
	}

	string getKind()
	{
		return kind;
	}

	bool getFact()
	{
		return fact;
	}
protected:
private:
	string kind;
	bool fact;
};

// 抽象的购物方式
class Shopping
{
public:
	virtual void buy(Item *it) = 0;
protected:
private:
};

class KoeraShopping : public Shopping
{
public:
	void buy(Item *it) {
		cout &lt;&lt; &quot;去韩国买了&quot; &lt;&lt; it-&gt;getKind() &lt;&lt; endl;
	}
protected:
private:
};

class USAShopping : public Shopping
{
public:
	void buy(Item * it) {
		cout &lt;&lt; &quot;去美国买了&quot; &lt;&lt; it-&gt;getKind() &lt;&lt; endl;
	}
protected:
private:
};


// 海外代理
class OverseasProxy : public Shopping
{
public:
	OverseasProxy(Shopping *shopping)
	{
		this-&gt;shopping = shopping;
	}
	virtual void buy(Item *it)
	{
		if (it-&gt;getFact() == true)
		{
			cout &lt;&lt; &quot;发现正品&quot; &lt;&lt; endl;
			shopping-&gt;buy(it);
			cout &lt;&lt; &quot;---------安检-----------&quot; &lt;&lt; endl;
		}
		else
		{
			cout &lt;&lt; &quot;发现假货&quot; &lt;&lt; it-&gt;getKind() &lt;&lt; endl;
		}
	}
protected:
private:
	Shopping *shopping; // 有一个购物方式
};


int main()
{
	Item it1(&quot;nike鞋子&quot;, true);
	Item it2(&quot;CET4证书&quot;, false);

	Shopping *Koerashopping = new KoeraShopping;
	Shopping *usaShopping = new USAShopping;

	Shopping *overseaProxy = new OverseasProxy(usaShopping);

	overseaProxy-&gt;buy(&amp;it1);
	overseaProxy-&gt;buy(&amp;it2);

    return 0;
}
代理模式的种类
远程代理（Remote Proxy）
为一个位于不同的地址空间的对象提供一个本地的代理对象，这个不同的地址空间可以是在同一台主机中，也可以是在另外一台主机中，远程代理又称为大使（Ambassador）。
远程代理： 使得客户端程序可以访问在远程主机上的对象，远程主机可能具有更好的计算性能与处理速度，可以快速相应并处理客户端的请求。远程代理可以将网络的细节隐藏起来，使得客户端不必考虑网络的存在。客户端完全可以认为被代理的远程业务对象是在本地而不是在远程，而远程代理对象承担了大部分的网络通信工作，并负责对远程业务方法的调用。


如图所示:
客户端对象不能直接访问远程主机中的业务对象，只能采取间接访问的方式。远程业务对象在本地主机中有一个代理对象，该代理对象负责对远程业务对象的访问和网络通信，它对于客户端对象而言是透明的。客户端无须关心实现具体业务的是谁，只需要按照服务接口所定义的方式直接与本地主机中的代理对象交互即可。

在基于[[【.Net】.Net逆向分析|.NET]]平台的分布式技术，例如DCOM（Distribute Component Object Mdoel， 分布式组件对象模型）、Web Service中，都应用了远程代理模式。
虚拟代理（Virtual Proxy）
如果需要创建一个资源消耗巨大的对象，先创建一个消耗相对较小的对象来表示，真实对象只在需要时才会被真正创建。虚拟代理(Virtual Proxy)也是一种常用的代理模式，对于一些占用系统资源较多或者加载时间较长的对象，可以给这些对象提供一个虚拟代理。在真实对象创建成功之前虚拟代理扮演真实对象的替身，而当真实对象创建之后，虚拟代理将用户的请求转发给真实对象。
通常，在以下两种情况下可以考虑使用虚拟代理：
(1) 由于对象本身的复杂性或者网络等原因导致一个对象需要较长的加载时间，此时可以用一个加载时间相对较短的代理对象来代表真实对象。通常在实现时可以结合多线程技术，一个线程用于显示代理对象，其他线程用于加载真实对象。这种虚拟代理模式可以应用在程序启动的时候，由于创建代理对象在时间和处理复杂度上要少于创建真实对象，因此，在程序启动时，可以用代理对象代替真实对象初始化，大大加速了系统的启动时间。当需要使用真实对象时，再通过代理对象来引用，而此时真实对象可能已经成功加载完毕，可以缩短用户的等待时间。
(2) 当一个对象的加载十分耗费系统资源的时候，也非常适合使用虚拟代理。虚拟代理可以让那些占用大量内存或处理起来非常复杂的对象推迟到使用它们的时候才创建，而在此之前用一个相对来说占用资源较少的代理对象来代表真实对象，再通过代理对象来引用真实对象。为了节省内存，在第一次引用真实对象时再创建对象，并且该对象可被多次重用，在以后每次访问时需要检测所需对象是否已经被创建，因此在访问该对象时需要进行存在性检测，这需要消耗一定的系统时间，但是可以节省内存空间，这是一种用时间换取空间的做法。
无论是以上哪种情况，虚拟代理都是用一个“虚假”的代理对象来代表真实对象，通过代理对象来间接引用真实对象，可以在一定程度上提高系统的性能。
保护代理（Protect Proxy）
控制对一个对象的访问，可以给不同的用户提供不同级别的使用权限
缓冲代理（Cache Proxy）
为某一个目标操作的结果提供临时的存储空间，以便多个客户端可以共享这些结果
缓冲代理(Cache Proxy)也是一种较为常用的代理模式，它为某一个操作的结果提供临时的缓存存储空间，以便在后续使用中能够共享这些结果，从而可以避免某些方法的重复执行，优化系统性能。
智能引用代理（Smart Reference Proxy）
当一个对象被引用时，提供一些额外的操作，例如将对象被调用的次数记录下来等。
装饰模式

装饰模式（decorator Pattern）: 动态地给一个对象增加一些额外的职责，就增加对象功能来说，装饰模式比生成子类实现更为灵活。装饰模式是一种对象结构型模式。


案例

代码
C++cpp// 装饰模式.cpp : 定义控制台应用程序的入口点。
#include &quot;stdafx.h&quot;
#include &lt;iostream&gt;
#include &lt;string&gt;
using namespace std;

// 一个抽象的构件，他是具体构件和抽象装饰类的父类 
class Phone
{
public:
	virtual void Show() = 0;
protected:
private:
};

// 具体的构件
class iPhone : public Phone
{
public:
	iPhone(string kind) {
		this-&gt;kind = kind;
	}

	virtual void Show() {
		cout &lt;&lt; &quot;秀出了 iPhone- &quot; &lt;&lt; kind &lt;&lt; &quot;:&quot; &lt;&lt; endl;
	}
protected:
private:
	string kind;
};

// 具体的构件
class Mi : public Phone
{
public:
	Mi(string kind) {
		this-&gt;kind = kind;
	}
	virtual void Show() {
		cout &lt;&lt; &quot;秀出了 Mi-&quot; &lt;&lt; kind &lt;&lt; &quot;:&quot; &lt;&lt; endl;
	}
protected:
private:
	string kind;
};

// 抽象的手机装饰类，必须包含抽象的构件
class DeCoratorPhone : public Phone
{
public:
	DeCoratorPhone() {

	}
	DeCoratorPhone(Phone *phone) {
		this-&gt;phone = phone;
	}
	virtual void Show()	{
		this-&gt;phone-&gt;Show();
	}
protected:
private:
	Phone *phone;
};

// 具体的装饰器
class DeCoratorPhoneMo : public DeCoratorPhone {

public:
	DeCoratorPhoneMo(Phone *phone) {
		this-&gt;phone = phone;
	}
	virtual void Show() {
		this-&gt;phone-&gt;Show();
		addMo();
	}
	void addMo() {
		cout &lt;&lt; &quot;装饰: 手机贴膜&quot; &lt;&lt; endl;
	}

private:
	Phone *phone;

};

// 具体的装饰器
class DeCoratorPhoneKe : public DeCoratorPhone {

public:
	DeCoratorPhoneKe(Phone *phone) {
		this-&gt;phone = phone;
	}
	virtual void Show() {
		this-&gt;phone-&gt;Show();
		addMo();
	}
	void addMo() {
		cout &lt;&lt; &quot;装饰: 手机装保护壳&quot; &lt;&lt; endl;
	}

private:
	Phone *phone;

};

int main()
{
	Phone *phone = NULL;
	DeCoratorPhone * hasMoPhone = NULL;
	DeCoratorPhone * hasKePhone = NULL;
	DeCoratorPhone * hasMoKePhone = NULL;

	// 定义一个Iphone 13手机
	phone = new iPhone(&quot;iPhone 13&quot;);
	// 给普通iphone 加上贴膜
	hasMoPhone = new DeCoratorPhoneMo(phone);
	// 给普通iphone 加上保护套
	hasKePhone = new DeCoratorPhoneKe(phone);
	hasMoPhone-&gt;Show();
	hasKePhone-&gt;Show();

	// 给有皮套的iphone 加上贴膜
	hasMoKePhone = new DeCoratorPhoneMo(hasKePhone);
	hasMoKePhone-&gt;Show();

	delete hasMoKePhone;
	delete hasKePhone;
	delete hasMoPhone;
	delete phone;
	cout &lt;&lt; &quot;---------------------------------------&quot; &lt;&lt; endl;

	phone = new Mi(&quot;Mix 4&quot;);
	hasMoPhone = new DeCoratorPhoneMo(phone);
	hasKePhone = new DeCoratorPhoneKe(phone);
	hasMoPhone-&gt;Show();
	hasKePhone-&gt;Show();

	hasMoKePhone = new DeCoratorPhoneKe(hasKePhone);
	hasMoKePhone-&gt;Show();

	delete hasMoKePhone;
	delete hasKePhone;
	delete hasMoPhone;
	delete phone;

    return 0;
}
输出：

秀出了 iPhone- iPhone 13:
装饰: 手机贴膜
秀出了 iPhone- iPhone 13:
装饰: 手机装保护壳
秀出了 iPhone- iPhone 13:
装饰: 手机装保护壳
装饰: 手机贴膜
秀出了 Mi-Mix 4:
装饰: 手机贴膜
秀出了 Mi-Mix 4:
装饰: 手机装保护壳
秀出了 Mi-Mix 4:
装饰: 手机装保护壳
装饰: 手机装保护壳
