KMP查找算法
Ccint KMPSearch(const void* src, size_t srcLen, const void* pat, size_t patLen)
{
    if (patLen == 0)
    {
        return 0;
    }

    if (srcLen &lt; patLen)
    {
        return -1;
    }

    auto GetNext = [](const void* pat, size_t patLen, int* next)
    {
        size_t i = 1;
        size_t j = 0;
        const char* ptr = (const char*)pat;

        next[0] = 0;

        while (i &lt; patLen)
        {
            if (ptr[j] == ptr[i])
            {
                next[i] = j + 1;
                i++;
                j++;
            }
            else if (j != 0)
            {
                j = next[j - 1];
            }
            else
            {
                i++;
            }
        }
    };

    std::unique_ptr&lt;int[]&gt; next(new(std::nothrow) int[patLen] {0});
    if (next == nullptr)
    {
        return -1;
    }
    GetNext(pat, patLen, next.get());

    size_t i = 0;
    size_t j = 0;
    const char* ptrSrc = (const char*)src;
    const char* ptrPat = (const char*)pat;
    while (i &lt; srcLen &amp;&amp; j &lt; patLen)
    {
        if (ptrSrc[i] == ptrPat[j])
        {
            i++;
            j++;
        }
        else if (j != 0)
        {
            j = next[j - 1];
        }
        else
        {
            i++;
        }
    }

    if (j == patLen)
    {
        return i - patLen;
    }

    return -1;
}
