Demo)

接口
在 Go 中，接口是一组方法签名。当一个类型为接口中的所有方法提供定义时，它被称为实现该接口。它与 oop 非常相似。接口指定类型应具有的方法，类型决定如何实现这些方法。
接口基础
之所以说 Go 语言的面向对象很灵活，很大一部分原因是由于接口的存在。接口是一个自定义类型，它声明了一个或者多个方法签名，任何实现了这些方法的类型都实现这个接口。infterface{} 类型是声明了空方法集的接口类型。任何一个值都满足 interface{} 类型，也就是说如果一个函数或者方法接收 interface{} 类型的参数，那么任意类型的参数都可以传递给该函数。接口是完全抽象的，不能实例化。接口能存储任何实现了该接口的类型。直接看例子吧，创建源文件 interface_t.go，输入以下代码：
gopackage main

import &quot;fmt&quot;

type Human struct { // 结构体
    name  string
    age   int
    phone string
}

//Human实现SayHi方法
func (h Human) SayHi() {
    fmt.Printf(&quot;Hi, I am %s you can call me on %s\n&quot;, h.name, h.phone)
}

//Human实现Sing方法
func (h Human) Sing(lyrics string) {
    fmt.Println(&quot;La la la la...&quot;, lyrics)
}

type Student struct {
    Human  //匿名字段
    school string
    loan   float32
}

type Employee struct {
    Human   //匿名字段
    company string
    money   float32
}

// Employee重载Human的SayHi方法
func (e Employee) SayHi() {
    fmt.Printf(&quot;Hi, I am %s, I work at %s. Call me on %s\n&quot;, e.name,
        e.company, e.phone)
}

// Interface Men被Human,Student和Employee实现
// 因为这三个类型都实现了这两个方法
type Men interface {
    SayHi()
    Sing(lyrics string)
}

func main() {
    mike := Student{Human{&quot;Mike&quot;, 25, &quot;222-222-XXX&quot;}, &quot;MIT&quot;, 0.00}
    paul := Student{Human{&quot;Paul&quot;, 26, &quot;111-222-XXX&quot;}, &quot;Harvard&quot;, 100}
    sam := Employee{Human{&quot;Sam&quot;, 36, &quot;444-222-XXX&quot;}, &quot;Golang Inc.&quot;, 1000}
    Tom := Employee{Human{&quot;Tom&quot;, 37, &quot;222-444-XXX&quot;}, &quot;Things Ltd.&quot;, 5000}

    //定义Men类型的变量i
    var i Men

    //i能存储Student
    i = mike
    fmt.Println(&quot;This is Mike, a Student:&quot;)
    i.SayHi()
    i.Sing(&quot;November rain&quot;)

    //i也能存储Employee
    i = Tom
    fmt.Println(&quot;This is Tom, an Employee:&quot;)
    i.SayHi()
    i.Sing(&quot;Born to be wild&quot;)

    //定义了slice Men
    fmt.Println(&quot;Let&#039;s use a slice of Men and see what happens&quot;)
    x := make([]Men, 3)
    //这三个都是不同类型的元素，但是他们实现了interface同一个接口
    x[0], x[1], x[2] = paul, sam, mike

    for _, value := range x {
        value.SayHi()
    }
}
接口变量值的类型*

接口类型声明的变量里能存储任何实现了该接口的类型的值。
有的时候我们需要知道这个变量里的值的类型，那么需要怎么做呢？可以使用类型断言，或者是 switch 类型判断分支。以下的例子 interface_t1.go 我们使用了 switch 类型判断分支。

go/*使用了switch 类型判断分支*/

package main

import (
	&quot;fmt&quot;
	&quot;strconv&quot;
)

type Element interface{}
type List []Element

type Person struct {
	name string
	age  int
}

// 实现了fmt.Stringer接口
func (p Person) String() string {
	return &quot;(name: &quot; + p.name + &quot;- age: &quot; + strconv.Itoa(p.age) + &quot; years)&quot;
}

func main() {
	list := make(List, 4)
	list[0] = 1
	list[1] = &quot;Hello&quot;
	list[2] = Person{&quot;Dennis&quot;, 70}
	list[3] = 1 + 2i

	for Index, element := range list {
		switch value := element.(type) {
		case int:
			fmt.Printf(&quot;list[%d] is an int and its value is %d\n&quot;, index, value)
		case string:
			fmt.Printf(&quot;list[%d] is an int and its value is %s\n&quot;, index, value)
		case Person:
			fmt.Printf(&quot;list[%d] is an int and its value is %s\n&quot;, index, value)
		default:
			fmt.Printf(&quot;list[%d] is of a different type&quot;, index)
		}
	}
}
