2352. 相等行列对 - 力扣（LeetCode）
给你一个下标从 0 开始、大小为 n x n 的整数矩阵 grid ，返回满足 Ri 行和 Cj 列相等的行列对 (Ri, Cj) 的数目。
如果行和列以相同的顺序包含相同的元素（即相等的数组），则认为二者是相等的。
 
示例 1：
![img](2352. 相等行列对/2166070-20230606232015247-2005756878.png)
输入：grid = [[3,2,1],[1,7,6],[2,7,7]]
输出：1
解释：存在一对相等行列对：

(第 2 行，第 1 列)：[2,7,7]

示例 2：
![img](2352. 相等行列对/2166070-20230606232037353-1792537934.png)
输入：grid = [[3,1,2,2],[1,4,4,5],[2,4,2,2],[2,4,2,2]]
输出：3
解释：存在三对相等行列对：

(第 0 行，第 0 列)：[3,1,2,2]
(第 2 行, 第 2 列)：[2,4,2,2]
(第 3 行, 第 2 列)：[2,4,2,2]

提示：
n  grid.length  grid[i].length
1 &lt;= n &lt;= 200
1 &lt;= grid[i][j] &lt;= 105
来源：力扣（LeetCode）
链接：leetcode.cn/problems/equal-row-and-column-pairs
著作权归领扣网络所有。商业转载请联系官方授权，非商业转载请注明出处。
Solution
cpp
C++cppclass Solution {
public:
    int equalPairs(vector&lt;vector&lt;int&gt;&gt;&amp; grid) {
        int res = 0, n = grid.size();
        for (int row = 0; row &lt; n; row++)
        {
            for (int col = 0; col &lt; n; col++)
            {
                if(equal(row, col, grid))
                {
                    res++;
                }
            }
        }
        return res;
    }

    bool equal(int row, int col, vector&lt;vector&lt;int&gt;&gt; &amp;grid)
    {
        int n = grid.size();
        for (int i = 0; i &lt; n; i++)
        {
            if(grid[row][i] != grid[i][col])
            {
                return false;
            }
        }
        return true;
    }
};
Go
gofunc equalPairs(grid [][]int) int {
    n := len(grid)
    cnt := make(map[string]int)

    for _,row := range grid {
        cnt[fmt.Sprint(row)]++
    }

    res := 0

    for j := 0; j &lt; n; j++ {
        var arr[] int
        for i := 0; i &lt; n; i++ {
            arr = append(arr, grid[i][j])
        }

        if val,ok := cnt[fmt.Sprint(arr)]; ok {
            res += val
        }
    }

    return res
}

