补充一下
load()的函数有必要读一下。
QPixmap::loadFromData() 的源码。
C++cpp/*!
    \fn bool QPixmap::loadFromData(const uchar *data, uint len, const char *format, Qt::ImageConversionFlags flags)

    Loads a pixmap from the \a len first bytes of the given binary \a
    data.  Returns \c true if the pixmap was loaded successfully;
    otherwise invalidates the pixmap and returns \c false.

    The loader attempts to read the pixmap using the specified \a
    format. If the \a format is not specified (which is the default),
    the loader probes the file for a header to guess the file format.

    If the data needs to be modified to fit in a lower-resolution
    result (e.g. converting from 32-bit to 8-bit), use the \a flags to
    control the conversion.

    \sa load(), {QPixmap#Reading and Writing Image Files}{Reading and
    Writing Image Files}
*/

bool QPixmap::loadFromData(const uchar *buf, uint len, const char *format, Qt::ImageConversionFlags flags)
{
    if (len == 0 || buf == 0) {
        data.reset();
        return false;
    }

    data = QPlatformPixmap::create(0, 0, QPlatformPixmap::PixmapType);

    if (data-&gt;fromData(buf, len, format, flags))
        return true;

    data.reset();
    return false;
}

b_code/qt/中英文切换.content:
概述：支持国际化是软件发布的基本项。Qt 提供了完整的国际化解决方案。


0x01、Qt 国际化概述
Qt 安装时，带了一个 Qt Linguist 的软件，这是 Qt 用来实现软件翻译的工具。Qt 内置的字体引擎可以在同一时间正确绘制包含不同书写系统字符的文本。
国际化流程
text源码中使用 tr() → 修改 .pro 文件 → 生成 .ts 文件 → 使用 Linguist 翻译 → 发布 .qm 文件 → 运行时加载
0x02、使用 tr() 函数
基本用法
C++cpp// 所有需要翻译的字符串都用 tr() 包裹
label-&gt;setText(tr(&quot;Hello World&quot;));
button-&gt;setText(tr(&quot;Save&quot;));

// 带上下文
tr(&quot;File&quot;, &quot;菜单项&quot;);  // &quot;菜单项&quot; 是上下文，帮助翻译者理解
格式化字符串
C++cpp// 使用 %1, %2 等占位符
QString msg = tr(&quot;Processing %1 of %2 files&quot;).arg(current).arg(total);

// 复数形式
QString msg = tr(&quot;%n file(s) found&quot;, nullptr, count);
不需要翻译的字符串
C++cpp// 使用 QStringLiteral 或 QLatin1String
const char* version = &quot;1.0.0&quot;;  // 不需要翻译
QString url = QStringLiteral(&quot;example.com&quot;);  // 不需要翻译
0x03、修改 .pro 文件
qmake# 添加翻译文件
TRANSLATIONS += \
    translations/myapp_zh_CN.ts \
    translations/myapp_en_US.ts \
    translations/myapp_ja_JP.ts

# 指定编码
CODECFORSRC = UTF-8
0x04、生成和更新翻译文件
使用命令行
bash# 生成/更新 .ts 文件
lupdate myapp.pro

# 指定输出目录
lupdate src -ts translations/myapp_zh_CN.ts

# 发布 .qm 文件
lrelease translations/myapp_zh_CN.ts
使用 Qt Creator

菜单：工具 → 外部 → Qt语言家 → 更新翻译 (lupdate)
翻译完成后：工具 → 外部 → Qt语言家 → 发布翻译 (lrelease)

0x05、使用 Qt Linguist

打开 .ts 文件
选择需要翻译的字符串
输入翻译内容
标记为”已完成”
保存并发布

0x06、运行时切换语言
加载翻译文件
C++cpp#include &lt;QTranslator&gt;
#include &lt;QLocale&gt;

class LanguageManager : public QObject
{
    Q_OBJECT
public:
    static LanguageManager* instance()
    {
        static LanguageManager manager;
        return &amp;manager;
    }

    bool loadLanguage(const QString &amp;language)
    {
        // 移除旧翻译器
        if (m_translator) {
            qApp-&gt;removeTranslator(m_translator);
            delete m_translator;
        }

        m_translator = new QTranslator();

        QString translationFile = QString(&quot;:/translations/myapp_%1.qm&quot;)
                                    .arg(language);

        if (m_translator-&gt;load(translationFile)) {
            qApp-&gt;installTranslator(m_translator);
            m_currentLanguage = language;
            emit languageChanged();
            return true;
        }

        delete m_translator;
        m_translator = nullptr;
        return false;
    }

    QString currentLanguage() const { return m_currentLanguage; }

signals:
    void languageChanged();

private:
    LanguageManager() : m_translator(nullptr) {}
    QTranslator *m_translator;
    QString m_currentLanguage;
};
动态切换语言
C++cpp// 切换语言
void MainWindow::switchLanguage(const QString &amp;language)
{
    if (LanguageManager::instance()-&gt;loadLanguage(language)) {
        // 刷新界面
        retranslateUi();
    }
}

// 刷新界面文本
void MainWindow::retranslateUi()
{
    m_label-&gt;setText(tr(&quot;Hello World&quot;));
    m_button-&gt;setText(tr(&quot;Save&quot;));
    // ... 刷新所有需要翻译的控件
}

// 重写 changeEvent
void MainWindow::changeEvent(QEvent *event)
{
    if (event-&gt;type() == QEvent::LanguageChange) {
        retranslateUi();
    }
    QMainWindow::changeEvent(event);
}
0x07、完整示例
C++cpp// main.cpp
#include &lt;QApplication&gt;
#include &lt;QTranslator&gt;
#include &lt;QLocale&gt;

int main(int argc, char *argv[])
{
    QApplication a(argc, argv);

    // 自动加载系统语言
    QTranslator translator;
    QString locale = QLocale::system().name();  // 如 &quot;zh_CN&quot;
    if (translator.load(QString(&quot;:/translations/myapp_%1.qm&quot;).arg(locale))) {
        a.installTranslator(&amp;translator);
    }

    MainWindow w;
    w.show();

    return a.exec();
}

// mainwindow.cpp
#include &quot;mainwindow.h&quot;
#include &lt;QMenu&gt;
#include &lt;QAction&gt;

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
{
    createMenus();
    retranslateUi();
}

void MainWindow::createMenus()
{
    m_fileMenu = menuBar()-&gt;addMenu(&quot;&quot;);

    m_newAction = new QAction(this);
    m_openAction = new QAction(this);
    m_saveAction = new QAction(this);
    m_exitAction = new QAction(this);

    m_fileMenu-&gt;addAction(m_newAction);
    m_fileMenu-&gt;addAction(m_openAction);
    m_fileMenu-&gt;addAction(m_saveAction);
    m_fileMenu-&gt;addSeparator();
    m_fileMenu-&gt;addAction(m_exitAction);

    // 连接信号槽
    connect(m_exitAction, &amp;QAction::triggered, this, &amp;MainWindow::close);
}

void MainWindow::retranslateUi()
{
    m_fileMenu-&gt;setTitle(tr(&quot;&amp;File&quot;));
    m_newAction-&gt;setText(tr(&quot;&amp;New&quot;));
    m_openAction-&gt;setText(tr(&quot;&amp;Open&quot;));
    m_saveAction-&gt;setText(tr(&quot;&amp;Save&quot;));
    m_exitAction-&gt;setText(tr(&quot;E&amp;xit&quot;));
}

void MainWindow::changeEvent(QEvent *event)
{
    if (event-&gt;type() == QEvent::LanguageChange) {
        retranslateUi();
    }
    QMainWindow::changeEvent(event);
}

// 切换语言
void MainWindow::onLanguageChanged(const QString &amp;language)
{
    LanguageManager::instance()-&gt;loadLanguage(language);
}
0x08、常见问题
翻译不生效

检查 .qm 文件路径是否正确
确保 installTranslator() 在界面创建之前调用
检查字符串是否使用 tr() 包裹

动态切换后界面不更新

重写 changeEvent 处理 LanguageChange 事件
手动调用 retranslateUi() 刷新界面

中文乱码

确保源文件编码为 UTF-8
在 .pro 中添加 CODECFORSRC = UTF-8
使用 QString::fromUtf8() 处理非 tr 包裹的中文字符串


