    void myMove(int x, int y);

    void setWidgetIndex(int i);

protected:
    void paintEvent(QPaintEvent *);

private:
    // 小三角的偏移量;
    int m_offset;
    // 小三角的宽度;
    int m_triangleWidth;
    // 小三角高度;
    int m_triangleHeight;
