        function acSetCookie(cname, cvalue, domain, exdays) {
          try {
            exdays = exdays || 30
            let d = new Date()
            domain = (domain ? &#039;domain=&#039; + domain : &#039;&#039;) + &#039;;&#039;
            d.setTime(d.getTime() + exdays * 24 * 60 * 60 * 1000)
            let expires = &#039;expires=&#039; + d.toUTCString()
            document.cookie =
              cname +
              &#039;=&#039; +
              cvalue +
              &#039;; &#039; +
              domain +
              expires +
              &#039;;path=/;SameSite=None;Secure&#039;
          } catch (e) {}
        }

