            &quot;font-style:normal;position:relative;z-index:1;margin-right:4px;display:inline-block;color:white;font-family:&#039;微软雅黑&#039;;font-size:16px;text-align:center;width:22px;line-height:22px;border-radius:50%;&quot;
          for (let i = 0; i &lt; citeList.length; i++) {
