              let ele = document.createElement(&#039;em&#039;)
              ele.className = &#039;AC-CounterT&#039;
              ele.style = cssText
              ele.innerText = CONST.sortIndex
              let child = cur.firstElementChild
              if (child &amp;&amp; child.nodeName == &#039;DIV&#039;) {
