      function safeRemove_xpath(
        xpathSelector,
        option = {
          isHide: false, // 隐藏模式
          withAni: true // 带动画效果
        }
      ) {
        const { isHide = false, withAni = false } = option
        safeFunction(() =&gt; {
          let removeNodes = getAllElements(xpathSelector)
          if (isHide) {
            for (let i = 0; i &lt; removeNodes.length; i++) {
              hideNode(removeNodes[i])
            }
          } else {
            for (let i = 0; i &lt; removeNodes.length; i++) {
              removeNodes[i].remove() // 避免卡顿现象
            }
          }
        })
      }

