       * @returns {boolean} T|F
       */
      function checkDocmentHasNode(nodeClass) {
        for (let i = 0; i &lt; document.childNodes.length; i++) {
          if (
            document.childNodes[i].data &amp;&amp;
            document.childNodes[i].data.indexOf(nodeClass) &gt; 0
