      function FSBaidu() {
        // thanks for code from 浮生@未歇 @page greasyfork.org/zh-TW/scripts/31642
        // debug(&quot;初始化FSBAIDU&quot;);

        const StyleManger = {
          /**
           * 导入css内容为【文本格式】！！！
           * @param data css内容
           * @param toClassName 预期的类名
           */
          importStyle: async (
            data,
            toClassName,
            useNormalCSS = false,
            mustLoad = false
          ) =&gt; {
            if (typeof data === &#039;undefined&#039; || data === null) {
              // 这个居然在VM上出问题了，很奇怪
              console.error(&#039;GM_getResourceText获取内容数据异常：&#039;, toClassName)
