            }
            if (data.startsWith(&#039;http&#039;)) {
              // 网址开头的，那么尝试去加载数据去
              data = await asyncGMHttpRequestGet(data)
            }
            // 普通浏览器模式--但是似乎样式加载的优先级低于head中的style优先级
            if (!useNormalCSS) {
              /* **********多重样式-兼容edge &amp;&amp; 黑夜脚本************ */
