              // AC_addStyle(data, toClassName, &quot;head&quot;, false, &quot;less&quot;);
              /* **********多重样式-兼容edge &amp;&amp; 黑夜脚本************ */
            }
          },
          loadStyle: async function (
            styleName,
            insClassName,
            setUrl,
            useNormalCSS = false,
            mustLoad = false
          ) {
            // 全部采用text/css的内容来载入
            // 如果是debug模式。或者是gm模式
            if (isLocalDebug) {
              debug(&#039;本地-加载样式：&#039; + insClassName)
              setUrl =
                setUrl ||
                &#039;debug.baidu.com/&#039; +
                  styleName +
                  &#039;.less?t=&#039; +
                  Math.random() * new Date().getTime()
              return await this.importStyle(
                setUrl,
                &#039;AC-&#039; + insClassName,
                useNormalCSS,
                mustLoad
              )
            } else {
              debug(&#039;加载样式：&#039; + insClassName)
              // TamperMonkey + GreaseMonkey &lt; 4.0 + ViolentMonkey (4.0GreaseMonkey不支持GetResource方法)
              const style =
                curSite.GMStyleList[styleName] ||
                (await GM_getResourceText(styleName))
              return await this.importStyle(
                style,
                &#039;AC-&#039; + insClassName,
                useNormalCSS,
                mustLoad
              )
            }
          },
          //加载护眼模式样式
          loadHuYanStyle: async function (color) {
            if (ACConfig.isUserColorEnable) {
              color = color || ACConfig.defaultHuYanColor || &#039;#FFFFFF&#039;
            } else {
              color = color || &#039;#FFFFFF&#039;
            }
            if (color.indexOf(&#039;#&#039;) !== 0 || color.length &lt; 7) return
            const style = GM_getResourceText(&#039;MainHuYanStyle&#039;)
              .replace(/#aaa(a*)/gim, color)
              .replace(/#bbb(b*)/gim, this.Lighter(color, -40))
              .replace(/#ccc(c*)/gim, this.Lighter(color, 45))
            CONST.flushNode.insert(
              await create_CSS_Node(
                style,
                &#039;AC-&#039; + CONST.useItem.name + &#039;HuYanStyle-File&#039;,
                &#039;less&#039;
              ),
              &#039;head&#039;,
              {
                isReload: true
              }
            )
          },
          clip255: function (value) {
            if (value &gt; 255) return 255
            if (value &lt; 0) return 0
            return value
          },
          Lighter: function (oriRGB, deltaY) {
            // 按比例缩放 + 1/deltaY
            // HEX 2 RGB
            let rgb = oriRGB.replace(&#039;#&#039;, &#039;&#039;)
            let R = parseInt(&#039;0x&#039; + rgb.substr(0, 2))
            let G = parseInt(&#039;0x&#039; + rgb.substr(2, 2))
            let B = parseInt(&#039;0x&#039; + rgb.substr(4, 2))
            // RGB 2 YUV
            let Y = ((66 * R + 129 * G + 25 * B + 128) &gt;&gt; 8) + 16
            let U = ((-38 * R - 74 * G + 112 * B + 128) &gt;&gt; 8) + 128
            let V = ((112 * R - 94 * G - 18 * B + 128) &gt;&gt; 8) + 128
            Y = Y * (1 + 1.0 / deltaY) // 提高亮度
            // YUV 2 RGB
            R = this.clip255((298 * (Y - 16) + 409 * (V - 128) + 128) &gt;&gt; 8)
            G = this.clip255(
              (298 * (Y - 16) - 100 * (U - 128) - 208 * (V - 128) + 128) &gt;&gt; 8
            )
            B = this.clip255((298 * (Y - 16) + 516 * (U - 128) + 128) &gt;&gt; 8)
            return &#039;#&#039; + ((R &lt;&lt; 16) + (G &lt;&lt; 8) + B).toString(16)
          },
          loadBaiduLiteStyle: async function () {
            const node = await this.loadStyle(
              &#039;baiduLiteStyle&#039;,
              &#039;baiduLiteStyle&#039;
            )
            this.flushDom.insert(node, &#039;DOM&#039;)
          },
          loadBgImage: async function () {
            if (
              CONST.useItem.defaultBgUrl &amp;&amp;
              CONST.useItem.defaultBgUrl.trim()
            ) {
              changeSiteBackground(CONST.useItem.defaultBgUrl)
            }
          },
          loadBgAutoFit: async function () {
            const node = await this.loadStyle(&#039;BgAutoFit&#039;, &#039;BgAutoFit&#039;)
            this.flushDom.insert(node, &#039;DOM&#039;)
          },
          //加载普通样式
          loadCommonStyle: async function () {
            const node = await this.loadStyle(
              CONST.useItem.name + &#039;CommonStyle&#039;,
              CONST.useItem.name + &#039;CommonStyle&#039;
            )
            this.flushDom.insert(node, &#039;DOM&#039;)
          },
          //加载单页样式
          loadOnePageStyle: async function () {
            const node2 = await create_CSS_Node(
              &#039;#main #cnt, #cnt #center_col, #cnt #foot{\n&#039; +
                &#039;    transition: all 0.1s ease-in-out;\n&#039; +
                &#039;    animation-duration: 0s !important;\n&#039; +
                &#039;}\n&#039; +
                &#039;div[two-father]{\n&#039; +
                &#039;    animation-duration: 0s !important;\n&#039; +
                &#039;}&#039;,
              &#039;AC-PageNoAni&#039;
            )
            this.flushDom.insert(node2, &#039;head&#039;)

            const node = await this.loadStyle(
              CONST.useItem.name + &#039;OnePageStyle&#039;,
              CONST.useItem.name + &#039;OnePageStyle&#039;
            )
            this.flushDom.insert(node, &#039;DOM&#039;)
          },
          //加载双页样式
          loadTwoPageStyle: async function () {
            const node = await this.loadStyle(
              CONST.useItem.name + &#039;TwoPageStyle&#039;,
              CONST.useItem.name + &#039;TwoPageStyle&#039;
            )
            this.flushDom.insert(node, &#039;DOM&#039;)
            let cssHead = &#039;&#039;
            if (
              curSite.SiteTypeID === SiteType.BAIDU ||
              curSite.SiteTypeID === SiteType.MBAIDU
            )
              cssHead =
                &#039;#container #content_left, body[news] #container #content_left&gt;div:not([class]):not([id])&#039;
            if (curSite.SiteTypeID === SiteType.GOOGLE)
              cssHead =
                &#039;.srg, #rso, div[two-father], #rso&gt;div:not(.g), #kp-wp-tab-overview&#039;
            if (curSite.SiteTypeID === SiteType.BING)
              cssHead = &#039;#b_content #b_results&#039;
            if (curSite.SiteTypeID === SiteType.SOGOU)
              cssHead = &#039;#main .results&#039;
            if (curSite.SiteTypeID === SiteType.DUCK)
              cssHead = &#039;#react-layout .react-results--main&#039;
            if (curSite.SiteTypeID === SiteType.DOGE)
              cssHead = &#039;#links_wrapper .results--main #links&#039;
            const node2 = await create_CSS_Node(
              cssHead +
                &quot;{grid-template-columns: repeat(2, minmax(50%,1fr));grid-template-areas:&#039;xmain xmain&#039;;}.AC.sp-separator{grid-column-start: 1;grid-column-end: xmain-end;}&quot;,
              &#039;AC-TwoPageExStyle&#039;
            )
            this.flushDom.insert(node2, &#039;head&#039;)
          },
          // 加载三列样式
          loadThreePageStyle: async function () {
            let cssHead = &#039;&#039;
            if (
              curSite.SiteTypeID === SiteType.BAIDU ||
              curSite.SiteTypeID === SiteType.MBAIDU
            )
              cssHead =
                &#039;#container #content_left, body[news] #container #content_left&gt;div:not([class]):not([id])&#039;
            if (curSite.SiteTypeID === SiteType.GOOGLE)
              cssHead =
                &#039;.srg, #rso, div[two-father], #rso&gt;div:not(.g), #kp-wp-tab-overview&#039;
            if (curSite.SiteTypeID === SiteType.BING)
              cssHead = &#039;#b_content #b_results&#039;
            if (curSite.SiteTypeID === SiteType.SOGOU)
              cssHead = &#039;#main .results&#039;
            if (curSite.SiteTypeID === SiteType.DUCK)
              cssHead = &#039;#react-layout .react-results--main&#039;
            if (curSite.SiteTypeID === SiteType.DOGE)
              cssHead = &#039;#links_wrapper .results--main #links&#039;
            const node2 = await create_CSS_Node(
              cssHead +
                &quot;{grid-template-columns: repeat(3, minmax(33.3%,1fr));grid-template-areas:&#039;xmain xmain xmain&#039;;}&quot;,
              &#039;AC-ThreePageExStyle&#039;
            )
            this.flushDom.insert(node2, &#039;head&#039;)
          },
          // 加载四列样式
          loadFourPageStyle: async function () {
            let cssHead = &#039;&#039;
            if (
              curSite.SiteTypeID === SiteType.BAIDU ||
              curSite.SiteTypeID === SiteType.MBAIDU
            )
              cssHead =
                &#039;#container #content_left, body[news] #container #content_left&gt;div:not([class]):not([id])&#039;
            if (curSite.SiteTypeID === SiteType.GOOGLE)
              cssHead =
                &#039;.srg, #rso, div[two-father], #rso&gt;div:not(.g), #kp-wp-tab-overview&#039;
            if (curSite.SiteTypeID === SiteType.BING)
              cssHead = &#039;#b_content #b_results&#039;
            if (curSite.SiteTypeID === SiteType.SOGOU)
              cssHead = &#039;#main .results&#039;
            if (curSite.SiteTypeID === SiteType.DOGE)
              cssHead = &#039;#react-layout .react-results--main&#039;
            if (curSite.SiteTypeID === SiteType.DOGE)
              cssHead = &#039;#links_wrapper .results--main #links&#039;
            const node2 = await create_CSS_Node(
              cssHead +
                &quot;{grid-template-columns: repeat(4, minmax(25%,1fr));grid-template-areas:&#039;xmain xmain xmain xmain&#039;;}&quot;,
              &#039;AC-FourPageExStyle&#039;
            )
            this.flushDom.insert(node2, &#039;head&#039;)
          },
          findPossibleTwoLines() {
            // 通过.g来往上查找
            // 如果其拥有的子节点的className具有两个以上的相同项，那么认为是grid布局，需要遍历，增加标记位
            function checkOne(element) {
              const res = {
                exist: false,
                skipFind: false
              }

              if (element.children.length &lt;= 2) return res

              // 如果已经有这个参数了，或者当前节点是右侧栏，那么跳过
              if (
                element.hasAttribute(&#039;two-checked&#039;) ||
                element.id.includes(&#039;rhs&#039;)
              ) {
                res.skipFind = true
                return res
              }

              element.setAttribute(&#039;two-checked&#039;, &#039;true&#039;)
              const childNodeClassNameList = [...element.children]
                .map((one) =&gt; one.className)
                .filter((one) =&gt; one &amp;&amp; one !== &#039;&#039;)
              const childNodeClassNameSet = new Set(childNodeClassNameList)
              const tf =
                childNodeClassNameSet.size !== childNodeClassNameList.length
              if (tf) {
                // debugger
                res.exist = true
              }
              return res
            }

            const gList = document.querySelectorAll(&#039;.g&#039;)
            const possibleList = []
            for (const perG of gList) {
              let curIndex = 10 // 最多查10层
              let curNode = perG.parentNode

              while (curIndex-- &gt; 0) {
                const { exist = false, skipFind = false } = checkOne(curNode)
                if (skipFind) {
                  break
                }
                if (exist) {
                  possibleList.push(curNode)
                  break
                }
                curNode = curNode.parentNode
              }
            }
            // console.log(possibleList)
            return possibleList
          },
          googleFatherChildTag: async function () {
            if (curSite.SiteTypeID === SiteType.GOOGLE) {
              let nodeList = this.findPossibleTwoLines()
              // console.log(nodeList)

              // 对于这些块，都判定一下结构，如果子节点中div数量不足2个的，那么丢弃grid布局
              if (nodeList.length &gt; 0) {
                nodeList.forEach((node) =&gt; {
                  const divChildren = [...node.children].filter(
                    (one) =&gt; one.tagName.toUpperCase() === &#039;DIV&#039;
                  )
                  const script_styleChildren = [...node.children].filter(
                    (one) =&gt; /(SCRIPT|STYLE)/.test(one.tagName.toUpperCase())
                  )
                  if (
                    divChildren.length &gt;= 2 &amp;&amp;
                    script_styleChildren.length &lt; 3
                  ) {
                    node.setAttribute(&#039;two-father&#039;, 1)
                    divChildren.forEach((one) =&gt; {
                      // 不显示那些应该隐藏的元素
                      if (one.innerText.length &gt; 0 || one.children.length &gt; 0) {
                        one.setAttribute(&#039;two-child&#039;, 1)
                      } else {
                        one.style = &#039;display:none&#039;
                      }
                    })
                  } else {
                    node.removeAttribute(&#039;two-father&#039;)
                  }

                  // 两列的时候，增加对应的grid布局
                  if (CONST.useItem.AdsStyleMode &gt;= 3) {
                    if (divChildren.length &gt;= 2) {
                      node.style.display !== &#039;grid&#039;
                        ? (node.style.display = &#039;grid&#039;)
                        : &#039;&#039;
                    } else {
                      node.style.display !== &#039;unset&#039;
                        ? (node.style.display = &#039;unset&#039;)
                        : &#039;&#039;
                    }
                  }
                })
              }
              // 特殊元素一行处理
              document
                .querySelectorAll(&#039;#rso&gt;div:not(.g)&gt;div[jsmodel]&#039;)
                .forEach((one) =&gt; {
                  one.parentNode.style.display = &#039;unset&#039;
                })
            }
          },
          loadPlainToCSS: function () {
            for (let i = 0; i &lt; document.childNodes.length; i++) {
              let curNode = document.childNodes[i]
              if (curNode.del) curNode.remove()
            }
            safeRemove(&quot;style[class*=&#039;AC&#039;][del=&#039;1&#039;]&quot;)
          },
          // 禁止独立的样式加载
          loadCSSToPlain: function () {
            for (let i = 0; i &lt; document.childNodes.length; i++) {
              let curNode = document.childNodes[i]
              // 如果是存在css， 且非必须数据
              if (
                curNode.target === &#039;xml-stylesheet&#039; &amp;&amp;
                curNode.data.indexOf(&#039;must=&quot;true&#039;) &lt; 0
              ) {
                curNode.data = &#039;&#039;
                curNode.del = true

                // 对于edge和safari都特殊处理一下吧
                if (
                  navigator.userAgent.toLowerCase().indexOf(&#039;edge&#039;) &gt; 0 ||
                  navigator.userAgent.toLowerCase().indexOf(&#039;safari&#039;) &gt; 0
                ) {
                  curNode.remove()
                }
              }
            }
          }
        }
        const ControlManager = {
          ...StyleManger,
          //居中显示 --- 必须是百度和谷歌的搜索结果页面，其他页面不能加载的--已经通过脚本include标签限制了一部分
          centerDisplay: async function () {
            // flush完成之后，等一等变更，渲染差不多之后再刷新
            this.googleFatherChildTag() // 先初始化，减少抖动问题
            setSlowInterval(() =&gt; {
              this.googleFatherChildTag()
            }, 600)
            // 如果是百度 &amp;&amp; ((地址替换-&gt;包含wd关键词[替换之后不等-是百度结果页面]) || 有右边栏-肯定是百度搜索结果页 || value中存在搜索内容) return;
            if (!checkISBaiduMain()) {
              console.log(&#039;not good At Baidu&#039;)
              this.loadCSSToPlain()
              return
            }
            this.flushDom.insert(
              await create_CSS_Node(
                &#039;.minidiv #logo img{width: 100px;height: unset;margin-top: 0.3rem;} body.purecss-mode:before{display: none;}&#039;,
                &#039;AC-style-logo&#039;
              )
            )
            let result = parseInt(CONST.useItem.AdsStyleMode || -1)
            if (
              acCssLoadFlag === false &amp;&amp;
              document.querySelector(&#039;.ACExtension&#039;) === null
            ) {
              debug(&#039;in样式即将加载:&#039; + result)
              let expandStyle =
                &#039;#wrapper #rs, #wrapper #content_left .result, #wrapper #content_left &gt; .c-container{min-width:670px;}.c-span18{width:78%!important;min-width:550px;}.c-span24{width: auto!important;}&#039;
              if (result === 1) {
                // 单列模式
                this.flushDom.insert(
                  await create_CSS_Node(expandStyle, &#039;AC-Style-expand&#039;)
                )
                await this.loadCommonStyle()
              } else if (result === 2) {
                //单页居中
                this.flushDom.insert(
                  await create_CSS_Node(expandStyle, &#039;AC-Style-expand&#039;)
                )
                await this.loadCommonStyle()
                await this.loadOnePageStyle()
              } else if (result === 3) {
                //双页居中
                await this.loadCommonStyle()
                await this.loadTwoPageStyle()
              } else if (result === 4) {
                // 三列
                await this.loadCommonStyle()
                await this.loadTwoPageStyle()
                await this.loadThreePageStyle()
              } else if (result === 5) {
                // 四列
                await this.loadCommonStyle()
                await this.loadTwoPageStyle()
                await this.loadFourPageStyle()
              }
              acCssLoadFlag = true
              debug(&#039;in样式运行结束&#039;)
              if (
                curSite.SiteTypeID === SiteType.BAIDU &amp;&amp;
                ACConfig.Style_BaiduLite === true
              ) {
                // AC_addStyle(GM_getResourceText(&quot;baiduLiteStyle&quot;), &quot;AC-baiduLiteStyle&quot;, &quot;head&quot;)
                await this.loadBaiduLiteStyle()
              }

              safeWaitFunc(&#039;body&#039;, async () =&gt; {
                if (result &gt; 0) {
                  // 非原始模式下
                  await this.loadBgImage()
                  CONST.useItem.defaultBgUrl &amp;&amp;
                    CONST.useItem.BgFit &amp;&amp;
                    (await this.loadBgAutoFit())
                  document.body.classList.remove(&#039;purecss-mode&#039;)
                  // document.querySelector(&quot;#rso &gt; div.hlcw0c &gt; div &gt; div &gt; div&quot;)
                } else {
                  document.body.classList.add(&#039;purecss-mode&#039;)
                }
              })
              this.flushDom.flush()
            }
            this.loadPlainToCSS()
            if (
              curSite.SiteTypeID !== SiteType.BAIDU &amp;&amp;
              curSite.SiteTypeID !== SiteType.BAIDU_XUESHU &amp;&amp;
              curSite.SiteTypeID !== SiteType.GOOGLE &amp;&amp;
              curSite.SiteTypeID !== SiteType.BING &amp;&amp;
              curSite.SiteTypeID !== SiteType.SOGOU &amp;&amp;
              curSite.SiteTypeID !== SiteType.DUCK &amp;&amp;
              curSite.SiteTypeID !== SiteType.DOGE
            )
              return

            // 如果是谷歌 &amp;&amp; (地址替换-&gt;是谷歌图像页面 || 是地图页面)[替换要变] return;
            if (
              curSite.SiteTypeID === SiteType.GOOGLE &amp;&amp;
              location.href.replace(/tbm=(isch|lcl|shop|flm)/, &#039;&#039;) !==
                location.href
            ) {
              this.loadCSSToPlain()
              return
            }
            this.huyanCheckAndLoad()
            this.flushCheckAndLoad()
          },
          flushDom: new FlushDomFragment(),
          huyanTimer: null,
          flushTimer: null,
          huyanCheckAndLoad: function () {
            /**护眼Style最后载入**/
            if (CONST.useItem.HuYanMode === true) {
              this.loadHuYanStyle()
            }
            if (!this.huyanTimer) {
              this.huyanTimer = setSlowInterval(() =&gt; {
                if (
                  document.querySelector(&quot;style[class*=&#039;darkreader&#039;]&quot;) != null
                ) {
                  this.loadHuYanStyle()
                  this.huyanTimer.cancel()
                }
              }, 100)
            }
          },
          flushCheckAndLoad: function () {
            if (!this.flushTimer) {
              this.flushTimer = setSlowInterval(() =&gt; {
                this.flushDom.flush()
              }, 600)
            }
          },
          init: function () {
            if (CONST.isGoogleImageUrl) return
            this.centerDisplay()
          }
        }
        return ControlManager
      }
    }
  })()
})()

