脚本内容
javascript// ==UserScript==
// @name         知乎隐藏标题
// @namespace    tampermonkey.net/
// @version      2025-09-28
// @description  try to take over the world!
// @author       Montarius
// @match        *://*/question/*
// @icon         static.zhihu.com/heifetz/assets/apple-touch-icon-152.81060cab.png
// @grant        none
// ==/UserScript==

(function() {
    &#039;use strict&#039;;

    console.log(&quot;知乎测试1111111111111111111111111&quot;);

    // Your code here...
    const selectors = [
        &quot;#root &gt; div &gt; div.css-s8xum0  &gt; header &gt; div &gt; div.css-51utkw  &gt; div.css-14iuq0r  &gt; div &gt; div &gt; div &gt; div.QuestionHeader-main &gt; h1&quot;,
        &quot;h1[data-cy=&#039;question-title&#039;]&quot;, // 备用选择器
        &quot;h1.title&quot; // 通用备用方案
    ];

    const findElement = () =&gt; {
        for (const selector of selectors) {
            const element = document.querySelector(selector);
            if (element) return element;
        }
        return null;
    };

    const element = findElement();
    if (element) {
        console.log(&quot; 元素内容:&quot;, element.innerText);
        element.style.display = &quot;none&quot;;
    } else {
        console.warn(&quot; 元素未找到，尝试监听动态加载...&quot;);
        const observer = new MutationObserver(() =&gt; {
            const el = findElement();
            if (el) {
                observer.disconnect();
                console.log(&quot; 动态加载的元素:&quot;, el);
                el.style.display = &quot;none&quot;;
            }
        });
        observer.observe(document.body, { childList: true, subtree: true });
    }
})();

b_code/脚本/tampermonkey/自动登录脚本.content:

                  概述 



网页网站自动登录脚本，内测等场景使用






                  相关说明 



一个简单的脚本


[toc]
脚本内容
javascript// ==UserScript==
// @name         EPP控制台自动登录
// @namespace    tampermonkey.net/
// @version      2025-01-07
// @description  try to take over the world!
// @author       You
// @match        *://*/*/dist/#/login?*
// @match        *://login\?origin/*
// @match        *://[0-9.]+/dist*
// @icon         www.google.com/s2/favicons
// @grant        none
// ==/UserScript==

(function() {
    &#039;use strict&#039;;

    console.log(&quot;测试代码&quot;);

    const MAX_RETRY = 5; // 最大重试次数
    const RETRY_INTERVAL = 2000; // 重试间隔时间（毫秒）

    let retryCount = 0; // 当前重试次数

    function loginButtonClick() {
        var loginButton = document.querySelector(&#039;button.btn-login.el-button--primary.el-button--medium&#039;);
        loginButton.click();
        var loginButton1 = document.querySelector(&#039;button.el-button.btn-login.el-button--primary.el-button--medium&#039;);
        loginButton1.click();
        setTimeout(loginButtonClick, 3000);
    }

    function tryLogin() {
        const inputElement = document.querySelector(&#039;input[name=&quot;username&quot;]&#039;) || document.querySelector(&#039;input[type=&quot;text&quot;][name=&quot;username&quot;]&#039;) || document.querySelector(&#039;input[type=&quot;username&quot;][name=&quot;username&quot;]&#039;);
        const inputElementPwd = document.querySelector(&#039;input[name=&quot;password&quot;][placeholder=&quot;请输入密码&quot;]&#039;) || document.querySelector(&#039;input[type=&quot;password&quot;][name=&quot;password&quot;][placeholder=&quot;请输入密码&quot;]&#039;);

        if (inputElement &amp;&amp; inputElementPwd) {
            simulateKeyboardInput(inputElement, &#039;eppadmin&#039;);
            simulateKeyboardInput(inputElementPwd, &#039;EPPAdmin@123456&#039;);
            loginButtonClick();
        } else if (retryCount &lt; MAX_RETRY) {
            retryCount++;
            setTimeout(tryLogin, RETRY_INTERVAL);
        }
    }

    function simulateKeyboardInput(element, text) {
        const dataTransfer = new DataTransfer();
        const inputEvent = new InputEvent(&#039;input&#039;, {
            bubbles: true,
            cancelable: true,
            data: text,
            inputType: &#039;insertText&#039;,
            dataTransfer: dataTransfer
        });

        element.focus();
        element.value = text;
        element.dispatchEvent(inputEvent);
        element.dispatchEvent(new Event(&#039;change&#039;));
    }

    window.addEventListener(&#039;load&#039;, tryLogin);
})();

c_opensource/minhook-windows-编译指南.content:
概述：MinHook——一个mini的Hook库。如何使用及原理解析


MinHook 说明
MinHook 是一个用C语言实现的 mini 的 Hook 项目，可同时适用于 x86/x64环境下，支持静态编译到项目中，目前 :star: Github Start 4K。
Github地址：TsudaKageyu/minhook: The Minimalistic x86/x64 API Hooking Library for Windows
使用
如何使用  MinHook ？
使用非常简单，初始化、创建Hook、启用Hook。大致代码如下所示：
Hook 实现修改弹窗: 实现Hook MsgBox弹窗,该库的原理与我们上面手动实现的方式是相同的.
C++cpp/* 
代码来自 C/C++ MinHook 库的使用技巧 - lyshark - 博客园
www.cnblogs.com/LyShark/p/13653435.html
*/
#include &lt;Windows.h&gt;
#include &lt;MinHook.h&gt;

#pragma comment(lib,&quot;libMinHook.x86.lib&quot;)

typedef int (WINAPI *OldMessageBox)(HWND, LPCSTR, LPCSTR, UINT);

OldMessageBox fpMessageBoxA = NULL;

int WINAPI MyMessageBoxA(HWND hWnd, LPCSTR lpText, LPCSTR lpCaption, UINT uType)
{
	int ret = fpMessageBoxA(hWnd, &quot;Hook Inject&quot;, lpCaption, uType);
	return ret;
}

void SetHook()
{
	if (MH_Initialize() == MB_OK)
	{
		MH_CreateHook(&amp;MessageBoxA, &amp;MyMessageBoxA, reinterpret_cast&lt;void**&gt;(&amp;fpMessageBoxA));
		MH_EnableHook(&amp;MessageBoxA);
	}
}

void UnHook()
{
	if (MH_DisableHook(&amp;MessageBoxA) == MB_OK)
	{
		MH_Uninitialize();
	}
}

BOOL APIENTRY DllMain(HMODULE hModule,DWORD ul_reason_for_call,LPVOID lpReserved)
{
	switch (ul_reason_for_call)
	{
	case DLL_PROCESS_ATTACH:
		SetHook();
		break;
	case DLL_PROCESS_DETACH:
		UnHook();
		break;
	}
	return TRUE;
}
这里还有其他一些例子，参考文章：C/C++ MinHook 库的使用技巧 - lyshark - 博客园
MinHook 原理分析
参考文章：

MinHook 分析01 （x86的jmp+offset类型hook） - 沉疴 - 博客园

c_opensource/mysql/mysql_connnector_8.0编.content:

                  概述 



本文主要记录 MySQL Connector/C++ 8.1 静态库的编译方式，因项目工程问题，需要编译 /MT 模式的静态库文件。
官方文档：4.3 从源安装连接器/C++_MySQL 连接器/C++ 8.0 开发人员指南



[toc]

 Debug 模式下 /MTd 编译 静态编译
 Release 模式下 /MT 编译 静态编译

前言
需求及官方文件说明
由于 MySQL官方并没有提供 /MT 模式的lib文件，因此编译所需要的静态库都需要从源码编译，首先说明一下官方已编译好的文件：
在 MySQL :: MySQL Connector/C++ Developer Guide :: 5.2.1 Windows Notes 这里可以看到官方提供了 /MD 模式下的 Debug 和 Release 静态库文件，下载为：MySQL :: Download MySQL Connector/C++ (Archived Versions)。关于下载后安装包的文件这我补充一下：

mysql-connector-C++-8.0.33-win32-debug：Debug 模式下 /MD 的编译产物
mysql-connector-C++-8.0.33-win32：Release 模式下 /MD 的编译产物

两个下载包的文件基本一致，主要是以下四个文件：

mysqlcppconn.lib: 使用 JDBC+openssl1.1.1 版本编译
mysqlcppconn8.lib：使用 X DEVAPI+openssl1.1.1 编译产物
mysqlcppconn8-static.lib：使用 X DEVAPI+OpenSSL3.3.1 编译产物
mysqlcppconn-static.lib：使用 JDBC+OpenSSL3.3.31 编译产物

使用 JDBC 和 X DEVAPI 的包需要使用不同的方式去连接 MySQL，具体代码如下所示：
使用 JDBC 连接
代码
C++cpp#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;list&gt;
#include &lt;cstdlib&gt;

#include &lt;mysqlx/xdevapi.h&gt;

using namespace mysqlx;
#ifdef _DEBUG
#pragma comment(lib, &quot;mysqlcppconn8-static-debug-openssl3-mdd.lib&quot;)    // 特殊命名标记了一下，官方库文件下 mysqlcppconn8_static.lib
#pragma comment(lib, &quot;dnsapi.lib&quot;)
#else
#pragma comment(lib, &quot;mysqlcppconn8_md.lib&quot;)// 特殊命名标记了一下，官方库文件下 mysqlcppconn8_static.libs
#pragma comment(lib, &quot;dnsapi.lib&quot;)
#endif // DEBUG

int main() {
    // 修改控制台编码
    // std::system(&quot;chcp 65001&quot;);

    try {
        // 改成你的信息b
        Session sess(SessionOption::USER, &quot;root&quot;,
            SessionOption::PWD, &quot;123456&quot;,
            SessionOption::HOST, &quot;localhost&quot;,
            SessionOption::PORT, 33060,
            SessionOption::DB, &quot;test&quot;);

        auto result = sess.sql(&quot;select * from user&quot;).execute();

        for (auto row : result.fetchAll()) {
            std::cout &lt;&lt; row[0] &lt;&lt; &quot; &quot; &lt;&lt; row[1] &lt;&lt; &quot; &quot; &lt;&lt; row[2] &lt;&lt; &quot;\n&quot;;
        }

    }
    catch (const std::exception&amp; e) {
        std::cerr &lt;&lt; e.what() &lt;&lt; &#039;\n&#039;;
    }
}
预处理器
参考官方说明：For aPPLications that use X DevAPI, X DevAPI for C, or (as of Connector/C++ 8.0.16) the legacy JDBC API, define the STATIC_CONCPP macro. All that matters is that you define it; the value does not matter. For example: -DSTATIC_CONCPP
使用 JDBC 连接编译时，需要在预处理器添加 STATIC_CONCPP 宏。

特别的，如果执行以上步骤之后还是编译报错，需要根据相关报错信息链接其他的库。如 MSCVRT.lib
使用cmkae生成工程文件

有其他特殊需求参考官方说明：MySQL :: MySQL Connector/C++ Developer Guide :: 4.3 Installing Connector/C++ from Source

官方要求安装boost库，实际编译不安装boost也可以编译成功。
编译命令如下所示：
cmakecmake . -G &quot;Visual Studio 15&quot; -A Win32 -DBUILD_STATIC=ON -DWITH_SSL=&quot;D:\OpenSSL-3.1-Win32-mtd&quot; -DWITH_JDBC=ON -DWITH_MYSQL=&quot;C:\Program Files\MySQL\MySQL Server 8.0&quot;
生成 vs2017工程（v141工具集）下的工程文件，产物为静态库，OpenSSL安装位置为 &quot;D:\OpenSSL-3.1-Win32-mtd。说明：

-G “Visual Studio 16”：指定工具集
-A Win32 指定生成的系统
-DBUILD_STATIC=ON：指定生成静态库
-DWITH_SSL=“D:\OpenSSL-3.1-Win32-mtd”：指定 OpenSSL 的安装位置
-DWITH_MYSQL=“C:\Program Files\MySQL\MySQL Server 8.0”：指定 mysql的安装位置
-DWITH_JDBC=ON：指定编译JDBC

由于需要 /MT 版本的，因此 OpenSSL 也需要自己编译 /MT 版本的才可以。
Release 模式编译
Release 模式的编译流程与 Debug 模式基本一致，主要区别在于 OpenSSL 的版本配置。
准备 Release 版 OpenSSL
由于 Release 模式需要 /MT 编译，需要准备相应版本的 OpenSSL：

Debug 模式：使用 OpenSSL-3.1-Win32-mtd（带调试符号）
Release 模式：使用 OpenSSL-3.1-Win32-mt（无调试符号）

OpenSSL 的编译命令参考（以 Release 为例）：
bash# 在 OpenSSL 源码目录执行
perl Configure VC-WIN32 no-shared -mt
nmake
编译完成后，将其安装到如 D:\OpenSSL-3.1-Win32-mt 目录。
CMake 生成工程（Release）
Release 模式的 CMake 配置命令：
cmakecmake . -G &quot;Visual Studio 15&quot; -A Win32 -DBUILD_STATIC=ON -DWITH_SSL=&quot;D:\OpenSSL-3.1-Win32-mt&quot; -DWITH_JDBC=ON -DWITH_MYSQL=&quot;C:\Program Files\MySQL\MySQL Server 8.0&quot;
主要变化：

将 OpenSSL 路径从 mtd 改为 mt
其他参数与 Debug 模式保持一致

编译 Release 静态库
bash# 生成工程文件后，使用 MSBuild 编译
msbuild mysqlcppconn8-static.vcxproj /p:Configuration=Release /p:Platform=Win32
或者直接用 Visual Studio 打开解决方案，选择 Release 配置进行编译。
编译产物
编译成功后，在 build/release 目录下会生成以下静态库文件：

mysqlcppconn8-static.lib - X DevAPI 版本（推荐）
mysqlcppconn-static.lib - JDBC 版本

Release 模式使用示例
在项目中使用 Release 版静态库的配置：
C++cpp#include &lt;mysqlx/xdevapi.h&gt;

using namespace mysqlx;

// 链接 Release 版静态库
#pragma comment(lib, &quot;mysqlcppconn8-static.lib&quot;)  // Release 版
#pragma comment(lib, &quot;dnsapi.lib&quot;)

// 如果使用 X DevAPI，也需要定义 STATIC_CONCPP
#define STATIC_CONCPP

int main() {
    try {
        Session sess(SessionOption::USER, &quot;root&quot;,
                     SessionOption::PWD, &quot;yourpassword&quot;,
                     SessionOption::HOST, &quot;localhost&quot;,
                     SessionOption::PORT, 33060,
                     SessionOption::DB, &quot;test&quot;);

        auto result = sess.sql(&quot;SELECT VERSION()&quot;).execute();
        std::cout &lt;&lt; &quot;MySQL Version: &quot; &lt;&lt; result.fetchOne()[0] &lt;&lt; std::endl;
    }
    catch (const std::exception&amp; e) {
        std::cerr &lt;&lt; &quot;Error: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
        return 1;
    }
    return 0;
}
注意事项

运行时库配置：确保项目属性中的「C/C++ → 代码生成 → 运行时库」设置为 多线程 (/MT)
预处理器宏：使用静态库时需要定义 STATIC_CONCPP
依赖库：可能还需要链接系统库如 ws2_32.lib、crypt32.lib 等
OpenSSL 依赖：虽然编译为静态库，但运行时仍需 OpenSSL 的 DLL 文件在 PATH 中

c_opensource/openssl/使用sm3加密文件.content:

                  概述 



使用 OpensSSL 进行 SM3 加密



以下是使用 OpenSSL 库进行 SM3 消息摘要和文件加密的 C++ 示例代码：
C++cpp#include &lt;iostream&gt;
#include &lt;fstream&gt;
#include &lt;string&gt;
#include &lt;openssl/evp.h&gt;
#include &lt;openssl/sha.h&gt;
#include &lt;openssl/sm3.h&gt;

// 计算字符串的 SM3 摘要值
std::string sm3_hash_string(const std::string&amp; str) {
    unsigned char md[SM3_DIGEST_LENGTH];
    SM3(reinterpret_cast&lt;const unsigned char*&gt;(str.data()), str.size(), md);
    std::string hash_str(reinterpret_cast&lt;const char*&gt;(md), SM3_DIGEST_LENGTH);
    return hash_str;
}

// 计算文件的 SM3 摘要值
std::string sm3_hash_file(const std::string&amp; file_path) {
    unsigned char md[SM3_DIGEST_LENGTH];
    std::ifstream input(file_path, std::ios::binary);
    if (input) {
        EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
        EVP_DigestInit_ex(mdctx, EVP_sm3(), nullptr);
        const size_t buf_size = 4096;
        char buf[buf_size];
        while (input.read(buf, buf_size)) {
            EVP_DigestUpdate(mdctx, buf, buf_size);
        }
        size_t remain_size = input.gcount();
        EVP_DigestUpdate(mdctx, buf, remain_size);
        EVP_DigestFinal_ex(mdctx, md, nullptr);
        EVP_MD_CTX_free(mdctx);
        input.close();
        std::string hash_str(reinterpret_cast&lt;const char*&gt;(md), SM3_DIGEST_LENGTH);
        return hash_str;
    }
    else {
        throw std::runtime_error(&quot;fail to open file &quot; + file_path);
    }
}

// 使用密码对文件进行加密
void encrypt_file(const std::string&amp; input_file_path, const std::string&amp; output_file_path, const std::string&amp; password) {
    std::ifstream input(input_file_path, std::ios::binary);
    std::ofstream output(output_file_path, std::ios::binary);
    if (input &amp;&amp; output) {
        const int key_len = EVP_MAX_KEY_LENGTH;
        const int iv_len = EVP_MAX_IV_LENGTH;
        unsigned char key[key_len];
        unsigned char iv[iv_len];
        EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sm3(), nullptr, reinterpret_cast&lt;const unsigned char*&gt;(password.data()), password.size(), 1, key, iv);
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key, iv);
        const size_t buf_size = 4096;
        char buf[buf_size];
        while (input.read(buf, buf_size)) {
            int len = input.gcount();
            int out_len = 0;
            EVP_EncryptUpdate(ctx, reinterpret_cast&lt;unsigned char*&gt;(buf), &amp;out_len, reinterpret_cast&lt;unsigned char*&gt;(buf), len);
            output.write(buf, out_len);
        }
        int len = input.gcount();
        int out_len = 0;
        EVP_EncryptFinal_ex(ctx, reinterpret_cast&lt;unsigned char*&gt;(buf), &amp;out_len);
        output.write(buf, out_len);
        EVP_CIPHER_CTX_free(ctx);
        input.close();
        output.close();
    }
    else {
        throw std::runtime_error(&quot;fail to open input/output file.&quot;);
    }

}

int main() {
    std::string str = &quot;message to be hashed&quot;;
    std::cout &lt;&lt; &quot;SM3 hash of string \&quot;&quot; &lt;&lt; str &lt;&lt; &quot;\&quot;: &quot; &lt;&lt; sm3_hash_string(str) &lt;&lt; std::endl;
    std::string file_path = &quot;test.txt&quot;;
    std::cout &lt;&lt; &quot;SM3 hash of file \&quot;&quot; &lt;&lt; file_path &lt;&lt; &quot;\&quot;: &quot; &lt;&lt; sm3_hash_file(file_path) &lt;&lt; std::endl;
    std::string password = &quot;123456&quot;;
    try {
        encrypt_file(file_path, &quot;test_encrypted.txt&quot;, password);
    }
    catch (const std::exception&amp; e) {
        std::cout &lt;&lt; &quot;Error: &quot; &lt;&lt; e.what() &lt;&lt; std::endl;
    }
    return 0;
}
上述代码中，使用 SM3 函数对字符串或文件内容进行摘要；使用 EVP_BytesToKey 函数生成密码加密密钥和初始化向量，并使用 EVP_EncryptInit_ex 函数初始化加密上下文，在循环中调用 EVP_EncryptUpdate 函数对文件进行逐块加密，最后调用 EVP_EncryptFinal_ex 函数完成加密过程，将结果写入新的加密文件中。

c_opensource/rapidjson.content:

                  本文由 AI 辅助生成，内容已验证可用 



概述
RapidJSON 是一个 C++ 的 JSON 解析器及生成器，灵感来自 RapidXml。
核心特点：

高性能：使用 SIMD 指令加速解析
头文件库：无需编译，直接包含即可使用
内存友好：支持原位解析，减少内存分配
标准兼容：支持 JSON 标准 RFC7159 和 ECMA-404
跨平台：支持各大编译器和操作系统


官方文档：RapidJSON 主页



快速开始
安装
RapidJSON 是纯头文件库，只需下载并包含头文件即可：
bash# 方式一：直接下载
git clone github.com/Tencent/rapidjson.git

# 方式二：使用 vcpkg
vcpkg install rapidjson

# 方式三：使用 CMake FetchContent
include(FetchContent)
FetchContent_Declare(
    rapidjson
    GIT_REPOSITORY github.com/Tencent/rapidjson.git
    GIT_TAG master
)
FetchContent_MakeAvailable(rapidjson)
包含头文件
C++cpp#include &quot;rapidjson/document.h&quot;
#include &quot;rapidjson/writer.h&quot;
#include &quot;rapidjson/stringbuffer.h&quot;
#include &quot;rapidjson/prettywriter.h&quot;
#include &lt;iostream&gt;

using namespace rapidjson;

核心 API
1. 解析 JSON 字符串
C++cpp// 从字符串解析
const char* json = R&quot;({
    &quot;name&quot;: &quot;小明&quot;,
    &quot;age&quot;: 25,
    &quot;skills&quot;: [&quot;C++&quot;, &quot;Python&quot;, &quot;Rust&quot;],
    &quot;active&quot;: true
})&quot;;

Document doc;
doc.Parse(json);

// 检查解析错误
if (doc.HasParseError()) {
    std::cerr &lt;&lt; &quot;解析错误: &quot; &lt;&lt; doc.GetParseError() &lt;&lt; std::endl;
    return -1;
}
2. 访问 JSON 值
C++cpp// 获取对象成员
assert(doc.HasMember(&quot;name&quot;));
assert(doc[&quot;name&quot;].IsString());
std::string name = doc[&quot;name&quot;].GetString();

// 获取数值
int age = doc[&quot;age&quot;].GetInt();
bool active = doc[&quot;active&quot;].GetBool();

// 获取数组
const Value&amp; skills = doc[&quot;skills&quot;];
assert(skills.IsArray());
for (SizeType i = 0; i &lt; skills.Size(); i++) {
    std::cout &lt;&lt; &quot;Skill: &quot; &lt;&lt; skills[i].GetString() &lt;&lt; std::endl;
}

// 使用迭代器遍历
for (Value::ConstMemberIterator itr = doc.MemberBegin();
     itr != doc.MemberEnd(); ++itr) {
    std::cout &lt;&lt; itr-&gt;name.GetString() &lt;&lt; &quot;: &quot;;
    // 根据 value 类型输出
}
3. 创建 JSON 文档
C++cppDocument doc;
doc.SetObject();

// 添加字符串
Document::AllocatorType&amp; allocator = doc.GetAllocator();
doc.AddMember(&quot;name&quot;, &quot;小明&quot;, allocator);

// 添加数值
doc.AddMember(&quot;age&quot;, 25, allocator);

// 添加布尔值
doc.AddMember(&quot;active&quot;, true, allocator);

// 创建数组
Value skills(kArrayType);
skills.PushBack(&quot;C++&quot;, allocator);
skills.PushBack(&quot;Python&quot;, allocator);
doc.AddMember(&quot;skills&quot;, skills, allocator);

// 创建嵌套对象
Value address(kObjectType);
address.AddMember(&quot;city&quot;, &quot;北京&quot;, allocator);
address.AddMember(&quot;zip&quot;, &quot;100000&quot;, allocator);
doc.AddMember(&quot;address&quot;, address, allocator);
4. 序列化输出
C++cpp// 方式一：紧凑格式
StringBuffer buffer;
Writer&lt;StringBuffer&gt; writer(buffer);
doc.Accept(writer);
std::cout &lt;&lt; buffer.GetString() &lt;&lt; std::endl;

// 方式二：美化格式（带缩进）
StringBuffer buffer;
PrettyWriter&lt;StringBuffer&gt; prettyWriter(buffer);
doc.Accept(prettyWriter);
std::cout &lt;&lt; buffer.GetString() &lt;&lt; std::endl;

进阶用法
原位解析（In-situ Parsing）
减少内存分配，直接修改原始 JSON 字符串：
C++cppchar json[] = R&quot;({&quot;name&quot;:&quot;小明&quot;,&quot;age&quot;:25})&quot;;
Document doc;
doc.ParseInsitu(json);  // 直接在原字符串上解析

// 注意：原字符串会被修改
自定义内存分配器
C++cpp// 使用内存池分配器，提升性能
MemoryPoolAllocator&lt;&gt; allocator;
Document doc(&amp;allocator);
处理大文件（流式解析）
C++cpp#include &quot;rapidjson/filereadstream.h&quot;
#include &quot;rapidjson/filewritestream.h&quot;

// 读取大文件
FILE* fp = fopen(&quot;large.json&quot;, &quot;rb&quot;);
char readBuffer[65536];
FileReadStream is(fp, readBuffer, sizeof(readBuffer));

Document doc;
doc.ParseStream(is);
fclose(fp);

// 写入大文件
FILE* fp2 = fopen(&quot;output.json&quot;, &quot;wb&quot;);
char writeBuffer[65536];
FileWriteStream os(fp2, writeBuffer, sizeof(writeBuffer));
PrettyWriter&lt;FileWriteStream&gt; writer(os);
doc.Accept(writer);
fclose(fp2);
JSON Schema 验证
C++cpp#include &quot;rapidjson/schema.h&quot;

Document sd;
sd.Parse(R&quot;({
    &quot;type&quot;: &quot;object&quot;,
    &quot;properties&quot;: {
        &quot;name&quot;: {&quot;type&quot;: &quot;string&quot;},
        &quot;age&quot;: {&quot;type&quot;: &quot;integer&quot;, &quot;minimum&quot;: 0}
    },
    &quot;required&quot;: [&quot;name&quot;, &quot;age&quot;]
})&quot;);

SchemaDocument schema(sd);
Document doc;
doc.Parse(R&quot;({&quot;name&quot;:&quot;小明&quot;,&quot;age&quot;:25})&quot;);

SchemaValidator validator(schema);
if (!doc.Accept(validator)) {
    // 验证失败，输出错误信息
    StringBuffer sb;
    validator.GetInvalidSchemaPointer().StringifyUriFragment(sb);
    printf(&quot;Invalid schema: %s\n&quot;, sb.GetString());
    printf(&quot;Invalid keyword: %s\n&quot;, validator.GetInvalidSchemaKeyword());
}

类型判断与转换
类型判断 API
C++cppValue v;
v.IsNull();      // 是否为 null
v.IsFalse();     // 是否为 false
v.IsTrue();      // 是否为 true
v.IsBool();      // 是否为布尔值
v.IsObject();    // 是否为对象
v.IsArray();     // 是否为数组
v.IsString();    // 是否为字符串
v.IsNumber();    // 是否为数值
v.IsInt();       // 是否为 int
v.IsUint();      // 是否为 unsigned int
v.IsInt64();     // 是否为 int64_t
v.IsUint64();    // 是否为 uint64_t
v.IsDouble();    // 是否为 double
数值获取 API
C++cppv.GetInt();      // 获取 int
v.GetUint();     // 获取 unsigned int
v.GetInt64();    // 获取 int64_t
v.GetUint64();   // 获取 uint64_t
v.GetDouble();   // 获取 double
v.GetBool();     // 获取 bool
v.GetString();   // 获取 const char*
v.GetStringLength(); // 获取字符串长度

常见问题
1. 中文乱码问题
RapidJSON 原生支持 UTF-8，确保源文件编码为 UTF-8：
C++cpp// 使用 UTF-8 编码保存文件
const char* json = R&quot;({&quot;name&quot;:&quot;小明&quot;})&quot;;
2. 内存泄漏问题
使用内存池分配器时，注意生命周期：
C++cppvoid ProcessJson() {
    MemoryPoolAllocator&lt;&gt; allocator;
    Document doc(&amp;allocator);
    // ... 使用 doc
    // 离开作用域，自动释放
}
3. 性能优化建议

使用 ParseInsitu() 减少内存分配
重用 Document 和 Allocator 对象
对于大量小 JSON，使用内存池分配器
启用 SIMD 优化（需要编译器支持）


完整示例
C++cpp#include &quot;rapidjson/document.h&quot;
#include &quot;rapidjson/writer.h&quot;
#include &quot;rapidjson/stringbuffer.h&quot;
#include &quot;rapidjson/prettywriter.h&quot;
#include &lt;iostream&gt;

using namespace rapidjson;

int main() {
    // 1. 创建 JSON 文档
    Document doc;
    doc.SetObject();
    Document::AllocatorType&amp; allocator = doc.GetAllocator();

    // 2. 添加数据
    doc.AddMember(&quot;project&quot;, &quot;RapidJSON Demo&quot;, allocator);
    doc.AddMember(&quot;version&quot;, 1.0, allocator);

    Value tags(kArrayType);
    tags.PushBack(&quot;JSON&quot;, allocator);
    tags.PushBack(&quot;C++&quot;, allocator);
    tags.PushBack(&quot;高性能&quot;, allocator);
    doc.AddMember(&quot;tags&quot;, tags, allocator);

    // 3. 序列化输出
    StringBuffer buffer;
    PrettyWriter&lt;StringBuffer&gt; writer(buffer);
    doc.Accept(writer);

    std::cout &lt;&lt; &quot;生成的 JSON:\n&quot; &lt;&lt; buffer.GetString() &lt;&lt; std::endl;

    // 4. 解析 JSON
    Document parsedDoc;
    parsedDoc.Parse(buffer.GetString());

    // 5. 访问数据
    std::cout &lt;&lt; &quot;\n解析结果:\n&quot;;
    std::cout &lt;&lt; &quot;Project: &quot; &lt;&lt; parsedDoc[&quot;project&quot;].GetString() &lt;&lt; std::endl;
    std::cout &lt;&lt; &quot;Version: &quot; &lt;&lt; parsedDoc[&quot;version&quot;].GetDouble() &lt;&lt; std::endl;

    return 0;
}
输出结果：
{}json{
    &quot;project&quot;: &quot;RapidJSON Demo&quot;,
    &quot;version&quot;: 1.0,
    &quot;tags&quot;: [&quot;JSON&quot;, &quot;C++&quot;, &quot;高性能&quot;]
}

解析结果:
Project: RapidJSON Demo
Version: 1.0

相关链接

JSON - JSON 格式基础
C++ - C++ 语言相关
GitHub 仓库
官方文档
性能测试


总结
RapidJSON 是一个高性能、易用、功能完善的 C++ JSON 库，适合：
✅ 需要高性能 JSON 解析的项目
✅ 嵌入式或内存受限环境
✅ 只需头文件即可集成的场景
✅ 需要流式解析大文件的场景
如果你的项目需要处理 JSON，RapidJSON 是一个非常值得考虑的选择。

c_opensource/libevent/evconnlistener_new.content:
概述：libevent 接口 evconnlistener_new_bind 的使用说明


libevent封装了监听套接字，将套接字和struct event统一管理。
官方的解释是：

The evonnlistener mechanism gives you a way to listen for and accept incoming TCP connections

首先还是学习怎么去使用evconnlistener
（一）接口
C++cpp//创建
struct evconnlistener *evconnlistener_new(struct event_base*base,evconnlistener_cb cb,
void *ptr,unsigned flags ,int backlog,evutil_socket_t fd);
struct evconnlistener*evconnlistener_new_bind(struct event_base*base,evconnlistener_cb cb,
void *ptr,unsigned flags,int backlog,const struct sockaddr*sa,int socklen);
void evconnlistener_free(struct evconnlistener*lev)
//其中callback的定义如下：
typedef void (*evconnlistener_cb)(struct evconnlistener *listener,evutil_socket_t sock,
        struct sockaddr*addr,int len,void *ptr);
//enable 和 disable
int evconnlistener_disable(struct evconnlistener *lev);
int evconnlistener_enable(struct evconnlistener *lev);
//调整callback
void evconnlistener_set_cb(struct evconnlistener*lev,evconnlistener_cb cb,void *arg)
//检查evconnlistener
evutil_socket_t evconnlistener_get_fd(struct evconnlistener *lev)
struct event_base *evconnlistener_get_base(struct evconnlistener*lev)
evconnlistener是对  套接字和event 的封装，可以想见，在这些接口中，除了调用[[【网络编程】SOCKET相关函数|Socket]] api之外，还会关联套接子到event上进而注册到event_base上去
不过接口封装好了这些行为，只需要了解这些参数的含义即可。

base：即event_base
cb：当有新连接时调用的回调函数
ptr：callback的参数
flags：控制listner的行为
backlog：同 listen(2)中backlog的含义
fd：已经bind的fd，传入api让libevent做listen调用

（二）例子
使用evconnlistener管理监听套接字构建一个简单的 echo server
代码也可参考gayhub
C++cpp#include &lt;event2/listener.h&gt;
#include &lt;event2/bufferevent.h&gt;
#include &lt;event2/buffer.h&gt;
#include &lt;arpa/inet.h&gt;
#include &lt;string.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdio.h&gt;
#include &lt;errno.h&gt;
#include &lt;assert.h&gt;
static void 
echo_read_cb(struct bufferevent*bev,void*ctx)
{
    struct evbuffer*input=bufferevent_get_input(bev);
    struct evbuffer*output=bufferevent_get_output(bev);
    evbuffer_add_buffer(output,input);
}
static void
echo_event_cb(struct bufferevent*bev,short events,void*ctx)
{
    if(events&amp;BEV_EVENT_ERROR)
    perror(&quot;Error from bufferevent&quot;);
    if(events&amp;(BEV_EVENT_EOF|BEV_EVENT_ERROR))
    {
    bufferevent_free(bev);
    }
}
static void
accept_error_cb(struct evconnlistener*listener,void*ctx)
{
    struct event_base*base=evconnlistener_get_base(listener);
    event_base_loopexit(base,NULL);
}
void accept_conn_cb(struct evconnlistener*listener,evutil_socket_t fd,struct sockaddr*address,int socklen,void*ctx)
{
    struct event_base*base=evconnlistener_get_base(listener);
    struct bufferevent*bev = bufferevent_socket_new(base,
        fd,
        BEV_OPT_CLOSE_ON_FREE);
    bufferevent_setcb(bev,echo_read_cb,NULL,echo_event_cb,NULL);
    bufferevent_enable(bev,EV_READ|EV_WRITE);
}
int main(int argc,char**argv)
{
    struct event_base *base;
    struct evconnlistener *listener;
    struct sockaddr_in sin;
    int port = 1025;
    base = event_base_new();
    assert(base!=NULL);
    memset(&amp;sin,0,sizeof(sin));
    sin.sin_family=AF_INET;
    sin.sin_addr.s_addr=htonl(0);
    sin.sin_port=htons(port);
    listener=evconnlistener_new_bind(base,//event_base
        accept_conn_cb,//cb
        NULL,// ptr
        LEV_OPT_CLOSE_ON_FREE|LEV_OPT_REUSEABLE,//flag
        -1,//backlog
        (struct sockaddr*)&amp;sin,
        sizeof(sin));
    assert(listener!=NULL);
    evconnlistener_set_error_cb(listener,accept_error_cb);
    event_base_dispatch(base);
    return 0;
}
（三）源码
看看evconnlistenr做了哪些封装
3.1结构体
C++cppstruct evconnlistener {
    const struct evconnlistener_ops *ops; //一些回调函数
    void *lock;
    evconnlistener_cb cb;//
    evconnlistener_errorcb errorcb;
    void *user_data;//
    unsigned flags;
    short refcnt;
    unsigned enabled : 1;
};
struct evconnlistener_event {
    struct evconnlistener base;
    struct event listener;
};
evconnlistener结构体将一些基本的回调函数、用户数据等封装，然后evconnlistener_event将这些东西和struct event封装在一起
3.2创建一个evconnlistener
看一下初始化有哪些内容：
C++cppstruct evconnlistener *
evconnlistener_new(struct event_base *base,
    evconnlistener_cb cb, void *ptr, unsigned flags, int backlog,
    evutil_socket_t fd)
{
    struct evconnlistener_event *lev;
    if (backlog &gt; 0) {
        if (listen(fd, backlog) &lt; 0)//调用listen
            return NULL;
    } else if (backlog &lt; 0) {
        if (listen(fd, 128) &lt; 0)
            return NULL;
    }
    lev = mm_calloc(1, sizeof(struct evconnlistener_event));
    if (!lev)
        return NULL;
        //lev-&gt;base是一个evconnlistener结构体
    lev-&gt;base.ops = &amp;evconnlistener_event_ops;//设置ops参数
    lev-&gt;base.cb = cb;//设置回调
    lev-&gt;base.user_data = ptr;//ptr
    lev-&gt;base.flags = flags;//flag
    lev-&gt;base.refcnt = 1;
    if (flags &amp; LEV_OPT_THREADSAFE) {
        EVTHREAD_ALLOC_LOCK(lev-&gt;base.lock, EVTHREAD_LOCKTYPE_RECURSIVE);
    }
    //将fd关联到struct event上去 lev-&gt;listener是struct event结构体
    //这样assigh将listener_read_cb设置到event的cb中，并将struct evconnlistner做为参数
    //这是一个比较复杂的过程，首先由于event激活，将先调用listener_read_cb
    //在listener_read_cb通过传入的struct evconnlistner调用用户自定义回调
    event_assign(&amp;lev-&gt;listener, base, fd, EV_READ|EV_PERSIST,
        listener_read_cb, lev);
        //这里底层调用event_enable
    evconnlistener_enable(&amp;lev-&gt;base);
    return &amp;lev-&gt;base;
}
在另外一个接口evconnlistener_new_bind中由于指定了套接字结构体，因此在底层还调用了bind
3.3 listener_read_cb
这个底层的回调函数先于用户回调函数调用，在这个回调中会调用用户回调，并且会将已连接的套接字作为参数传入用户回调，
这也正是evconnlistener的精髓，无需要用户进行listen、bind、accept等操作
C++cppstatic void
listener_read_cb(evutil_socket_t fd, short what, void *p)
{
    struct evconnlistener *lev = p;
    int err;
    evconnlistener_cb cb;
    evconnlistener_errorcb errorcb;
    void *user_data;
    LOCK(lev);
    while (1) {
        struct sockaddr_storage ss;
        socklen_t socklen = sizeof(ss);
        evutil_socket_t new_fd = accept(fd, (struct sockaddr*)&amp;ss, &amp;socklen);//accept
        if (new_fd &lt; 0)
            break;
        if (socklen == 0) {
            /* This can happen with some older linux kernels in
             * response to nmap. */
            evutil_closesocket(new_fd);
            continue;
        }
        if (!(lev-&gt;flags &amp; LEV_OPT_LEAVE_SOCKETS_BLOCKING))
            evutil_make_socket_nonblocking(new_fd);//non blocking
        if (lev-&gt;cb == NULL) {
            UNLOCK(lev);
            return;
        }
        ++lev-&gt;refcnt;
        cb = lev-&gt;cb;//拿到用户回调
        user_data = lev-&gt;user_data;
        UNLOCK(lev);
        cb(lev, new_fd, (struct sockaddr*)&amp;ss, (int)socklen,
            user_data);//调用用户回调并将connfd传入用户回调
        LOCK(lev);
        if (lev-&gt;refcnt == 1) {
            int freed = listener_decref_and_unlock(lev);
            EVUTIL_ASSERT(freed);
            return;
        }
        --lev-&gt;refcnt;
    }
}
（四）参考
1.libevent programming
2.libevent 深入浅出

