wiki/pe/pe文件结构12-tls表.content:
概述：TLS(TLSDirectory) 的说明和使用


0x01 TLS
TLS全称线程局部存储器，它用来保存变量或回调函数。
TLS里面的变量和回调函数都在程序入口点（AddressOfEntry）之前执行，也就是说程序在被调试时，还没有在入口点处断下来之前，TLS中的变量和回调函数就已经执行完了，所以TLS可以用作反调试之类的操作。
TLS中的变量单独存在于每个独立的线程当中，每个线程中对该变量的操作都不会影响到其他线程中的TLS变量。
TLS变量的创建方法有两种方式，分别是动态方式和静态方式，动态方法会用到TlsAlloc、TlsFree、TlsSetValue、TlsGetValue这几个函数来操作变量，静态方法会用声明__declspec (thread) int xx = 1;这样的方式来创建。需要注意的是静态创建的TLS变量不能用于DLL动态库中。
理论说的多了未免有点枯燥，先写个实例吧，说明变量和回调函数的创建，这样明白的更透彻一点。
0x02 TLS实例
C++cpp__declspec (thread)int g_nNum = 0x11111111;
__declspec (thread)char g_szStr[] = &quot;TLS g_nNum = 0x%p ...\r\n&quot;;

void NTAPI t_TlsCallBack_A(PVOID DllHandle, DWORD Reason, PVOID Red)
{
	if (DLL_THREAD_DETACH == Reason)
	{
		printf(&quot;t_TlsCallBack_A -&gt; ThreadDetach!\r\n&quot;);
		return;
	}
}
void NTAPI t_TlsCallBack_B(PVOID DllHandle, DWORD Reason, PVOID Red)
{
	if (DLL_THREAD_DETACH == Reason)
	{
		printf(&quot;t_TlsCallBack_B -&gt; ThreadDetach!\r\n&quot;);
		return;
	}
}

#pragma  data_seg(&quot;.CRT$XLB&quot;)
PIMAGE_TLS_CALLBACK p_thread_callback[] = {
	t_TlsCallBack_A,
	t_TlsCallBack_B,
	NULL
};
#pragma  data_seg()

DWORD WINAPI t_ThreadFun(PVOID pParam)
{
	printf(&quot;t_Thread -&gt;   first printf:&quot;);
	printf(g_szStr, g_nNum);
	g_nNum = 0x2222222;
	printf(&quot;t_Thread -&gt; second printf:&quot;);
	printf(g_szStr, g_nNum);
	return 0;
}
int _tmain()
{
	printf(&quot;_tmain -&gt; TlsDemo.exe is running...\r\n\r\n&quot;);

	CreateThread(NULL, 0, t_ThreadFun, NULL, 0, 0);
	Sleep(100);
	printf(&quot;\r\n&quot;);
	CreateThread(NULL, 0, t_ThreadFun, NULL, 0, 0);

	system(&quot;pause&quot;);

	return 0;
}
首先我们看注册TLS变量的方式，本例子使用的是静态方法也就是__declspec (thread)int xx = 1;这样的方式来创建，而注册回调函数相对比较麻烦点，我们要声明一个#pragma data_seg(”.CRT$XLB”)这样的宏定义将回调函数包起来，CRT表明使用C RunTime机制，X表示标识名随机，L表示TLS callback section，B可以是B-Y之间任意的字母。
我们还看见回调函数会在线程被终止时调用，并且调用的顺序跟注册回调函数时相关，其实回调函数不止会在线程终止时调用，还有以下几种情况会被调用。
Transclude of 【pe】pe文件结构1格式学习（十二）：TLS表](【PE】PE文件结构12-TLS表/1240.webp)
具体的参见代码吧，打印结果如下：

可以看见两个线程对g_nNum的操作其实是互不影响的，在程序运行到入口点之前，g_nNum已经被初始化了，以后每开辟一条新的线程，系统都会拷贝一份TLS变量的副本到该线程中。
0x03 TLS 解析
接下来对TLS在PE文件中的结构进行解析。TLS在PE中数据目录表的第10位。
通常一个包含了TLS表的程序，它就会拥有.tls段，这个段里面保存了变量和回调函数的数据，但是TLS表本身的结构体一般存在于.rdata段内。本文的例子程序的TLS表RVA是0x2200，通过转换为offset得到0x1000,我们到0x1000处看看十六进制再对比结构体字段就可以解析出TLS表了。
C++cpptypedef struct _IMAGE_TLS_DIRECTORY32 
{
    DWORD   StartAddressOfRawData;
    DWORD   EndAddressOfRawData;
    PDWORD  AddressOfIndex;
    PIMAGE_TLS_CALLBACK *AddressOfCallBacks;
    DWORD   SizeOfZeroFill;
    DWORD   Characteristics;
} IMAGE_TLS_DIRECTORY32
以上述代码为例：编译 x64-debug 版本后分析如下所示：

可以看到 .tls 段的起始地址为 E200h。 也就是.tls 段的偏移在 E200h位置，跳转到 E200h 看一下。

从 E2000h 开始就可以使用 _IMAGE_TLS_DIRECTORY32 结构体读取 tls 表了。
在 tls 段内存中就能看到 TLS 变量了

wiki/pe/pe文件结构6-异常表(exception).content:
date: 2023/12/19
概述：x86系统采用动态的方式构建SEH结构，相比而言x64系统下采用静态的方式处理SEH结构，它保存PE文件中，通常在.pdata区段。因此本文的例子采用x64编译过的程序。异常表在资源表的后面。


0x01 异常表解析
数据目录表的第四个元素指向异常表，RVA指向的是一个IMAGE_IA64_RUNTIME_FUNCTION_ENTRY的结构体，本例的RVA是0xA000（也就是.pdata段的起始位置），转换成offset是0x7a00。它的结构体是：
C++cpptypedef struct _IMAGE_IA64_RUNTIME_FUNCTION_ENTRY {
    DWORD BeginAddress;      //与SEH相关代码的起始偏移地址
    DWORD EndAddress;        //与SEH相关代码的末尾偏移地址
    DWORD UnwindInfoAddress; //指向描述上面两个字段之间代码异常信息的UNWIND_INFO
} IMAGE_IA64_RUNTIME_FUNCTION_ENTRY, *PIMAGE_IA64_RUNTIME_FUNCTION_ENTRY;
​    BeginAddress 与 EndAddress之间，是异常处理函数的内容。UnwindInfoAddress 指向的位置是用来描述 BeginAddress 与 EndAddress 之间的代码异常属性信息的UNWIND_INFO。UNWIND_INFO 也叫作异常展开信息，此结构用来描述堆栈指针的记录属性与寄存器中保存的地址属性，它的结构体如下：
C++cppstruct _UNWIND_INFO {
   UBYTE Version:3;        
   UBYTE Flags:5; 
   UBYTE SizeOfProlog;        
   UBYTE CountOfCodes;   
   UBYTE FrameRegister:4;
   UBYTE FrameOffset:4;
   UNWIND_CODE UnwindCode[1];
   union {
        // If (Flags &amp; UNW_FLAG_EHANDLER)
       OPTIONAL ULONG ExceptionHandler;//异常/终止函数的映像相对地址指针
       // Else if (Flags &amp; UNW_FLAG_CHAININFO)
       OPTIONAL ULONG FunctionEntry;//展开信息链的映像相对地址指针
   };
   // If (Flags &amp; UNW_FLAG_EHANDLER)
   ULONG ExceptionData[1];//异常处理程序的数据
} UNWIND_INFO, *PUNWIND_INFO;
Version:异常展开信息的版本号，一般为0x001
Flags:共有四种标志：

当它为0x0的时候表示UNW_FLAG_NHANDLER，没有异常处理函数。
当它为0x1的时候表示UNW_FLAG_EHANDLER，有异常处理函数。
当它为0x2的时候表示UNW_FLAG_UHANDLER，有系统默认的处理函数。
当它为0x4的时候表示UNW_FLAG_CHAININFO，表示FunctionEntry指向的是前一个RUNTIME_FUNCTION的RAV。

SizeOfProlog:函数起始部分字节的长度
CountOfCodes:UNWIND_INFO结构包含的UNWIND_CODE结构数
FrameRegister:寄存器帧指针，为0则指定函数不使用框架
FrameOffset:若上面字段不为0，表示函数偏移
UnwindCode:指定永久性寄存器与RSP的数组项目数
ExceptionHandler:异常句柄
FunctionEntry:展开信息链（函数）的映像相对地址指针（如果设置了UNW_FLAG_CHAININFO标识）
ExceptionData:异常处理程序的数据
查找SEH表
以下代码说明：打开一个进程模块，然后查找 .pdata 段，依次遍历异常表。
C++cppconst char	gPDataSectionName[] = &quot;.pdata&quot;;

typedef struct _ModuleSectionInfo_T {
	VOID*	pBase;
	UINT	Size;
}ModuleSectionInfo_T;

// 查找 .pdata 段地址和大小
BOOL getModulePdataSection(
    __in HANDLE hProcess, 
    __in VOID * pModule, 
    __out ModuleSectionInfo_T * pModuleSectionInfo)
{
	IMAGE_DOS_HEADER		ImageDosHeader;
	IMAGE_NT_HEADERS		ImageNtHeaders;
	IMAGE_SECTION_HEADER*	pImageSectionHeader;
	UINT					SectionIdx;
	IMAGE_SECTION_HEADER	ImageSectionHeader;
	UCHAR*					pBase = (UCHAR*)pModule;
	BOOL					bResult = FALSE;

	if (!ReadProcessMemory(hProcess, pBase, &amp;ImageDosHeader, sizeof(ImageDosHeader), NULL)) goto End;
	if (ImageDosHeader.e_magic != IMAGE_DOS_SIGNATURE) goto End;
	if (!ReadProcessMemory(hProcess, pBase + ImageDosHeader.e_lfanew, &amp;ImageNtHeaders, sizeof(ImageNtHeaders), NULL)) goto End;
	if (ImageNtHeaders.Signature != IMAGE_NT_SIGNATURE) goto End;
	//
	// For 64bits, add the size of IMAGE_NT_HEADERS64 to its own base to get the base of the IMAGE_SECTION_HEADER table
	//
#ifdef _WIN64
#pragma warning(push)
#pragma warning(disable:4127)
	if (SQLPLUGIN_IS_WOW64 == TRUE) pImageSectionHeader = (IMAGE_SECTION_HEADER*)((UINT_PTR)pBase + ImageDosHeader.e_lfanew + sizeof(IMAGE_NT_HEADERS));
#pragma warning(pop)
	else
#endif		
		pImageSectionHeader = (IMAGE_SECTION_HEADER*)((UINT_PTR)pBase + ImageDosHeader.e_lfanew + sizeof(IMAGE_NT_HEADERS32));

	for (SectionIdx = 0; SectionIdx &lt; ImageNtHeaders.FileHeader.NumberOfSections; SectionIdx++)
	{
		if (!ReadProcessMemory(hProcess, &amp;pImageSectionHeader[SectionIdx], &amp;ImageSectionHeader, sizeof(ImageSectionHeader), NULL)) goto End;
		const char* SectionName = (const char*)ImageSectionHeader.Name;
		if (strncmp(SectionName, gPDataSectionName, sizeof(gPDataSectionName)) == 0)
		{
			pModuleSectionInfo-&gt;pBase = pBase + ImageSectionHeader.VirtualAddress;
			pModuleSectionInfo-&gt;Size = ImageSectionHeader.Misc.VirtualSize;
			bResult = TRUE;
			break;
		}
	}
End:
	return (bResult);
}


BOOL getFunWithSepAddr(MODULEENTRY32 me32, ULONGLONG InputAddr, ULONGLONG&amp; RetAddr)
{
	BOOL bRet = FALSE;
	ModuleSectionInfo_T ModuleSectionInfo;
	ULONGLONG ulModuleBase = (ULONGLONG)me32.modBaseAddr;
	ULONGLONG ulModuleSize = (ULONGLONG)me32.modBaseSize;

	if (!getModulePdataSection(m_hProcess, me32.hModule, &amp;ModuleSectionInfo)) goto End;

	PVOID								pCandidate;
	IMAGE_IA64_RUNTIME_FUNCTION_ENTRY	RuntimeEntry;

#pragma warning(push)
#pragma warning(disable:4305)
	pCandidate = ModuleSectionInfo.pBase;
#pragma warning(pop)
	unsigned int iCount = 0;

    // 这里遍历的就是 SEH 表
	for (iCount = 0; iCount &lt; ModuleSectionInfo.Size; iCount += sizeof(IMAGE_IA64_RUNTIME_FUNCTION_ENTRY))
	{
		if (!ReadProcessMemory(m_hProcess, pCandidate, &amp;RuntimeEntry, sizeof(IMAGE_IA64_RUNTIME_FUNCTION_ENTRY), NULL))	goto NextCandidate;

		ULONGLONG begin = (ULONGLONG)ulModuleBase + RuntimeEntry.BeginAddress;
		ULONGLONG end = (ULONGLONG)ulModuleBase + RuntimeEntry.EndAddress;

		if (IsInThisFun(iCount, InputAddr, begin, end))
		{
			bRet = TRUE;
			RetAddr = begin;
			break;
		}

	NextCandidate:
		pCandidate = (PVOID)((ULONGLONG)pCandidate + sizeof(IMAGE_IA64_RUNTIME_FUNCTION_ENTRY));
	}
End:
	return bRet;
}

wiki/windows驱动开发教程/0-开发相关api整理.content:
概述 驱动开发 过程中，相关 API 的学习整理



      本文部分内容由 AI 生成，经人工修订。 

[toc]
链表
定义链表结构体
Cctypedef struct
{
	DWORD Pid;
	UCHAR ProcessName[2048];
	DWORD Handle;
	LIST_ENTRY ListEntry;
} ProcessList;
初始化 InitializeListHead
CcLIST_ENTRY linkListHead;

// 初始化链表头部
InitializeListHead(&amp;linkListHead);
插入链表 InsertTailList
CcpData = (ProcessList*)ExAllocatePool(PagedPool, sizeof(ProcessList));

InsertTailList(&amp;linkListHead, &amp;pData-&gt;ListEntry);
判断是否为空 IsListEmpty
Ccif(!IsListEmpty(&amp;linkListHead))
{
    DbgPrint(&quot;Empty&quot;);
}
移除链表 RemoveHeadList
CcLIST_ENTRY* pEntry = RemoveHeadList(&amp;linkListHead);
获取链表当中的结构
CcpData = CONTAINING_RECORD(pEntry, ProcessList, ListEntry);
DbgPrint(&quot;Pid[%d], ProcessName[%s], Handle[0x%x] \n&quot;, pData-&gt;Pid, pData-&gt;ProcessName, pData-&gt;Handle);
安装卸载相关
WdfDriverCreate
WdfDriverCreate 是 Windows Driver Frameworks (WDF) 中用于创建驱动程序的函数。它用于初始化驱动程序，并将其与 Windows 操作系统进行集成。
WdfDriverCreate 函数需要填写一个 WDFDRIVER 结构体来定义驱动程序的属性和行为。以下是一些常见的参数：

DriverName: 驱动程序的名称，用于在调试和日志记录中标识驱动程序。
DriverVersion: 驱动程序的版本号，用于标识驱动程序的版本。
DeviceAddVersion: 用于添加新设备的 WDF 函数版本。
DriverUnload: 驱动程序卸载时的回调函数，用于清理资源并执行其他必要的操作。
DispatchTable: 一个包含驱动程序处理 IRP 请求的回调函数的表。
RegistryPath: 驱动程序在注册表中的路径，用于存储配置信息和设置。

WdfDeviceCreate
WdfDeviceCreate 是 Windows Driver Frameworks (WDF) 中的一个函数，用于创建设备对象并初始化与设备相关的数据结构。它是 WDF 中非常重要和常用的函数之一。
WdfDeviceCreate 函数需要填写一个 WDFDEVICE_INIT 结构体来定义设备的属性和行为。以下是一些常见的参数：


Driver: 指向驱动程序的指针，用于关联设备和驱动程序。


DeviceAttributes: 指向调用方分配的 WDF_OBJECT_ATTRIBUTES 结构的指针，该结构包含新设备的属性。


StackSize: 设备的堆栈大小，用于定义设备对象的执行环境。


DeviceInit: 指向 WDFDEVICE_INIT 结构的指针的地址，用于初始化设备的状态和行为。


在调用 WdfDeviceCreate 之后，WDF 将使用提供的参数来创建并初始化一个设备对象。然后，设备可以使用 WDF 提供的其他函数来管理设备的状态、处理请求以及与其他设备或驱动程序进行交互。
需要注意的是，WdfDeviceCreate 是一个高级别的函数，通常用于创建完整的设备对象。对于较简单的设备或需要更精细控制的情况，可能需要使用其他 WDF 函数来手动创建和配置设备对象。同时，在使用 WdfDeviceCreate 和其他 WDF 函数时，应注意遵循正确的使用方法和规范，以避免产生潜在的问题和风险。
实用函数
绕过签名检查
Cc// 绕过签名检查
BOOLEAN BypassCheckSign(PDRIVER_OBJECT pDriverObject)
{
#ifdef _WIN64
	typedef struct _KLDR_DATA_TABLE_ENTRY
	{
		LIST_ENTRY listEntry;
		ULONG64 __Undefined1;
		ULONG64 __Undefined2;
		ULONG64 __Undefined3;
		ULONG64 NonPagedDebugInfo;
		ULONG64 DllBase;
		ULONG64 EntryPoint;
		ULONG SizeOfImage;
		UNICODE_STRING path;
		UNICODE_STRING name;
		ULONG   Flags;
		USHORT  LoadCount;
		USHORT  __Undefined5;
		ULONG64 __Undefined6;
		ULONG   CheckSum;
		ULONG   __padding1;
		ULONG   TimeDateStamp;
		ULONG   __padding2;
	} KLDR_DATA_TABLE_ENTRY, * PKLDR_DATA_TABLE_ENTRY;
#else
	typedef struct _KLDR_DATA_TABLE_ENTRY
	{
		LIST_ENTRY listEntry;
		ULONG unknown1;
		ULONG unknown2;
		ULONG unknown3;
		ULONG unknown4;
		ULONG unknown5;
		ULONG unknown6;
		ULONG unknown7;
		UNICODE_STRING path;
		UNICODE_STRING name;
		ULONG   Flags;
	} KLDR_DATA_TABLE_ENTRY, * PKLDR_DATA_TABLE_ENTRY;
#endif

	PKLDR_DATA_TABLE_ENTRY pLdrData = (PKLDR_DATA_TABLE_ENTRY)pDriverObject-&gt;DriverSection;
	pLdrData-&gt;Flags = pLdrData-&gt;Flags | 0x20;

	return TRUE;
}
如何使用
Cc// 驱动入口地址
NTSTATUS DriverEntry(IN PDRIVER_OBJECT Driver, PUNICODE_STRING RegistryPath)
{
	if (BypassCheckSign(Driver))
		DbgPrint(&quot;Bypass Sign Success.&quot;);

	DbgPrint(&quot;Driver loaded. \n&quot;);

	Driver-&gt;DriverUnload = UnDriver;
	return STATUS_SUCCESS;
}
内存相关
申请内存 ExAllocatePool
申请内存使用 ExAllocatePool 、ExAllocatePoolWithTag、ExAllocatePool2 接口
原型
CcPVOID ExAllocatePool(
  IN POOL_TYPE PoolType,
  IN SIZE_T NumberOfBytes
);

PoolType：指定内存池的类型，可以是 NonPagedPool（非分页内存池）或 PagedPool（分页内存池）等。
NumberOfBytes：指定要分配的内存大小，最好是 4 的倍数。
返回值：返回分配的内存地址，一定是内核模式地址。如果返回 NULL，则代表分配失败。

ExAllocatePool 与 ExAllocatePool2/ExAllocatePool3
从 Windows 10 版本 2004 开始，推荐使用 ExAllocatePool2 和 ExAllocatePool3 来替代 ExAllocatePool。新的 API 默认会将分配的内存初始化为零，有助于避免内存泄漏相关的 bug。
示例代码
CcPVOID Allocation = ExAllocatePool(PagedPool, 100);
if (Allocation == NULL) {
    // 处理内存分配失败的情况
} else {
    // 使用分配的内存
}
在新的驱动中，应该使用 ExAllocatePool2 接口
CcPVOID Allocation = ExAllocatePool2(POOL_FLAG_PAGED, 100, &#039;abcd&#039;);
if (Allocation == NULL) {
    // 处理内存分配失败的情况
} else {
    // 使用分配的内存
}
填充内存 RtlZeroMemory
Cc// 分配内核堆空间
pData = (ProcessList*)ExAllocatePool(PagedPool, sizeof(ProcessList));
RtlZeroMemory(pData, sizeof(ProcessList));
拷贝内存 RtlCopyMemory
Cc// 设置变量
pData-&gt;Pid = (DWORD)PsGetProcessId(eproc);
RtlCopyMemory(pData-&gt;ProcessName, PsGetProcessImageFileName(eproc), strlen(PsGetProcessImageFileName(eproc)));
pData-&gt;Handle = (DWORD)PsGetProcessInheritedFromUniqueProcessId(eproc);
释放内存 ExFreePool
CcExFreePool(pData);
进程相关
Cc#include &lt;windef.h&gt;

// 函数返回给定进程的进程环境块（Process Environment Block，PEB）的指针
extern PVOID PsGetProcessPeb(_In_ PEPROCESS Process); 

// 此函数通过给定的进程 ID 查找对应的进程，并将进程的 EPROCESS 结构指针存储在提供的指针变量中。
NTKERNELAPI NTSTATUS PsLookupProcessByProcessId(HANDLE ProcessId, PEPROCESS* Process); 

// 此函数返回给定进程的 Wow64 进程环境的指针。Wow64 进程环境是用于在 64 位 Windows 上运行 32 位应用程序的兼容性层。
extern NTKERNELAPI PVOID PsGetProcessWow64Process(_In_ PEPROCESS Process); 

// 此函数返回给定进程的映像文件名，即执行该进程的可执行文件的名称。
extern NTKERNELAPI UCHAR* PsGetProcessImageFileName(IN PEPROCESS Process); 

//  此函数返回给定进程所继承的唯一进程 ID, 即父进程 ID。
extern NTKERNELAPI HANDLE PsGetProcessInheritedFromUniqueProcessId(IN PEPROCESS Process);
宏
alloc_text
这段代码是 Windows内核驱动开发（特别是使用 WDF — Windows Driver Framework，如 KMDF 或 UMDF）中常见的 内存分页控制指令，用于指定函数应被放置在可分页内存（PAGE 段）还是非分页内存（INIT 或默认代码段）中。

📌 代码解析
Cc#ifdef ALLOC_PRAGMA
#pragma alloc_text (PAGE, EchoDeviceCreate)
#pragma alloc_text (PAGE, EchoEvtDeviceSelfManagedIoSuspend)
#endif
1. #ifdef ALLOC_PRAGMA

这是一个 条件编译宏。
ALLOC_PRAGMA 通常由驱动项目在需要显式控制函数内存属性时定义（例如在源文件开头或通过编译器选项）。
如果未定义 ALLOC_PRAGMA，这些 #pragma 指令将被忽略，函数按编译器默认方式分配（通常是可分页的，但不保证）。


💡 为什么用条件编译？
有些构建环境（如静态分析、特定平台）可能不支持 #pragma alloc_text，或开发者希望在调试/发布版本中灵活控制。通过宏开关，可以统一管理。


2. alloc_text
PAGE 段
#pragma alloc_text(PAGE, FunctionName):

这是 Microsoft 编译器（MSVC）特有的 pragma 指令。
作用：将指定函数的代码放入名为 PAGE 的内存段中。
PAGE 段 = 可分页内存（Paged Memory）：

系统内存紧张时，该段代码可被换出到磁盘（pagefile.sys）。
只能在 IRQL &lt;= APC_LEVEL（通常是 PASSIVE_LEVEL）时调用。
适用于 不会在高 IRQL（如 DISPATCH_LEVEL）或 DPC/ISR 中执行的函数。



编译后的可行文件逆向结果如下所示，可见 EchoDeviceCreate 函数是直接保存在普通函数区的，并且该函数所使用字符串等都会被编译到当前页：


INIT 段
#pragma alloc_text(INIT, DriverEntry):

INIT 段 = 可分页且可丢弃（Discardable）
驱动加载完成后（即 DriverEntry 执行完毕），操作系统会 自动释放整个 INIT 段，回收物理内存。
只能在 IRQL = PASSIVE_LEVEL 调用（DriverEntry 正是在此 IRQL 下执行）。
适用场景：仅在驱动加载阶段运行一次的初始化代码。

💡 为什么放这里？

DriverEntry 是驱动入口点，只在驱动加载时调用一次。
放入 INIT 可减少驱动常驻内存占用，符合 Windows 驱动最佳实践。


⚠️ 错误示例：如果某个 INIT 段函数在驱动加载后被再次调用，会导致 Page Fault / BugCheck（蓝屏）！

对比





























内存段是否可分页安全调用 IRQL典型用途PAGE✅ 是≤ APC_LEVEL（通常 PASSIVE_LEVEL）设备创建、初始化、清理、IOCTL 处理等（默认 / 无标记）❌ 否（非分页）≤ DISPATCH_LEVELDPC、中断处理、CompletionRoutine 等INIT✅ 是（且驱动加载后可释放）≤ APC_LEVELDriverEntry、AddDevice 等仅在加载时运行的函数

⚠️ 错误示例：若将 DPC 回调函数放在 PAGE 段，在内存分页时触发 DPC 会导致 BugCheck（蓝屏），因为系统无法在高 IRQL 访问分页内存。

🛠 开发建议

始终确认函数调用上下文的 IRQL
使用 Static Driver Verifier (SDV) 或 Code Analysis 检查 IRQL 与内存段匹配性。
不要将 PAGE 函数用于以下场景：

DPC / Timer callbacks
Interrupt Service Routines (ISR)
Completion routines（除非明确在 PASSIVE_LEVEL）
Any code path called at IRQL ≥ DISPATCH_LEVEL


INIT 函数必须满足：

仅在驱动加载期间调用
不被任何非-INIT 函数引用（否则链接器可能报错或导致运行时崩溃）


现代 WDF 驱动中：

大多数事件回调（EvtDeviceAdd, EvtIoRead, EvtDeviceD0Entry 等）默认可安全放入 PAGE。
只有涉及硬件中断、DPC、自旋锁保护的代码才需放在非分页段（默认段）。

wiki/windows驱动开发教程/10-驱动开发通用模版.content:
概述驱动开发通用模板
参考文章：驱动开发：应用DeviceIoContro开发模板 | LyShark®


模板说明
内核中执行代码后需要将结果动态显示给应用层的用户，DeviceIoControl 是直接发送控制代码到指定的设备驱动程序，使相应的移动设备以执行相应的操作的函数，如下代码是一个经典的驱动开发模板框架，在开发经典驱动时会用到的一个通用案例。
如下这段案例中，我们只介绍DispatchIoctl，该函数主要用于接收或发送IOCTL控制信号，以此来实现接收和发送数据。
首先，通过调用IoGetCurrentIrpStackLocation函数获取IRP（I/O Request Packet）的堆栈位置，并获取控制码、输入和输出缓冲区的相关信息。
然后，根据不同的控制信号码，进行相应的处理流程。这里的示例代码只列出了一个控制信号码（IOCTL_IO_LyShark）的处理流程，即接收传入数据，进行处理后返回传出数据。
最后，根据处理结果，设置IRP的状态和返回信息，并通过调用IoCompleteRequest函数完成IRP的处理。
需要注意的是，这段代码中没有对错误情况进行处理，如果出现错误，返回的状态码为STATUS_INVALID_DEVICE_REQUEST。因此，实际使用中需要根据具体情况进行修改和完善。
如下所示，为驱动开发通用模板：
Cc#include &lt;ntifs.h&gt;
#include &lt;windef.h&gt;

// 控制器
#define IOCTL_IO_LyShark CTL_CODE(FILE_DEVICE_UNKNOWN,0x800,METHOD_BUFFERED,FILE_ANY_ACCESS)

// 卸载驱动执行
VOID UnDriver(PDRIVER_OBJECT pDriver)
{
	PDEVICE_OBJECT pDev;                                        // 用来取得要删除设备对象
	UNICODE_STRING SymLinkName;                                 // 局部变量symLinkName
	pDev = pDriver-&gt;DeviceObject;
	IoDeleteDevice(pDev);                                       // 调用IoDeleteDevice用于删除设备
	RtlInitUnicodeString(&amp;SymLinkName, L&quot;\\??\\My_Driver&quot;);     // 初始化字符串将symLinkName定义成需要删除的符号链接名称
	IoDeleteSymbolicLink(&amp;SymLinkName);                         // 调用IoDeleteSymbolicLink删除符号链接
	DbgPrint(&quot;驱动卸载完毕...&quot;);
}

// 创建设备连接
NTSTATUS CreateDriverObject(IN PDRIVER_OBJECT pDriver)
{
	NTSTATUS Status;
	PDEVICE_OBJECT pDevObj;
	UNICODE_STRING DriverName;
	UNICODE_STRING SymLinkName;

	// 创建设备名称字符串
	RtlInitUnicodeString(&amp;DriverName, L&quot;\\Device\\My_Driver&quot;);
	Status = IoCreateDevice(pDriver, 0, &amp;DriverName, FILE_DEVICE_UNKNOWN, 0, TRUE, &amp;pDevObj);

	// 指定通信方式为缓冲区
	pDevObj-&gt;Flags |= DO_BUFFERED_IO;

	// 创建符号链接
	RtlInitUnicodeString(&amp;SymLinkName, L&quot;\\??\\My_Driver&quot;);
	Status = IoCreateSymbolicLink(&amp;SymLinkName, &amp;DriverName);
	return STATUS_SUCCESS;
}

// 创建回调函数
NTSTATUS DispatchCreate(PDEVICE_OBJECT pDevObj, PIRP pIrp)
{
	pIrp-&gt;IoStatus.Status = STATUS_SUCCESS;          // 返回成功
	DbgPrint(&quot;派遣函数 IRP_MJ_CREATE 执行 \n&quot;);
	IoCompleteRequest(pIrp, IO_NO_INCREMENT);        // 指示完成此IRP
	return STATUS_SUCCESS;                           // 返回成功
}

// 关闭回调函数
NTSTATUS DispatchClose(PDEVICE_OBJECT pDevObj, PIRP pIrp)
{
	pIrp-&gt;IoStatus.Status = STATUS_SUCCESS;          // 返回成功
	DbgPrint(&quot;派遣函数 IRP_MJ_CLOSE 执行 \n&quot;);
	IoCompleteRequest(pIrp, IO_NO_INCREMENT);        // 指示完成此IRP
	return STATUS_SUCCESS;                           // 返回成功
}

// 主控制器,用于判断R3发送的控制信号
NTSTATUS DispatchIoctl(PDEVICE_OBJECT pDevObj, PIRP pIrp)
{
	NTSTATUS status = STATUS_INVALID_DEVICE_REQUEST;
	PIO_STACK_LOCATION pIrpStack;
	ULONG uIoControlCode;
	PVOID pIoBuffer;
	ULONG uInSize;
	ULONG uOutSize;

	// 获得IRP里的关键数据
	pIrpStack = IoGetCurrentIrpStackLocation(pIrp);

	// 获取控制码
	uIoControlCode = pIrpStack-&gt;Parameters.DeviceIoControl.IoControlCode;

	// 输入和输出的缓冲区（DeviceIoControl的InBuffer和OutBuffer都是它）
	pIoBuffer = pIrp-&gt;AssociatedIrp.SystemBuffer;

	// EXE发送传入数据的BUFFER长度（DeviceIoControl的nInBufferSize）
	uInSize = pIrpStack-&gt;Parameters.DeviceIoControl.InputBufferLength;

	// EXE接收传出数据的BUFFER长度（DeviceIoControl的nOutBufferSize）
	uOutSize = pIrpStack-&gt;Parameters.DeviceIoControl.OutputBufferLength;

	// 对不同控制信号的处理流程
	switch (uIoControlCode)
	{
		// 接收或发送
	case IOCTL_IO_LyShark:
	{
		DWORD dw = 0;

		// 得到输入参数
		memcpy(&amp;dw, pIoBuffer, sizeof(DWORD));

		DbgPrint(&quot;[+] hello lyshark \n&quot;);

		// 对输入参数进行处理
		dw++;

		// 设置输出参数
		memcpy(pIoBuffer, &amp;dw, sizeof(DWORD));

		// 返回通信状态
		status = STATUS_SUCCESS;
		break;
	}

	pIrp-&gt;IoStatus.Status = status;
	pIrp-&gt;IoStatus.Information = uOutSize;
	IoCompleteRequest(pIrp, IO_NO_INCREMENT);
	return status;
	}

	// 设定DeviceIoControl的*lpBytesReturned的值（如果通信失败则返回0长度）
	if (status == STATUS_SUCCESS)
		pIrp-&gt;IoStatus.Information = uOutSize;
	else
		pIrp-&gt;IoStatus.Information = 0;

	// 设定DeviceIoControl的返回值是成功还是失败
	pIrp-&gt;IoStatus.Status = status;
	IoCompleteRequest(pIrp, IO_NO_INCREMENT);
	return status;
}

// 入口函数
NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING RegistryPath)
{
	// 调用创建设备
	CreateDriverObject(pDriver);

	pDriver-&gt;DriverUnload = UnDriver;                               // 卸载函数
	pDriver-&gt;MajorFunction[IRP_MJ_CREATE] = DispatchCreate;         // 创建派遣函数
	pDriver-&gt;MajorFunction[IRP_MJ_CLOSE] = DispatchClose;           // 关闭派遣函数
	pDriver-&gt;MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchIoctl;  // 分发函数

	DbgPrint(&quot;By:LyShark ...&quot;);

	return STATUS_SUCCESS;
}

