【驱动学习】1-开发准备(VS2022)|驱动开发：测试模式过DSE签名 | LyShark®
新生吃老饭之无签驱动的两种加载方式 - FreeBuf网络安全行业门户



DSE
Windows DSE（Driver Signature Enforcement）机制是微软Windows操作系统中的一项关键安全特性，旨在确保只有经过验证和签名的驱动程序才能被加载到系统中。以下是DSE机制的主要功能和特点：


安全性和验证：DSE的主要目的是保护操作系统免受恶意或不稳定的驱动程序影响。通过确保所有加载的驱动程序都经过签名验证，DSE帮助防止恶意代码和不安全的软件干扰系统操作。


数字签名：驱动程序需要使用有效的数字证书进行签名。数字签名通过公钥加密技术保证驱动程序的来源和完整性。签名证书由受信任的证书颁发机构颁发，证书包含开发者的公钥以及CA的签名信息。


内核模式驱动程序加载：Windows操作系统内核模式下的驱动程序需要经过DSE的验证过程，以确保其签名有效。如果签名有效，系统会允许驱动程序加载，并将其映射到内核空间；如果签名无效，系统会阻止驱动程序加载，并提供错误信息给用户或管理员。


代码完整性检查：DSE还包括代码完整性检查，用于确保驱动程序在加载时没有被篡改。驱动程序的哈希值（如SHA256）会与签名中的哈希值进行比对，以确保驱动程序的内容与签名时的一致性。


Secure Boot配合：DSE可以与Secure Boot配合使用，进一步提升系统的安全性。Secure Boot确保在启动阶段仅允许经过认证的操作系统和驱动程序加载，防止未授权的代码在启动阶段运行。


DSE运行模式：在强制模式下，DSE确保所有驱动程序都经过数字签名。这是Windows的默认设置，从Vista及后续版本开始就已经启用。在测试模式下，DSE允许加载未签名的驱动程序，主要用于开发和测试阶段。


用户和管理员控制：用户可以通过高级启动选项临时禁用DSE，以便安装或测试未签名的驱动程序。在企业环境或特殊需求下，管理员可以通过组策略或注册表设置来永久禁用DSE，但这种做法会降低系统的安全性。


政策管理：在企业环境中，IT管理员可以使用组策略配置和管理DSE设置，确保符合组织的安全和合规要求。


DSE机制通过这些方式确保了系统中运行的所有驱动程序都经过认证，降低了潜在的安全风险，提高了系统的稳定性和安全性。
ByPass
仅限于在 Windows 测试模式下使用这种方式，通过修改 PKLDR_DATA_TABLE_ENTRY.Flags 来达到测试模式下需要验签的问题。
更改 _KLDR_DATA_TABLE_ENTRY 的 FLAGS， pLdrData-&gt;data | 0x20 置位。
相关代码如下所示：
Cc// 绕过签名检查
BOOLEAN BypassCheckSign(PDRIVER_OBJECT pDriverObject)
{
#ifdef _WIN64
	typedef struct _KLDR_DATA_TABLE_ENTRY
	{
		LIST_ENTRY listEntry;
		ULONG64 __Undefined1;
		ULONG64 __Undefined2;
		ULONG64 __Undefined3;
		ULONG64 NonPagedDebugInfo;
		ULONG64 DllBase;
		ULONG64 EntryPoint;
		ULONG SizeOfImage;
		UNICODE_STRING path;
		UNICODE_STRING name;
		ULONG   Flags;
		USHORT  LoadCount;
		USHORT  __Undefined5;
		ULONG64 __Undefined6;
		ULONG   CheckSum;
		ULONG   __padding1;
		ULONG   TimeDateStamp;
		ULONG   __padding2;
	} KLDR_DATA_TABLE_ENTRY, * PKLDR_DATA_TABLE_ENTRY;
#else
	typedef struct _KLDR_DATA_TABLE_ENTRY
	{
		LIST_ENTRY listEntry;
		ULONG unknown1;
		ULONG unknown2;
		ULONG unknown3;
		ULONG unknown4;
		ULONG unknown5;
		ULONG unknown6;
		ULONG unknown7;
		UNICODE_STRING path;
		UNICODE_STRING name;
		ULONG   Flags;
	} KLDR_DATA_TABLE_ENTRY, * PKLDR_DATA_TABLE_ENTRY;
#endif

	PKLDR_DATA_TABLE_ENTRY pLdrData = (PKLDR_DATA_TABLE_ENTRY)pDriverObject-&gt;DriverSection;
	pLdrData-&gt;Flags = pLdrData-&gt;Flags | 0x20;

	return TRUE;
}
如何使用
Cc// 驱动入口地址
NTSTATUS DriverEntry(IN PDRIVER_OBJECT Driver, PUNICODE_STRING RegistryPath)
{
	if (BypassCheckSign(Driver))
		DbgPrint(&quot;Bypass Sign Success.&quot;);

	Driver-&gt;DriverUnload = UnloadDriver;
	return STATUS_SUCCESS;
}

wiki/windows驱动开发教程/4-内核下遍历系统当前进程.content:
概述：内核模式下遍历系统当前进程，以及链表的基本使用


相关接口
进程相关
相关知识点
PID
PID 一定是4的整数倍



                  为什么 PID 一定是4的整数倍 



Windows进程的PID（Process ID）是4的倍数的原因与Windows内核中句柄分配机制有关。以下是详细的解释：


句柄分配机制：在Windows NT内核的操作系统中，进程ID（PID）和线程ID（TID）实际上是基于全局的句柄表PspCidTable生成的，这个表也被称为CID句柄表（Client ID handle table）。这个句柄表中的每个项都包含了进程或线程的对象地址。


句柄值与索引：在Windows中，句柄值是用来检索句柄表的一个“伪索引”。由于句柄值的低2位被用作标志位，因此它们对于作为句柄表索引本身没有意义。这意味着句柄值实际上是4的倍数，因为每4个字节对应一个句柄索引值。


内核句柄重用：分配内核句柄的相同代码也用于分配进程和线程ID。由于内核句柄是4的倍数，因此进程和线程ID也是如此。这是一个实现细节，因此不应编写依赖于这个规律的代码。


结构定义：在Windows内核中，句柄类型是由EXHANDLE结构定义的，其中包含一个ULONG值，用于存储索引。由于低2位被用作标志位，所以有效的索引从第3位开始，这就是为什么句柄值（以及由此产生的PID和TID）是4的倍数的原因。


历史和兼容性：这个机制在Windows的多个版本中一直保持不变，主要是因为底层代码难以改变。即使在最新的Windows版本中，这个规律依然存在。


总结来说，Windows进程PID是4的倍数是由于内核中句柄分配机制的设计，特别是与句柄值的位结构和内核句柄重用代码有关。这是一个实现细节，不应该依赖于应用程序开发中。


完整代码
Cc#include &lt;ntifs.h&gt;
#include &lt;windef.h&gt;

extern PVOID PsGetProcessPeb(_In_ PEPROCESS Process); // 函数返回给定进程的进程环境块（Process Environment Block，PEB）的指针
NTKERNELAPI NTSTATUS PsLookupProcessByProcessId(HANDLE ProcessId, PEPROCESS* Process); // 此函数通过给定的进程 ID 查找对应的进程，并将进程的 EPROCESS 结构指针存储在提供的指针变量中。
extern NTKERNELAPI PVOID PsGetProcessWow64Process(_In_ PEPROCESS Process); // 此函数返回给定进程的 Wow64 进程环境的指针。Wow64 进程环境是用于在 64 位 Windows 上运行 32 位应用程序的兼容性层。
extern NTKERNELAPI UCHAR* PsGetProcessImageFileName(IN PEPROCESS Process); // 此函数返回给定进程的映像文件名，即执行该进程的可执行文件的名称。
extern NTKERNELAPI HANDLE PsGetProcessInheritedFromUniqueProcessId(IN PEPROCESS Process); //  此函数返回给定进程所继承的唯一进程 ID,即父进程ID。

typedef struct
{
	DWORD Pid;
	UCHAR ProcessName[2048];
	DWORD Handle;
	LIST_ENTRY ListEntry;
} ProcessList;

// 根据进程ID返回进程EPROCESS结构体失败返回NULL
PEPROCESS LookupProcess(HANDLE Pid)
{
	PEPROCESS eprocess = NULL;
	NTSTATUS Status = STATUS_UNSUCCESSFUL;
	Status = PsLookupProcessByProcessId(Pid, &amp;eprocess);
	if (NT_SUCCESS(Status))
	{
		return eprocess;
	}
	return NULL;
}

// 内核链表操作
BOOLEAN GetAllProcess()
{
	PEPROCESS eproc = NULL;
	LIST_ENTRY linkListHead;

	// 初始化链表头部
	InitializeListHead(&amp;linkListHead);
	ProcessList* pData = NULL;

	for (int temp = 0; temp &lt; 100000; temp += 4) // pid 一定是4的整数倍
	{
		eproc = LookupProcess((HANDLE)temp);
		if (eproc != NULL)
		{
			STRING nowProcessnameString = { 0 };
			RtlInitString(&amp;nowProcessnameString, PsGetProcessImageFileName(eproc));

			// 分配内核堆空间
			pData = (ProcessList*)ExAllocatePool(PagedPool, sizeof(ProcessList));
			RtlZeroMemory(pData, sizeof(ProcessList));

			// 设置变量
			pData-&gt;Pid = (DWORD)PsGetProcessId(eproc);
			RtlCopyMemory(pData-&gt;ProcessName, PsGetProcessImageFileName(eproc), strlen(PsGetProcessImageFileName(eproc)));
			pData-&gt;Handle = (DWORD)PsGetProcessInheritedFromUniqueProcessId(eproc);

			// 插入元素
			InsertTailList(&amp;linkListHead, &amp;pData-&gt;ListEntry);
			ObDereferenceObject(eproc); // 内核对象引用计数+1
		}
	}

	// 输出链表内的数据
	while (!IsListEmpty(&amp;linkListHead))
	{
		LIST_ENTRY* pEntry = RemoveHeadList(&amp;linkListHead);
		pData = CONTAINING_RECORD(pEntry, ProcessList, ListEntry);

		DbgPrint(&quot;Pid[%d], ProcessName[%s], Handle[0x%x] \n&quot;, pData-&gt;Pid, pData-&gt;ProcessName, pData-&gt;Handle);
		ExFreePool(pData);
	}
	return TRUE;
}

// 绕过签名检查
BOOLEAN BypassCheckSign(PDRIVER_OBJECT pDriverObject)
{
#ifdef _WIN64
	typedef struct _KLDR_DATA_TABLE_ENTRY
	{
		LIST_ENTRY listEntry;
		ULONG64 __Undefined1;
		ULONG64 __Undefined2;
		ULONG64 __Undefined3;
		ULONG64 NonPagedDebugInfo;
		ULONG64 DllBase;
		ULONG64 EntryPoint;
		ULONG SizeOfImage;
		UNICODE_STRING path;
		UNICODE_STRING name;
		ULONG   Flags;
		USHORT  LoadCount;
		USHORT  __Undefined5;
		ULONG64 __Undefined6;
		ULONG   CheckSum;
		ULONG   __padding1;
		ULONG   TimeDateStamp;
		ULONG   __padding2;
	} KLDR_DATA_TABLE_ENTRY, * PKLDR_DATA_TABLE_ENTRY;
#else
	typedef struct _KLDR_DATA_TABLE_ENTRY
	{
		LIST_ENTRY listEntry;
		ULONG unknown1;
		ULONG unknown2;
		ULONG unknown3;
		ULONG unknown4;
		ULONG unknown5;
		ULONG unknown6;
		ULONG unknown7;
		UNICODE_STRING path;
		UNICODE_STRING name;
		ULONG   Flags;
	} KLDR_DATA_TABLE_ENTRY, * PKLDR_DATA_TABLE_ENTRY;
#endif

	PKLDR_DATA_TABLE_ENTRY pLdrData = (PKLDR_DATA_TABLE_ENTRY)pDriverObject-&gt;DriverSection;
	pLdrData-&gt;Flags = pLdrData-&gt;Flags | 0x20;

	return TRUE;
}



// 卸载驱动
void UnloadDriver(PDRIVER_OBJECT driver)
{
	DbgPrint(&quot;Uninstall Driver Is Ok \n&quot;);
}

// 驱动入口地址
NTSTATUS DriverEntry(IN PDRIVER_OBJECT Driver, PUNICODE_STRING RegistryPath)
{

	if (BypassCheckSign(Driver))
		DbgPrint(&quot;Bypass Sign Success.&quot;);


	DbgPrint(&quot;Driver loaded. \n&quot;);

	GetAllProcess();

	Driver-&gt;DriverUnload = UnloadDriver;
	return STATUS_SUCCESS;

}

wiki/windows驱动开发教程/4.1-内存操作及内存属性.content:
概述：Windows 内核内存操作以及内存属性的说明


内存属性
在了解自旋锁之前需要先了解下内核内存分配相关内容，相关的 API 可以参考 内存相关 一文。 这里补充下 ExAllocatePool 的参数1，也就是申请的页属性参数 POOL_TYPE：
微软官方说明：_POOL_TYPE (wdm.h) - Windows drivers | Microsoft Learn
这里主要就常用的三个进行简单说明：


NonPagedPool 非分页池，这是不可分页的系统内存。 可以从任何 IRQL 访问非分页池，但它是一种稀缺资源，驱动程序应仅在必要时进行分配。该内存不会被交换到磁盘上，并且可以直接被内核访问，适用于需要快速访问的内存，例如驱动程序的代码、中断处理程序、系统调用等。


PagePool 分页池，它是可分页的系统内存。 只能在 IRQL &lt; DISPATCH_LEVEL分配和访问分页池。


NonPagedPoolExecute
带有执行权限的非分页内存。如果是使用 NonPagedPoolExecute 申请的内存则需要留意，避免被利用。 从 Windows 8 开始，NonPagedPoolExecute 是 NonPagedPool 值的备用名称。 此值指示分配的内存是非分页且可执行的，即在此内存中启用指令执行。 若要从早期版本的 Windows 移植驱动程序，通常应将驱动程序源代码中 NonPagedPool 名称的所有或大多数实例替换为 NonPagedPoolNx。 避免将 NonPagedPool 名称的实例替换为 NonPagedPoolExecute ，除非显式需要可执行内存。 有关详细信息，请参阅 No-Execute (NX) Nonpaged Pool。


内存操作
ExAllocatePool 内存申请
RtlZeroMemory 内存初始化
RtlCopyMemory 内存拷贝
ExFreePool 内存释放
Demo1
Cc// #include &lt;ntddk.h&gt;

#include &lt;ntifs.h&gt;

typedef struct _MyStruct
{
	ULONG x;
	ULONG y;
}MyStruct, *PMyStruct;

NTSTATUS UnloadDriver(PDRIVER_OBJECT pDriver)
{
	DbgPrint(&quot;Bye, Driver\n&quot;);

	return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING pReg)
{
	DbgPrint(&quot;Hello World, Driver\n&quot;);
	DbgPrint(&quot;PDRIVER_OBJECT-&gt; [0x%08x]\n&quot;, pDriver);
	DbgPrint(&quot;PUNICODE_STRING-&gt;[%ws]\n&quot;, pReg-&gt;Buffer);

	// 1 用于分配与释放非标签内存
	PVOID buffer = ExAllocatePool(NonPagedPool, 1024);

	DbgPrint(&quot;[*] 分配内存地址=%p \n&quot;, buffer);

	if (buffer)
	{
		ExFreePool(buffer);
	}

	// 用于分配带有标签的内存
	PMyStruct pStu = (PMyStruct)ExAllocatePoolWithTag(NonPagedPoolExecute, sizeof(PMyStruct), &quot;KernelTest&quot;);

	if (pStu)
	{
		pStu-&gt;x = 100;
		pStu-&gt;y = 200;

		DbgPrint(&quot;[*] 分配内存 x = %d, y= %d&quot;, pStu-&gt;x, pStu-&gt;y);

		ExFreePoolWithTag(pStu, &quot;KernelTest&quot;);
	}

	UNICODE_STRING dst = { 0 };
	UNICODE_STRING src = RTL_CONSTANT_STRING(L&quot;Hello KernelTest&quot;);

	dst.Buffer = (PWCHAR)ExAllocatePool(NonPagedPool, src.Length);
	if (dst.Buffer == NULL)
	{
		DbgPrint(&quot;[-] 分配空间错误&quot;);
	}

	dst.Length = dst.MaximumLength = src.Length;
	RtlCopyUnicodeString(&amp;dst, &amp;src);

	DbgPrint(&quot;[*] 输出拷贝 = %wZ&quot;, dst);

	pDriver-&gt;DriverUnload = UnloadDriver;
	return STATUS_SUCCESS;
}

输出

Hello World, Driver
PDRIVER_OBJECT-&gt; [0xb0402e30]
PUNICODE_STRING-&gt;[\REGISTRY\MACHINE\SYSTEM\ControlSet001\Services\KmdfMemory]
[*] 分配内存地址=FFFFAA02B11358F0 
[*] 分配内存 x = 100, y= 200
[*] 输出拷贝 = Hello KernelTest

双向链表
双向链表的结构体如下所示：
Cctypedef struct _LIST_ENTRY
{
	struct _LIST_ENTRY* Flink; // 指向后一个节点
	struct _LIST_ENTRY* Blink; // 指向前一个节点
}LIST_ENTRY, * PLIST_ENTRY;
需要注意的是：FLink 指向后一个节点，Blink 指向前一个结点。



                  多线程访问 



需要注意的是，多线程访问同一数据结构时会存在线程同步问题，常见的使用方式就是使用锁机制进程同步。自旋锁是一种常用的锁机制，它是一种高 IRQL 锁，用于同步和独占地访问某个资源。
**自旋锁的基本思想：**当一个线程尝试获取锁时，如果锁已经被占用，则该线程不断循环（即自旋），直到锁被释放。自旋锁适用于锁的持有时间较短，且竞争者较少的情况下，可以避免进程上下文的切换和调度开销。在下一章将详细记录和说明。


Demo2
Cc// #include &lt;ntddk.h&gt;

#include &lt;ntifs.h&gt;

typedef struct _MyStruct
{
	ULONG x;
	ULONG y;
	LIST_ENTRY lpListEntry;
}MyStruct, * PMyStruct;

NTSTATUS UnloadDriver(PDRIVER_OBJECT pDriver)
{
	DbgPrint(&quot;Bye, Driver\n&quot;);

	return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING pReg)
{
	DbgPrint(&quot;Hello World, Driver\n&quot;);
	DbgPrint(&quot;PDRIVER_OBJECT-&gt; [0x%016x]\n&quot;, pDriver);
	DbgPrint(&quot;PUNICODE_STRING-&gt;[%ws]\n&quot;, pReg-&gt;Buffer);

	// 初始化头节点
	LIST_ENTRY ListHeader = { 0 };
	InitializeListHead(&amp;ListHeader);

	// 定义链表元素
	MyStruct testA = { 0 };
	MyStruct testB = { 0 };
	MyStruct testC = { 0 };

	testA.x = 10;
	testA.y = 20;

	testB.x = 100;
	testB.y = 200;

	testC.x = 1000;
	testC.y = 2000;

	// 分别插入节点到头部和尾部
	InsertHeadList(&amp;ListHeader, &amp;testA.lpListEntry);
	InsertTailList(&amp;ListHeader, &amp;testB.lpListEntry);
	InsertTailList(&amp;ListHeader, &amp;testC.lpListEntry);

	// 输出链表数据
	PLIST_ENTRY pListEntry = NULL;
	pListEntry = ListHeader.Flink;

	int i = 0;

	while (pListEntry != &amp;ListHeader)
	{
		// 计算出成员距离结构体顶部内存距离
		PMyStruct ptr = CONTAINING_RECORD(pListEntry, MyStruct, lpListEntry);
		DbgPrint(&quot;节点元素x = %d, 节点元素y = %d\n&quot;, ptr-&gt;x, ptr-&gt;y);

		if (i++ &gt; 10)
		{
			break;
		}
		// 获取下一个链表地址
		pListEntry = pListEntry-&gt;Flink;
	}

	pDriver-&gt;DriverUnload = UnloadDriver;

	return STATUS_SUCCESS;
}
驱动输出：

Hello World, Driver
PDRIVER_OBJECT-&gt; [0x00000000a78b4950]
PUNICODE_STRING-&gt;[\REGISTRY\MACHINE\SYSTEM\ControlSet001\Services\KmdfListEntry]
节点元素x = 10, 节点元素y = 20
节点元素x = 100, 节点元素y = 200
节点元素x = 1000, 节点元素y = 2000

wiki/windows驱动开发教程/5-内核自旋锁.content:
概述：Windows 内核自旋锁了解与使用。自旋锁





                  相关参考： 




【驱动学习】1-开发准备(VS2022)|驱动开发：内核中自旋锁结构 | LyShark®



内核自旋锁 KSPIN_LOCK
Windows 内核自旋锁（Spin Locks）是内核定义的、仅在内核模式下使用的同步机制，用于保护共享数据或资源免受同时访问的影响。以下是关于 Windows 内核自旋锁的一些关键信息和使用指南：


自旋锁类型：

KSPIN_LOCK：这是最常用的自旋锁类型，是一个不透明的类型，用于同步对共享资源的访问。
执行自旋锁（Executive Spin Locks）：任何类型的驱动程序都可能使用一个或多个执行自旋锁。例如，大多数文件系统使用执行自旋锁来保护文件系统驱动程序（FSD）设备扩展中的交错工作队列，该队列存储由文件系统的工作者线程回调例程和 FSD 处理的 IRP。
中断自旋锁（Interrupt Spin Locks）：每个具有 ISR（Interrupt Service Routine）的驱动程序都使用中断自旋锁来保护其 ISR 和通常从其 StartIo 和 DpcForIsr 例程调用的 SynchCritSection 例程之间共享的任何数据或硬件。



自旋锁的获取与释放：

在 IRQL（Interrupt Request Level）小于或等于 DISPATCH_LEVEL 时，驱动程序可以使用 KeAcquireInStackQueuedSpinLock 和 KeReleaseInStackQueuedSpinLock 来获取和释放自旋锁作为队列自旋锁。
对于在 IRQL 大于或等于 DISPATCH_LEVEL 的调用者，可以调用 KeAcquireSpinLockAtDpcLevel 和 KeReleaseSpinLockFromDpcLevel 以获得更好的驱动程序性能。



队列自旋锁（Queued Spin Locks）：

队列自旋锁在多处理器机器上的性能优于普通自旋锁，特别是在高争用锁的情况下。
队列自旋锁允许处理器在锁上排队，释放时，锁会传递给排队的处理器，等待的处理器在本地标志上自旋。



使用自旋锁的指南：

任何由自旋锁保护的数据或资源以及相应的自旋锁的存储必须在驻留系统空间内存（非分页池）中提供。
驱动程序必须提供其使用的任何执行自旋锁的存储。但是，设备驱动程序不需要为其中断自旋锁提供存储，除非它具有多向量 ISR 或多个 ISR。



注意事项：

使用自旋锁时需要注意避免死锁和优先级反转问题，因此在实际应用中需要谨慎使用。



如上所示为 Windows 中提供的集中自旋锁，根据特性使用在不同的场景，尤其需要注意  死锁  和  优先级反转  等问题，谨慎使用。
使用示例
Cc// #include &lt;ntddk.h&gt;

#include &lt;ntifs.h&gt;

typedef struct _MyStruct
{
	ULONG x;
	ULONG y;
	LIST_ENTRY lpListEntry;
}MyStruct, * PMyStruct;

// 定义全局链表和全局锁
LIST_ENTRY g_ListHeader;
KSPIN_LOCK g_kSpinLock;

void Init()
{
	InitializeListHead(&amp;g_ListHeader);
	KeInitializeSpinLock(&amp;g_kSpinLock);
}

void function_ins()
{
	KIRQL Irql;

	// 加锁
	KeAcquireSpinLock(&amp;g_kSpinLock, &amp;Irql);

	DbgPrint(&quot;[*] 锁内部执行 \n&quot;);

	KeReleaseSpinLock(&amp;g_kSpinLock, Irql);
}

NTSTATUS UnloadDriver(PDRIVER_OBJECT pDriver)
{
	DbgPrint(&quot;Bye, Driver\n&quot;);

	return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING pReg)
{
	DbgPrint(&quot;Hello World, Driver\n&quot;);
	DbgPrint(&quot;PDRIVER_OBJECT-&gt; [0x%08x]\n&quot;, pDriver);
	DbgPrint(&quot;PUNICODE_STRING-&gt;[%ws]\n&quot;, pReg-&gt;Buffer);

	// 初始化链表
	Init();

	// 分配链表空间
	PMyStruct pStuA = (PMyStruct)ExAllocatePool(NonPagedPoolExecute, sizeof(PMyStruct));
	PMyStruct pStuB = (PMyStruct)ExAllocatePool(NonPagedPoolExecute, sizeof(PMyStruct));

	// 赋值
	if (pStuA)
	{
		pStuA-&gt;x = 10;
		pStuA-&gt;y = 20;
	}

	if (pStuB)
	{
		pStuB-&gt;x = 100;
		pStuB-&gt;y = 200;
	}

	if (pStuA &amp;&amp; pStuB)
	{
		ExInterlockedInsertHeadList(&amp;g_ListHeader, (PLIST_ENTRY)&amp;pStuA-&gt;lpListEntry, &amp;g_kSpinLock);
		ExInterlockedInsertTailList(&amp;g_ListHeader, (PLIST_ENTRY)&amp;pStuB-&gt;lpListEntry, &amp;g_kSpinLock);
	}

	function_ins();

	int i = 0;

	// 移除节点A并放入到 remove_entry 中
	PLIST_ENTRY pRemoveEntry = ExInterlockedRemoveHeadList(&amp;pStuA-&gt;lpListEntry, &amp;g_kSpinLock);

	while (pRemoveEntry != &amp;g_ListHeader)
	{
		// 计算出成员距离结构体顶部内存距离
		PMyStruct ptr = CONTAINING_RECORD(pRemoveEntry, MyStruct, lpListEntry);
		DbgPrint(&quot;节点元素x = %d, 节点元素y = %d\n&quot;, ptr-&gt;x, ptr-&gt;y);

		if (i++ &gt; 10)
		{
			break;
		}
		// 获取下一个链表地址
		pRemoveEntry = pRemoveEntry-&gt;Flink;
	}

	pDriver-&gt;DriverUnload = UnloadDriver;

	return STATUS_SUCCESS;
}
输出：

Hello World, Driver 
PDRIVER_OBJECT-&gt; [0xfdd2fe50] 
PUNICODE_STRING-&gt; [\REGISTRY\MACHINE\SYSTEM\ControlSet001\Services\KmdfKSpinLock] 
[*] 锁内部执行 
节点元素 x = 100, 节点元素 y = 200 
Bye, Driver

wiki/windows驱动开发教程/6-内核字符串.content:
概述：内核开字符串使用





                  相关参考： 




【驱动学习】1-开发准备(VS2022)|驱动开发：内核字符串转换方法 | LyShark®




内核字符串
内核编程中主要使用的字符串有两种格式：


UNICODE_STRING
Cctypedef struct _UNICODE_STRING {
    USHORT Length;
    USHORT MaximumLength;
#ifdef MIDL_PASS
    [size_is(MaximumLength / 2), length_is((Length) / 2) ] USHORT * Buffer;
#else // MIDL_PASS
    _Field_size_bytes_part_opt_(MaximumLength, Length) PWCH   Buffer;
#endif // MIDL_PASS
} UNICODE_STRING;
typedef UNICODE_STRING *PUNICODE_STRING;
typedef const UNICODE_STRING *PCUNICODE_STRING;


ANSI_STRING
Cctypedef struct _STRING {
    USHORT Length;
    USHORT MaximumLength;
#ifdef MIDL_PASS
    [size_is(MaximumLength), length_is(Length) ]
#endif // MIDL_PASS
    _Field_size_bytes_part_opt_(MaximumLength, Length) PCHAR Buffer;
} STRING;
typedef STRING *PSTRING;
typedef STRING ANSI_STRING;


在 Windows 内核中，字符串的处理十分重要。稍有不慎就会造成系统蓝屏。因此，对于字符串的处理必须遵循严格的安全规则，以确保不会引发各种安全漏洞。
内核字符串初始化
内核开发模式下提供了多个 API 可以用于字符串初始化操作，常见的主要是：

RtlInitUnicodeString
RtlInitAnsiString

字符串转换
针对 ANSI 和 UNICODE 两种编码格式之间进行转换操作，主要的 API 是：

RtlUnicodeStringToAnsiString
RtlAnsiStringToUnicodeString

另外的就是可以使用 CHAR*、WCHAR* 来保存和操作字符串。
Demo1
需要注意的是，参考的教程直接修改内存的方式会崩溃蓝屏。修改常量区内存需要先修改内存属性才可以。这里我是在网上随便找了一个方式。
Cc// #include &lt;ntddk.h&gt;

#include &lt;ntifs.h&gt;

NTSTATUS UnloadDriver(PDRIVER_OBJECT pDriver)
{
	DbgPrint(&quot;Bye, Driver\n&quot;);

	return STATUS_SUCCESS;
}

KIRQL WPOFFx64()
{
	KIRQL irql = KeRaiseIrqlToDpcLevel();
	UINT64 cr0 = __readcr0();
	cr0 &amp;= 0xfffffffffffeffff;
	__writecr0(cr0);
	_disable();
	return irql;
}

void WPONx64(KIRQL irql)
{
	UINT64 cr0 = __readcr0();
	cr0 |= 0x10000;
	_enable();
	__writecr0(cr0);
	KeLowerIrql(irql);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING pReg)
{
	DbgPrint(&quot;Hello World, Driver\n&quot;);
	DbgPrint(&quot;PDRIVER_OBJECT-&gt; [0x%08x]\n&quot;, pDriver);
	DbgPrint(&quot;PUNICODE_STRING-&gt;[%ws]\n&quot;, pReg-&gt;Buffer);

	// 定义内核字符串
	ANSI_STRING ansi;
	ANSI_STRING ansiDst = {0}; // 最好赋个初值
	UNICODE_STRING unicode;
	UNICODE_STRING str;

	// 定义普通字符串
	char* chr = &quot;Hello Kernel Test&quot;;
	wchar_t* wchr = (WCHAR*)L&quot;Hello Kernel Test&quot;;

	// 初始化字符串，有多种方式可以选择
	RtlInitAnsiString(&amp;ansi, chr);
	RtlInitUnicodeString(&amp;unicode, wchr);
	RtlInitUnicodeString(&amp;str, L&quot;Hello Kernel Test&quot;);

#if 0
	// 创建 MDL
	PMDL mdl = IoAllocateMdl(chr, strlen(chr) + 1, FALSE, FALSE, NULL);
	if (!mdl) {
		DbgPrint(&quot;Failed to allocate MDL.\n&quot;);
		return STATUS_INSUFFICIENT_RESOURCES;
	}

	// 锁定内存页
	MmBuildMdlForNonPagedPool(mdl);

	// 映射 MDL 到系统地址空间
	PVOID baseAddress = MmGetSystemAddressForMdlSafe(mdl, MdlMappingNoExecute);
	if (!baseAddress) {
		DbgPrint(&quot;Failed to map MDL to system address space.\n&quot;);
		IoFreeMdl(mdl);
		return STATUS_INSUFFICIENT_RESOURCES;
	}

	// 修改内存保护属性为可读写
	NTSTATUS status = MmProtectMdlSystemAddress(mdl, PAGE_READWRITE);
	if (!NT_SUCCESS(status)) {
		DbgPrint(&quot;Failed to change memory protection: %x\n&quot;, status);
		IoFreeMdl(mdl);
		return status;
	}
#endif

	// 改变原始字符串，看下效果，这里应该是不能修改的，编译后位于常量区，要修改必须先修改内存属性才可以。否则会报错
	KIRQL irql = WPOFFx64();
	// 修改字符串内容
	chr[0] = &#039;h&#039;; // 将 &#039;H&#039; 改为 &#039;h&#039;
	chr[6] = &#039;k&#039;; // 将 &#039;K&#039; 改为 &#039;k&#039;

	WPONx64(irql);


	// 打印
	DbgPrint(&quot;[*] 输出ANSI: %Z \n&quot;, &amp;ansi);
	DbgPrint(&quot;[*] 输出WCHAR: %Z \n&quot;, &amp;unicode);
	DbgPrint(&quot;[*] 输出字符串: %wZ \n&quot;, &amp;str);

	NTSTATUS flag = RtlUnicodeStringToAnsiString(&amp;ansiDst, &amp;unicode, TRUE);
	if (NT_SUCCESS(flag))
	{
		DbgPrint(&quot;[*] RtlUnicodeStringToAnsiString Called Print: %Z&quot;, &amp;ansiDst);
	}

	pDriver-&gt;DriverUnload = UnloadDriver;

	return STATUS_SUCCESS;
}

输出：

Hello World, Driver
PDRIVER_OBJECT-&gt; [0x0edcee30]
PUNICODE_STRING-&gt;[\REGISTRY\MACHINE\SYSTEM\ControlSet001\Services\KmdfString]
[*] 输出ANSI: hello kernel Test 
[*] 输出WCHAR: H
[*] 输出字符串: Hello Kernel Test 
[*] RtlUnicodeStringToAnsiString Called Print: Hello Kernel Test
Bye, Driver 

字符串和数字之间的转换
Demo2
Cc// #include &lt;ntddk.h&gt;

#include &lt;ntifs.h&gt;

NTSTATUS UnloadDriver(PDRIVER_OBJECT pDriver)
{
	DbgPrint(&quot;Bye, Driver\n&quot;);

	return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING pReg)
{
	DbgPrint(&quot;Hello World, Driver\n&quot;);
	DbgPrint(&quot;PDRIVER_OBJECT-&gt; [0x%08x]\n&quot;, pDriver);
	DbgPrint(&quot;PUNICODE_STRING-&gt;[%ws]\n&quot;, pReg-&gt;Buffer);


	UNICODE_STRING unicode_buffer_source = { 0 };
	UNICODE_STRING unicode_buffer_target = { 0 };

	// 字符串转为数字
	ULONG number;
	RtlInitUnicodeString(&amp;unicode_buffer_source, L&quot;100&quot;);
	NTSTATUS flag = RtlUnicodeStringToInteger(&amp;unicode_buffer_source, 10, &amp;number);

	if (NT_SUCCESS(flag))
	{
		DbgPrint(&quot;[*] 字符串 -&gt; 数字：%d \n&quot;, number);
	}

	// 数字转字符串
	unicode_buffer_target.Buffer = (PWSTR)ExAllocatePool(PagedPool, 1024);
	unicode_buffer_target.MaximumLength = 1024;

	flag = RtlIntegerToUnicodeString(number, 10, &amp;unicode_buffer_target);
	if (NT_SUCCESS(flag))
	{
		DbgPrint(&quot;[*] 数字 -&gt; 字符串：%wZ \n&quot;, unicode_buffer_target);
	}


	{
		RtlFreeUnicodeString(&amp;unicode_buffer_target);
	}

	pDriver-&gt;DriverUnload = UnloadDriver;
	return STATUS_SUCCESS;
}
输出：

Hello World, Driver
PDRIVER_OBJECT-&gt; [0x0b68a570]
PUNICODE_STRING-&gt;[\REGISTRY\MACHINE\SYSTEM\ControlSet001\Services\KmdfString2]
字符串 -&gt; 数字：100 
数字 -&gt; 字符串：100 
Bye, Driver

字符串拷贝和比较
UNICODE_STRING 和 ANSI_STRING 都是结构体，因此在使用上可以直接通过申请内存的方式来指定字符串的大小。

RtlInitEmptyUnicodeString
RtlCopyUnicodeString
RtlAppendUnicodeToString
RtlEqualUnicodeString

Demo3
Cc// #include &lt;ntddk.h&gt;

#include &lt;ntifs.h&gt;

NTSTATUS UnloadDriver(PDRIVER_OBJECT pDriver)
{
	DbgPrint(&quot;Bye, Driver\n&quot;);

	return STATUS_SUCCESS;
}

void StringCopyDemo()
{
	UNICODE_STRING dst;
	WCHAR dst_buf[256] = { 0 };
	NTSTATUS status;

	// 初始化字符串
	UNICODE_STRING src = RTL_CONSTANT_STRING(L&quot;Hello World!&quot;);

	// 字符串初始化为空，长度为256
	RtlInitEmptyUnicodeString(&amp;dst, dst_buf, 256 * sizeof(WCHAR));

	if (&amp;dst)
	{
		RtlCopyUnicodeString(&amp;dst, &amp;src);
	}

	// 在 dst 之后追加
	status = RtlAppendUnicodeToString(&amp;dst, L&quot;KernelTest&quot;);
	if (status == STATUS_SUCCESS)
	{
		DbgPrint(&quot;[*] 输出操作后的字符串：%wZ&quot;, &amp;dst);
	}
}

NTSTATUS DriverEntry(PDRIVER_OBJECT pDriver, PUNICODE_STRING pReg)
{
	DbgPrint(&quot;Hello World, Driver\n&quot;);
	DbgPrint(&quot;PDRIVER_OBJECT-&gt; [0x%08x]\n&quot;, pDriver);
	DbgPrint(&quot;PUNICODE_STRING-&gt;[%ws]\n&quot;, pReg-&gt;Buffer);

	UNICODE_STRING unicode_buffer = { 0 };
	UNICODE_STRING unicode_buffer_dst = { 0 };
	wchar_t* wchar_string = L&quot;Hello World! Kernel Test&quot;;

	// 初始化并分配
	RtlInitUnicodeString(&amp;unicode_buffer_dst, L&quot;Hello World! Kernel Test&quot;);

	// 设置最大长度
	unicode_buffer.MaximumLength = 1024;

	// 分配内存空间
	unicode_buffer.Buffer = (PWSTR)ExAllocatePool(PagedPool, 1024);

	// 设置字符长度，由于是宽字符，所以要*2
	unicode_buffer.Length = wcslen(wchar_string) * 2;

	// 保证缓冲区足够大，否则程序终止
	ASSERT(unicode_buffer.MaximumLength &gt;= unicode_buffer.Length);

	// 将 wchar_string 中的字符串拷贝到 uncode_buffer.Buffer
	RtlCopyMemory(unicode_buffer.Buffer, wchar_string, unicode_buffer.Length);

	// 设置字符串长度，并打印
	unicode_buffer.Length = wcslen(wchar_string) * 2;
	DbgPrint(&quot;[*] 输出字符串：%wZ \n&quot;, unicode_buffer);

	// 比较字符串是否相等
	if (RtlEqualUnicodeString(&amp;unicode_buffer, &amp;unicode_buffer_dst, TRUE))
	{
		DbgPrint(&quot;[*] 字符串相等&quot;);
	}
	else
	{
		DbgPrint(&quot;[*] 字符串不相等&quot;);
	}

	// 释放堆空间
	ExFreePool(unicode_buffer.Buffer);

	unicode_buffer.Buffer = NULL;
	unicode_buffer.MaximumLength = 0;
	unicode_buffer.Length = 0;

	pDriver-&gt;DriverUnload = UnloadDriver;

	return STATUS_SUCCESS;
}
输出：

Hello World, Driver
PDRIVER_OBJECT-&gt; [0x0fb6fa80]
PUNICODE_STRING-&gt;[\REGISTRY\MACHINE\SYSTEM\ControlSet001\Services\KmdfStringCopy]
[*] 输出字符串：Hello World! Kernel Test 
[*] 字符串相等
Bye, Driver

